
'use strict';const KEY='miguel_clinic_v02';const $=id=>document.getElementById(id);const init=()=>({version:2,day:1,phase:0,tab:'story',story:'intro',peace:55,tired:10,trust:0,supplies:8,coins:24,patients:0,visits:0,flags:{},records:[],messages:[],lastCase:null,toolsUsed:[],vacationDay:0,eventsSeen:[],villageSpot:"clinic",facilities:{},neighborStages:{},specialSeen:[],secondVacation:false});let s=init();const phases=['아침','낮','저녁','밤'];const safe=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function clamp(v){return Math.max(0,Math.min(100,v))}function modify(d={}){for(const k of ['peace','tired','trust'])if(d[k])s[k]=clamp(s[k]+d[k]);for(const k of ['supplies','coins'])if(d[k])s[k]=Math.max(0,s[k]+d[k]);save(false)}function record(t){if(!s.records.includes(t))s.records.unshift(t);s.records=s.records.slice(0,35)}function save(toast=true){try{localStorage.setItem(KEY,JSON.stringify(s));if(toast)alert('저장했습니다.')}catch(e){if(toast)alert('저장할 수 없습니다. 브라우저 저장 공간을 확인해 주세요.')}}function move(tab){s.tab=tab;save(false);render()}function next(){if(s.phase<3)s.phase++;else{s.phase=0;s.day++;modify({tired:-18,peace:5});s.flags={};s.lastCase=null;s.toolsUsed=[];record(`${s.day}일 차: 새로운 하루가 시작되었다.`)}save(false);render()}function done(k){return !!s.flags[k]}function use(k,delta){if(done(k))return false;s.flags[k]=true;modify(delta);return true}function button(label,cb,disabled=false){const b=document.createElement('button');b.textContent=label;b.disabled=disabled;b.addEventListener('click',cb);return b}function actionWrap(el,actions){const c=document.createElement('div');c.className='choices';actions.forEach(([label,fn,off])=>c.appendChild(button(label,fn,off)));el.appendChild(c)}
const intro={intro:{who:'내레이션',where:'백사구 외곽 정착촌',text:'미겔 코트리먼은 살아남았다.\n\n제5사관학교의 제로 사태와 제로 전담반을 지나, 그녀는 군을 떠났다.\n\n낡은 버스가 하얀 모래를 뒤로 흩뿌렸다. 미겔은 여행 가방을 들고 변방의 정착촌에 내렸다.',choices:[['마을을 바라본다','arrive']]},arrive:{who:'미겔',where:'마을 입구',text:'물통 하나를 두고 실랑이하는 주민들. 바람에 펄럭이는 천막. 먼지 쌓인 간판.\n\n“……나쁘지 않다.”',choices:[['진료소 열쇠를 꺼낸다','door']]},door:{who:'내레이션',where:'작은 무료 진료소',text:'문은 삐걱거렸고, 선반은 비어 있었다. 그러나 지붕은 멀쩡했다.\n\n미겔은 가방을 내려놓았다.\n\n이번에는 자신이 선택한 방식으로.',choices:[['진료소 문을 연다','first']]},first:{who:'첫 방문자',where:'진료소',text:'“선생님! 아버지가 죽어가요!”\n\n미겔이 즉시 고개를 든다.\n\n“제가 만든 요리를 어제부터 안 드세요!”',choices:[['의식과 호흡부터 확인한다','firstcheck'],['요리를 보여 달라고 한다','firstfood']]},firstcheck:{who:'미겔',where:'진료소',text:'“의식은? 호흡은?”\n\n“멀쩡하세요! 저한테 소리도 지르셨어요!”\n\n“……그럼 직접 상태를 확인하겠다.”',choices:[['아버지를 모셔 오게 한다','father']]},firstfood:{who:'미겔',where:'진료소',text:'그릇에는 정체불명의 보랏빛 덩어리가 담겨 있다.\n\n“……식사는 잠시 중단한다. 아버지는 어디에 있지?”',choices:[['아버지를 모셔 오게 한다','father']]},father:{who:'아버지',where:'진료소',text:'“난 멀쩡해. 저 녀석 요리가 문제지!”\n\n미겔은 직접 상태를 확인했다. 당장 우려할 만한 이상은 없었다.\n\n“의료적인 문제와 요리의 문제는 구분한다.”',choices:[['첫 진료를 기록한다','child']]},child:{who:'어린 환자',where:'진료소 · 오후',text:'문을 두드린 아이의 손에는 흙이 묻은 작은 찰과상이 있었다.\n\n“넘어졌어요. 엄마는 일하러 가셨어요.”',choices:[['상처를 확인하고 아이를 안심시킨다','childend']]},childend:{who:'미겔',where:'진료소',text:'“여기까지 잘 왔다.”\n\n상처를 확인하고 씻어 보호한 뒤, 필요한 안내를 했다.\n\n아이는 돌아가며 조그맣게 손을 흔들었다.',choices:[['진료소를 정리한다','night']]},night:{who:'다니엘 · 통신',where:'진료소 · 밤',text:'“코트리먼. 무사히 도착하셨습니까?”\n\n“그렇다. 오늘은 꽤 시끄러웠다.”\n\n“하하. 벌써 적응하고 계신 것 같습니다.”\n\n미겔은 창밖의 작은 불빛들을 바라보았다.',choices:[['첫날을 마무리한다','complete']]},complete:{who:'DAY 01 COMPLETE',where:'진료소 · 밤',text:'첫날이 끝났다.\n\n이상한 환자도 있었고, 작은 상처를 입은 아이도 있었다.\n\n그리고 먼 곳에서 익숙한 목소리가 들렸다.\n\n이제 진료소의 매일이 시작된다.',choices:[['자유 생활 시작하기','free']]}};
function story(){const el=$('main');if(s.story!=='free'){const n=intro[s.story]||intro.intro;el.innerHTML=`<div class="speaker">${safe(n.who)}</div><div class="dialogue">${safe(n.text)}</div>`;$('location').textContent=n.where;actionWrap(el,n.choices.map(([label,id])=>[label,()=>{if(id==='child'){modify({trust:8,tired:5});record('첫 진료: 요리 소동')}if(id==='night'){modify({trust:12,tired:10,peace:5});record('두 번째 진료: 아이의 찰과상')}if(id==='free'){s.phase=0;s.day=2;record('첫날 완료 · 진료소 자유 운영 시작')}s.story=id;save(false);render()}]));return} $('location').textContent='백사구 외곽 정착촌';el.innerHTML=`<h2 class="sectionTitle">${s.day}일 차 · ${phases[s.phase]}</h2><div class="dialogue">${dailyText()}</div><div class="notice">이제부터 원하는 활동을 선택할 수 있습니다. 각 시간대에는 주요 행동을 한 번 할 수 있고, 밤이 지나면 다음 날이 시작됩니다.</div>`;actionWrap(el,[['진료소로 이동',()=>move('clinic')],['마을을 둘러본다',()=>move('village')],['수첩을 확인한다',()=>move('journal')],['다음 시간대로',next]]);}
function dailyText(){const texts=['진료소 창으로 하얀 햇빛이 들어온다. 오늘은 누가 찾아올까?','마을 시장이 소란스럽다. 진료소 앞에도 발소리가 들린다.','바람이 조금 누그러졌다. 주민들이 하나둘 집으로 돌아간다.','작은 집들에 불빛이 켜진다. 다니엘에게서 연락이 올지도 모른다.'];return texts[s.phase]+(s.day===3&&s.phase===3?'\n\n창가에 놓인 빈 꽃병이 눈에 띈다. 누군가 꽃을 두고 간 모양이다. 미겔은 그것을 치우지 않는다.':s.day===6&&s.phase===2?'\n\n모래바람이 거세다. 진료소의 문을 일찍 닫고 쉬어도 괜찮을 것이다.':'')}
const cases=[{name:'선인장에게 미움받는 남자',claim:'“선생님, 제 선인장이 저를 공격했습니다!”',hint:'손가락에 작은 가시가 보인다.',correct:0,choices:['손의 상태를 살피고 가시와 상처를 확인한다','선인장에게 사과하라고 권한다','일단 아무 처치 없이 돌려보낸다'],result:['“식물은 이동하지 않는다. 손을 보여라.”\n환자는 얌전히 손을 내민다.','“그게 도움이 될까요?”\n“의학적 처치는 아니다.”','환자는 여전히 손가락을 붙잡고 있다. 다시 진료해야 할 것 같다.']},{name:'잠을 안 자는 청년',claim:'“이상해요! 몸이 축 처져요! 큰 병 아닐까요?”',hint:'전날 밤 거의 잠을 자지 않았다고 한다.',correct:1,choices:['무조건 운동량을 늘리라고 한다','수면과 다른 증상을 확인하고 필요 시 추가 평가한다','걱정하지 말라고만 한다'],result:['“지금 당장은 쉬는 편이 낫다.”','“수면부터 확인한다. 다른 증상도 말해라.”\n청년은 어젯밤 게임을 했다고 실토한다.','청년은 아직 걱정스러운 얼굴이다.']},{name:'체스를 두러 온 할아버지',claim:'“가슴이 답답해. 그런데 체스판은 있나?”',hint:'증상이 있다고 말하는 만큼 우선 상태 평가가 필요하다.',correct:2,choices:['체스부터 둔다','체스판을 내밀고 다음 환자를 부른다','증상과 위험 신호부터 확인한다'],result:['“체스는 진료 이후다.”\n할아버지가 못내 아쉬워한다.','할아버지는 체스 말을 정리하다 다시 가슴을 문지른다.','“좋아, 선생. 진료가 끝나면 한 판 어떤가?”']},{name:'일하느라 식사를 거른 상인',claim:'“어지러운 것 같기도 하고… 그냥 잠깐 쉬러 왔소.”',hint:'최근 식사와 수분 섭취가 불규칙했다.',correct:0,choices:['상태를 확인하고 원인과 위험 신호를 살핀다','바로 가게로 돌아가라고 한다','원인 확인 없이 단정한다'],result:['“잠깐 앉는다. 지금 상태부터 확인한다.”\n상인은 조용히 고개를 끄덕인다.','상인은 돌아서다가 잠시 벽을 짚는다.','“그런가…?”\n상인은 여전히 불안해한다.']},{name:'진료소가 궁금한 할머니',claim:'“무릎이 좀 뻐근해서 왔지. 차는 있나?”',hint:'반복되는 불편감이 있어 기본적인 확인이 필요하다.',correct:1,choices:['아무것도 묻지 않고 차만 내온다','무릎 상태와 일상 불편을 확인한 뒤 이야기를 듣는다','오늘은 문을 닫았다고 한다'],result:['“차는 진료가 끝난 뒤다.”\n할머니는 껄껄 웃는다.','“아이고, 꼼꼼하구먼. 다음엔 과자도 가져올게.”','“그럼 내일 다시 올게!”']}];
function clinic(){const el=$('main');el.innerHTML='<h2 class="sectionTitle">🩺 무료 진료소</h2>';if(s.story!=='free'){el.innerHTML+='<p>프롤로그를 완료하면 자유 진료를 시작할 수 있습니다.</p>';actionWrap(el,[['이야기로 돌아가기',()=>move('story')]]);return}if(s.lastCase){const c=cases[s.lastCase.i];el.innerHTML+=`<div class="speaker">환자 · ${safe(c.name)}</div><div class="dialogue">${safe(c.claim)}\n\n${safe(c.hint)}</div><p class="muted">1단계 · 진료 도구를 선택해 상태를 확인하세요. (게임용 단순화)</p>`;if(!s.lastCase.tool){const tools=[['🩺 청진기','stethoscope'],['🌡️ 체온계','thermometer'],['🧴 상처 처치 키트','wound'],['📋 문진표','history']];actionWrap(el,tools.map(([name,id])=>[name,()=>{s.lastCase.tool=id;s.toolsUsed.push(id);save(false);render()}]));return}const hints={stethoscope:'호흡과 흉부 증상을 확인한다. 청진만으로 모든 문제를 배제할 수는 없다.',thermometer:'체온을 확인했다. 열이 없더라도 다른 증상 확인이 필요하다.',wound:'상처 여부와 피부 상태를 살폈다. 필요한 경우 안전하게 처치한다.',history:'발생 시점, 동반 증상, 복용 약과 위험 신호를 질문했다.'};el.innerHTML+=`<div class="notice">${safe(hints[s.lastCase.tool])}</div><p class="muted">2단계 · 진료 방향을 선택하세요.</p>`;actionWrap(el,[...c.choices.map((label,i)=>[label,()=>resolveCase(i)]),['↩ 다른 도구 선택',()=>{s.lastCase.tool=null;save(false);render()}]]);return}el.innerHTML+=`<div class="dialogue">오늘의 진료 기록을 확인하고 환자를 맞이할 수 있습니다. 적절한 진료에는 마을 운영 지원금이 소액 적립됩니다. 환자에게 진료비를 받지 않습니다.\n\n남은 의료 물품: ${s.supplies}개\n오늘 진료: ${done('clinic')?'완료':'가능'}</div>`;actionWrap(el,[['환자 맞이하기 (의료 물품 1)',startCase,done('clinic')||s.supplies<1],['의료 물품 정리하기',()=>{if(use('organize',{tired:3,supplies:2})){record(`${s.day}일 차: 의료 물품 정리`);render()}},done('organize')],['쉬면서 진료 기록 읽기',()=>{if(use('clinicrest',{peace:5,tired:-6}))render()},done('clinicrest')],['이웃의 경과 확인하기',()=>move('neighbors')],['시간 보내기',next]]);}
function startCase(){if(s.supplies<1||done('clinic'))return;const idx=(s.day-2+s.phase)%cases.length;s.lastCase={i:idx,tool:null};save(false);render()}function resolveCase(i){if(!s.lastCase)return;const c=cases[s.lastCase.i];const tool=s.lastCase.tool;const good=i===c.correct;s.lastCase=null;s.flags.clinic=true;s.patients++;modify({supplies:-1,tired:9,trust:good?8:1,peace:good?2:-2,coins:good?3:1});record(`${s.day}일 차: ${c.name} · ${good?'적절한 대응':'추가 확인이 필요했던 진료'} · 도구 ${tool||'미사용'}`);s.messages.unshift(`${c.name}: ${c.result[i]}`);s.messages=s.messages.slice(0,15);save(false);const el=$('main');el.innerHTML=`<h2 class="sectionTitle">진료 결과</h2><div class="dialogue">${safe(c.result[i])}</div><p class="muted">${good?'환자가 안심하고 돌아갔습니다.':'다음에는 증상 확인과 안전한 평가를 우선해 보세요.'}</p>`;actionWrap(el,[['진료소로 돌아가기',()=>render()],['다음 시간대로',next]])}
function village(){const el=$('main');el.innerHTML='<h2 class="sectionTitle">🏘️ 백사구 마을</h2>';if(s.story!=='free'){el.innerHTML+='<p>첫날의 이야기를 완료한 뒤 마을을 자유롭게 탐방할 수 있습니다.</p>';return}el.innerHTML+='<div class="dialogue">낡은 천막 아래로 사람들이 오간다. 누구도 이곳을 특별하다고 생각하지 않는 듯하지만, 저마다 오늘을 열심히 살아간다.</div>';actionWrap(el,[['시장 구경하기',()=>{if(use('market',{peace:4,trust:2})){record(`${s.day}일 차: 시장 산책`);s.messages.unshift('시장 상인: “의사 선생님! 오늘은 물통 때문에 싸운 사람 없어요!”');render()}},done('market')],['의료 물품 사기 (6코인 → 3개)',()=>{if(s.coins<6)return;modify({coins:-6,supplies:3});record(`${s.day}일 차: 물품 구입`);render()},s.coins<6],['주민과 이야기하기',()=>{if(use('talk',{trust:4,tired:2})){s.messages.unshift('주민: “여긴 별거 없지만, 밤하늘은 예뻐요.”');render()}},done('talk')],['집에서 휴식하기',()=>{if(use('rest',{tired:-15,peace:7}))render()},done('rest')],['다니엘에게 연락하기',()=>{if(use('daniel',{peace:8})){s.messages.unshift(s.phase===3?'다니엘: “코트리먼, 오늘도 고생하셨습니다. 푹 쉬십시오.”':'다니엘: “코트리먼. 연락 주셔서 기쁩니다. 오늘은 어떠셨습니까?”');record(`${s.day}일 차: 다니엘과 연락`);render()}},done('daniel')],['🗺️ 마을 지도 보기',()=>move('map')],['💌 다니엘의 휴가 일정 확인',vacationEvent],['💌 두 번째 휴가 이야기 (8일 차)',secondVacationEvent],['💬 이웃 연속 이야기',()=>move('neighbors')],['🪑 진료소 시설 관리',()=>move('facilities')],['다음 시간대로',next]]);}

const spots=[{id:'clinic',name:'🩺 무료 진료소',desc:'미겔이 자신의 의지로 연 작은 진료소. 오늘도 문이 열려 있다.',action:'clinic'},{id:'market',name:'🧺 천막 시장',desc:'식료품과 약품이 오가는 소란스러운 골목.',action:'village'},{id:'well',name:'🚰 공동 급수대',desc:'주민들이 소식을 나누는 곳. 오늘도 물통을 두고 말다툼이 있다.',action:'well'},{id:'post',name:'✉️ 우편소',desc:'메인시티에서 편지와 물자가 도착하는 작은 우편소.',action:'post'},{id:'home',name:'🏠 미겔의 집',desc:'작은 침대와 차 한 잔. 여기서는 누구도 명령하지 않는다.',action:'home'}];
function map(){const el=$('main');$('location').textContent='백사구 · 정착촌 지도';el.innerHTML='<h2 class="sectionTitle">🗺️ 백사구 정착촌</h2><p class="muted">장소를 눌러 탐색하세요. 새 지역은 게임 확장 설정입니다.</p><div class="mapgrid"></div>';const g=el.querySelector('.mapgrid');spots.forEach(p=>{const b=button(p.name,()=>visitSpot(p));b.className='mapspot';g.appendChild(b)});el.innerHTML+='<div class="notice">마을은 작지만 이야기는 많다. 주민들의 삶은 미겔이 오기 전부터 계속되고 있었다.</div>'}
function visitSpot(p){s.villageSpot=p.id;save(false);if(p.action==='clinic'||p.action==='village'){move(p.action);return}const el=$('main');el.innerHTML=`<h2 class="sectionTitle">${safe(p.name)}</h2><div class="dialogue">${safe(p.desc)}</div>`;const acts=[];if(p.action==='post')acts.push(['다니엘에게 편지 보내기',()=>{if(use('postletter',{peace:5})){record(`${s.day}일 차: 다니엘에게 편지를 보냈다.`);s.messages.unshift('미겔: “D. 이곳은 꽤 시끄럽다. 하지만 나쁘지 않다.”')}render()},done('postletter')]);if(p.action==='well')acts.push(['주민의 소문 듣기',()=>{if(use('well',{trust:3})){s.messages.unshift('급수대 주민: “그 의사 선생님, 말수는 적어도 꼼꼼하더라.”');record(`${s.day}일 차: 급수대의 소문`)}render()},done('well')]);if(p.action==='home')acts.push(['집에서 쉬기',()=>{if(use('homerest',{tired:-12,peace:6}))record(`${s.day}일 차: 집에서 휴식`);render()},done('homerest')]);acts.push(['지도로 돌아가기',()=>move('map')]);actionWrap(el,acts)}
function vacationEvent(){const el=$('main');if(s.story!=='free'){el.innerHTML='<h2>다니엘의 휴가</h2><p>첫날을 완료하면 열립니다.</p>';return}const ready=s.day>=4;const already=s.eventsSeen.includes('vacation');el.innerHTML=`<h2 class="sectionTitle">💌 다니엘의 휴가</h2><div class="dialogue">${!ready?'다니엘은 아직 군 복무 중이다. 편지에는 다음 휴가에 관한 이야기가 적혀 있다. (4일 차부터 이벤트 개방)':already?'다니엘이 가져온 물품은 이미 진료소 선반에 가지런히 놓여 있다.':'“코트리먼! 휴가를 받았습니다!”\n\n문밖에는 양손 가득 짐을 든 다니엘이 서 있었다.\n\n미겔: “D. 세 개만 부탁했다.”\n다니엘: “……열두 개를 가져왔습니다.”\n미겔: “왜?”\n다니엘: “도움이 될 것 같아서…….”'}</div>`;const a=[];if(ready&&!already){a.push(['함께 물품 정리하기',()=>finishVacation('sort')],['진료소 문을 닫고 산책하기',()=>finishVacation('walk')]);}a.push(['마을로 돌아가기',()=>move('village')]);actionWrap(el,a)}
function finishVacation(type){if(s.eventsSeen.includes('vacation'))return;s.eventsSeen.push('vacation');modify(type==='sort'?{supplies:4,peace:7,tired:-4}:{peace:12,tired:-8});record(`${s.day}일 차: 다니엘의 첫 휴가 · ${type==='sort'?'물품 정리':'함께 산책'}`);s.messages.unshift(type==='sort'?'다니엘: “도움이 되었다면 다행입니다, 코트리먼.”':'다니엘: “오늘은 아무것도 하지 않으셔도 됩니다, 코트리먼.”');save(false);vacationEvent()}

function journal(){const el=$('main');el.innerHTML='<h2 class="sectionTitle">📒 진료소 수첩</h2>';el.innerHTML+=`<p>누적 진료 <b>${s.patients+2*(s.story==='free'?1:0)}</b>건 · 생활 ${s.day}일 차</p><h3>최근 기록</h3><div>${s.records.length?s.records.map(x=>`<div class="log">${safe(x)}</div>`).join(''):'아직 기록이 없습니다.'}</div><h3>최근 대화</h3><div>${s.messages.length?s.messages.map(x=>`<div class="log">${safe(x)}</div>`).join(''):'아직 대화가 없습니다.'}</div>`}
function updates(){const el=$('main');el.innerHTML='<h2 class="sectionTitle">⚙️ 개발 · 고도화 센터</h2><div class="dialogue">현재 버전: v0.5\n\n다음 업데이트를 요청할 때 사용할 개발 지시문을 복사할 수 있습니다. 이 버튼만으로 설치된 게임 코드가 자동 수정되지는 않습니다. 최신 ZIP 파일을 ChatGPT 대화에 첨부하고 요청을 보내 주세요.</div>';actionWrap(el,[['다음 버전 요청 문구 복사',async()=>{const msg='MIGUEL CLINIC 최신 ZIP의 docs/*.md를 먼저 읽고 기존 localStorage 키 miguel_clinic_v02와 version:2를 유지하며 v0.6을 개발해 주세요. 기존 스토리·저장 데이터·진료 기능을 유지하고, 환자 이벤트 확장, 진료 도구 상호작용, 마을 지도, 다니엘 휴가 이벤트를 고도화해 주세요. 결과는 GitHub 업로드용 ZIP 하나로 주세요.';try{await navigator.clipboard.writeText(msg);alert('요청 문구를 복사했습니다. 최신 ZIP과 함께 채팅에 붙여넣어 주세요.')}catch(e){prompt('아래 문구를 복사해 주세요.',msg)}}],['게임 데이터 내보내기',()=>{const blob=new Blob([JSON.stringify(s,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='miguel_clinic_save_v05.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}],['v0.1 원본 열기',()=>window.open('legacy_v01.html','_blank')]]);el.innerHTML+='<div class="notice">업데이트는 사용자의 명시적인 요청에 따라 새 ZIP으로 제공됩니다. 브라우저에서 플레이 중인 파일을 원격으로 자동 교체하지 않습니다.</div>'}
const improvements=[{id:'shelf',name:'튼튼한 약품 선반',cost:12,desc:'물품을 정리하고 재고를 확보한다.',reward:{supplies:5,peace:3}},{id:'chair',name:'대기실 의자',cost:15,desc:'환자들이 편히 기다릴 수 있다.',reward:{trust:6,peace:3}},{id:'curtain',name:'진료 공간 가림막',cost:18,desc:'작은 진료소에도 사생활은 중요하다.',reward:{trust:8}},{id:'lamp',name:'따뜻한 탁상등',cost:10,desc:'늦은 밤 진료 기록을 정리할 때 유용하다.',reward:{peace:8}},{id:'chess',name:'낡은 체스판 수선',cost:9,desc:'치료를 마친 뒤 가끔 체스를 둘 수 있다.',reward:{peace:5,trust:3}}];
function facilities(){const el=$('main');el.innerHTML='<h2 class="sectionTitle">🪑 진료소 시설</h2><div class="dialogue">작은 진료소를 조금씩 손본다. 무료 진료는 유지하고, 운영 자금으로 시설을 보완한다.</div>';if(s.story!=='free'){el.innerHTML+='<p class="muted">첫날을 마치면 열립니다.</p>';return}for(const it of improvements){const box=document.createElement('div');box.className='notice';box.innerHTML=`<b>${safe(it.name)}</b><br>${safe(it.desc)}<br><small>${s.facilities[it.id]?'설치 완료':`비용 ${it.cost}코인`}</small>`;actionWrap(box,[[s.facilities[it.id]?'설치 완료':'설치하기',()=>{if(s.facilities[it.id]||s.coins<it.cost)return;s.coins-=it.cost;s.facilities[it.id]=true;modify(it.reward);record(`${s.day}일 차: ${it.name} 설치`);save(false);render()},!!s.facilities[it.id]||s.coins<it.cost]]);el.appendChild(box)}actionWrap(el,[['진료소로 돌아가기',()=>move('clinic')]])}
const neighborsData=[{id:'cactus',name:'선인장과 화해하려는 남자',start:2,steps:[{title:'가시가 남긴 오해',text:'“선생님, 선인장이 또 저를 노려봅니다.”\n미겔: “선인장에 눈은 없다. 상처는 어떤가?”\n남자는 손가락을 내민다. 다행히 잘 아물고 있다.',choice:'상처 경과를 확인한다',delta:{trust:3}},{title:'화분을 옮긴 날',text:'남자는 화분을 창가로 옮겼다고 말한다.\n“그 사람이 남긴 거라 잘 키우고 싶었어요.”\n미겔: “그럼 식물에 맞는 환경을 확인한다. 손도 조심하고.”',choice:'식물 관리에 관해 이야기한다',delta:{trust:5,peace:3}},{title:'가시 없는 인사',text:'“이제 공격하지 않아요!”\n미겔: “움직이지 않는다는 점은 전과 같다.”\n남자가 웃으며 돌아간다.',choice:'진료를 마무리한다',delta:{trust:5}}]},{id:'sleep',name:'밤을 새우는 청년',start:3,steps:[{title:'잠 못 드는 이유',text:'청년은 게임을 하느라 밤을 샜다고 말하지만, 최근에는 자주 잠을 설친다고 덧붙인다.\n미겔: “생활을 확인한다. 불편이 계속되면 다시 온다.”',choice:'생활 패턴을 묻는다',delta:{trust:3}},{title:'오늘은 일찍 자겠습니다',text:'“어제는 네 시간이나 잤어요!”\n미겔: “그것도 충분하다고 단정할 수 없다.”\n청년은 민망하게 웃는다.',choice:'경과를 듣는다',delta:{trust:4}},{title:'정상적인 아침',text:'청년이 아침 시장에서 빵을 들고 인사한다.\n“이제 아침이 있다는 걸 알겠어요!”\n미겔: “원래 있었다.”',choice:'인사를 받는다',delta:{peace:4,trust:4}}]},{id:'merchant',name:'식사를 거르는 상인',start:4,steps:[{title:'잠깐 쉬는 의자',text:'상인이 다시 찾아와 잠시 앉아도 되냐고 묻는다.\n미겔: “앉는다. 증상은 어떤가?”\n상인은 시장의 분주함을 이야기한다.',choice:'상태를 확인한다',delta:{trust:4}},{title:'시장 사람들의 간식',text:'상인이 동료들이 챙겨 준 작은 도시락을 보여준다.\n“이 동네 사람들, 잔소리는 참 많다니까.”\n미겔: “그것은 식사다.”',choice:'함께 웃는다',delta:{trust:5,peace:3}}]},{id:'grandma',name:'차를 마시러 오는 할머니',start:5,steps:[{title:'무릎과 차',text:'할머니가 무릎 상태를 이야기한 뒤 차 한 잔을 청한다.\n미겔: “진료는 끝났다. 차는 있다.”\n“거봐, 좋은 의사라니까.”',choice:'차를 내온다',delta:{trust:4,peace:3}},{title:'마을의 오래된 이름들',text:'할머니는 정착촌의 오래된 가게와 이웃들에 대해 이야기한다.\n미겔은 얼굴보다 목소리와 말버릇으로 익숙한 사람들을 기억한다.',choice:'이야기를 듣는다',delta:{trust:5,peace:3}}]},{id:'chess',name:'체스 할아버지',start:6,steps:[{title:'진료 후 한 판',text:'할아버지가 진료를 마치고 체스판을 펼친다.\n미겔: “봐주지는 않는다.”\n“그걸 바랐겠나, 선생!”',choice:'진지하게 한 판 둔다',delta:{peace:5,trust:3}},{title:'판 밖의 오후',text:'말 하나가 바닥에 굴러 떨어진다. 미겔은 주워 제자리에 놓는다.\n전쟁을 떠올리던 체스판이 이제는 오후의 놀이가 될 수도 있다. [게임용 해석]',choice:'다음 수를 둔다',delta:{peace:6}}]}];
function neighbors(){const el=$('main');el.innerHTML='<h2 class="sectionTitle">💬 이웃들의 연속 이야기</h2><p class="muted">환자들의 후일담입니다. 각 인물의 다음 이야기는 하루에 한 번만 진행됩니다. 모든 대사는 게임용 신규 창작입니다.</p>';if(s.story!=='free'){el.innerHTML+='<p>첫날 이후 개방됩니다.</p>';return}for(const n of neighborsData){const stage=Math.max(0,Math.min(n.steps.length,Number(s.neighborStages[n.id])||0));const box=document.createElement('div');box.className='notice';box.innerHTML=`<b>${safe(n.name)}</b><br><small>${stage}/${n.steps.length}화 · ${s.day<n.start?'아직 만나지 않음':stage===n.steps.length?'이야기 완료':safe(n.steps[stage].title)}</small>`;const disabled=s.day<n.start||stage>=n.steps.length||done('neighbor_'+n.id);actionWrap(box,[[stage===n.steps.length?'완료':'이야기 듣기',()=>neighborEvent(n.id),disabled]]);el.appendChild(box)}actionWrap(el,[['마을로 돌아가기',()=>move('village')]])}
function neighborEvent(id){const n=neighborsData.find(x=>x.id===id);if(!n||s.day<n.start||done('neighbor_'+id))return;const stage=Number(s.neighborStages[id])||0;if(stage>=n.steps.length)return;const ev=n.steps[stage];const el=$('main');el.innerHTML=`<h2 class="sectionTitle">${safe(ev.title)}</h2><div class="dialogue">${safe(ev.text)}</div><p class="muted">[게임 확장] 원작 사건을 새로 발생시킨 것이 아닙니다.</p>`;actionWrap(el,[[ev.choice,()=>{s.neighborStages[id]=stage+1;s.flags['neighbor_'+id]=true;modify(ev.delta);record(`${s.day}일 차: ${n.name} · ${ev.title}`);save(false);neighbors()}],['나중에 듣기',neighbors]])}
function secondVacationEvent(){const el=$('main');const ready=s.story==='free'&&s.day>=8;el.innerHTML=`<h2 class="sectionTitle">💌 두 번째 휴가 · 느긋한 하루</h2><div class="dialogue">${!ready?'다니엘은 현역 군인이다. 다음 휴가 이야기는 8일 차부터 열린다.':s.secondVacation?'다니엘은 부대로 복귀했다. 진료소에는 조용한 오후의 기억이 남았다.':'다니엘이 진료소 문을 조심스레 두드린다.\n“코트리먼. 이번에는 부탁하신 만큼만 가져왔습니다!”\n미겔: “잘했다. D.”\n“……정말입니까?”\n“그렇다. 오늘은 쉬어도 된다.”'}</div><p class="muted">[게임 확장] 다니엘의 대사와 휴가 일정은 원작 확정이 아닌 게임용 제안입니다.</p>`;const acts=[];if(ready&&!s.secondVacation)acts.push(['함께 진료소를 정돈한다',()=>finishSecondVacation('tidy')],['함께 체스를 둔다',()=>finishSecondVacation('chess')]);acts.push(['마을로 돌아가기',()=>move('village')]);actionWrap(el,acts)}
function finishSecondVacation(kind){if(s.secondVacation)return;s.secondVacation=true;modify(kind==='tidy'?{supplies:3,peace:7}:{peace:12,tired:-5});record(`${s.day}일 차: 다니엘 두 번째 휴가 · ${kind==='tidy'?'진료소 정돈':'체스'}`);s.messages.unshift(kind==='tidy'?'다니엘: “다음에도 돕겠습니다, 코트리먼.”':'미겔: “D. 일부러 져주지는 않는다.”');save(false);secondVacationEvent()}
function stats(){const fields=[['안정감','peace'],['피로도','tired'],['마을 신뢰','trust']];$('stats').innerHTML=fields.map(([name,k])=>`<div class="statline"><span>${name}</span><span>${s[k]}/100</span></div><div class="meter"><span style="width:${s[k]}%"></span></div>`).join('')+`<div class="statline"><span>의료 물품</span><b>${s.supplies}</b></div><div class="statline"><span>운영 자금</span><b>${s.coins} 코인</b></div>`;$('sideNotes').innerHTML=`<div class="notice"><b>오늘의 활동</b><br>진료 ${done('clinic')?'완료':'대기'} · 마을 산책 ${done('market')?'완료':'가능'}<br><br><b>기록</b><br>${s.records.slice(0,3).map(safe).join('<br>')||'아직 없음'}</div>`}
function render(){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===s.tab));$('clock').textContent=`${s.day}일 차 · ${phases[s.phase]}`;stats();({story,clinic,village,map,journal,facilities,neighbors,updates}[s.tab]||story)()};document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>move(b.dataset.tab)));$('saveBtn').addEventListener('click',()=>save());$('resetBtn').addEventListener('click',()=>{if(confirm('현재 MIGUEL CLINIC 저장 데이터를 지우고 새로 시작할까요?')){s=init();save(false);render()}});try{const old=JSON.parse(localStorage.getItem(KEY));if(old&&old.version===2&&typeof old.day==='number'&&old.flags&&Array.isArray(old.records))s={...init(),...old,eventsSeen:Array.isArray(old.eventsSeen)?old.eventsSeen:[],toolsUsed:Array.isArray(old.toolsUsed)?old.toolsUsed:[],facilities:old.facilities&&typeof old.facilities==='object'?old.facilities:{},neighborStages:old.neighborStages&&typeof old.neighborStages==='object'?old.neighborStages:{},specialSeen:Array.isArray(old.specialSeen)?old.specialSeen:[],secondVacation:!!old.secondVacation}}catch(e){}

// v0.5 additive systems. Existing save key, version and v0.4 fields remain unchanged.
const v05Defaults=()=>({queueItems:[],queueDay:0,queueServed:[],lettersSent:[],lettersRead:[],furniturePositions:{},weatherNotices:[],scheduleVisits:[]});
function v05ensure(){for(const [k,v] of Object.entries(v05Defaults()))if(s[k]===undefined||s[k]===null)s[k]=Array.isArray(v)?[]:typeof v==='object'?{}:v;}
const weatherTypes=[{name:'맑음',icon:'☀️',desc:'하얀 모래 위로 햇빛이 반짝인다. 마을은 평소처럼 분주하다.'},{name:'옅은 바람',icon:'🌤️',desc:'천막이 바람에 흔들린다. 바깥 활동에 큰 지장은 없다.'},{name:'모래바람',icon:'🌬️',desc:'모래가 길을 덮는다. 주민들은 천막을 단단히 묶고, 이동을 줄인다.'},{name:'모래폭풍',icon:'🌪️',desc:'시야가 나빠지고 이동이 위험하다. 비응급 외출은 미루고 진료소 문을 닫아 두는 편이 안전하다.'}];
function weatherFor(day){return weatherTypes[(day%11===6||day%11===0)?3:(day%5===3?2:day%3===0?1:0)];}
const villageNPCs=[{id:'cactus',name:'선인장 환자',spot:'시장',times:[1,2],start:2,lines:['화분에 붙인 이름표가 바람에 날아갔습니다!','선생님, 선인장에게 말을 걸면 더 잘 자랄까요?']},{id:'sleep',name:'수면 부족 청년',spot:'급수대',times:[0,2],start:3,lines:['오늘은 일찍 자겠다고 약속했어요.','밤에 라디오를 듣다가 또 늦게 잤어요.']},{id:'grandma',name:'차 마시는 할머니',spot:'진료소',times:[0,1],start:2,lines:['차 한 잔 얻어 마셔도 되겠나?','오늘은 무릎보다 이야기가 더 고프구먼.']},{id:'chess',name:'체스 할아버지',spot:'우편소',times:[1,2],start:4,lines:['체스판을 고쳤다고? 이번엔 내가 이길 거야.','의사 양반은 봐주는 법이 없어서 좋다니까.']},{id:'merchant',name:'천막 상인',spot:'시장',times:[0,1],start:2,lines:['오늘도 물통 때문에 다툰 건 아닙니다!','천막을 고치려면 줄이 더 필요하겠군요.']}];
function presentNPCs(){return villageNPCs.filter(n=>s.day>=n.start&&n.times.includes(s.phase)&&((s.day+n.name.length)%4!==0));}
function queueCandidates(){const n=presentNPCs();return n.length?n:[villageNPCs[(s.day+s.phase)%villageNPCs.length]];}
function refreshQueue(){v05ensure();if(s.story!=='free')return;if(s.queueDay===s.day)return;s.queueDay=s.day;s.queueItems=queueCandidates().slice(0,3).map(n=>n.id);s.queueServed=[];save(false);}
function schedule(){v05ensure();const w=weatherFor(s.day);const el=$('main');$('location').textContent='백사구 · 오늘의 마을 소식';el.innerHTML=`<h2 class="sectionTitle">${w.icon} ${s.day}일 차 · ${safe(w.name)}</h2><div class="dialogue">${safe(w.desc)}</div><p class="muted">날씨는 게임용 일정표에 따라 바뀝니다. 실제 기상 예보가 아닙니다.</p><h3>지금 마을에 있는 주민</h3><div class="mini-grid">${presentNPCs().map(n=>`<div class="mini-card"><b>${safe(n.name)}</b><br><small>${safe(n.spot)}</small></div>`).join('')||'<div class="mini-card">지금은 거리가 한산하다.</div>'}</div>`;actionWrap(el,[['주민과 짧게 인사하기',()=>{const n=presentNPCs()[0];if(!n)return;if(use('greet_'+n.id,{peace:2,trust:1})){s.messages.unshift(`${n.name}: “${n.lines[s.day%2]}”`);record(`${s.day}일 차: ${n.name}과 인사`)}render()},!presentNPCs().length||done('greet_'+(presentNPCs()[0]||{}).id)],['환자 대기열 확인',()=>move('queue')],['다음 시간대로',next]]);}
function queue(){v05ensure();refreshQueue();const w=weatherFor(s.day),el=$('main');el.innerHTML=`<h2 class="sectionTitle">🧾 오늘의 환자 대기열</h2><p class="muted">${safe(w.name)} · 대기 ${s.queueItems.length}명 · 오늘 응대 ${s.queueServed.length}명</p><div class="notice">이 대기열은 기존의 자유 진료와 별도로 운영되는 예약·상담 시스템입니다. 무료 진료 원칙을 유지합니다. 모래폭풍 날에는 안전을 위해 비응급 방문이 줄어듭니다.</div>`;if(s.story!=='free'){el.innerHTML+='<p>프롤로그를 완료하면 열립니다.</p>';return}if(!s.queueItems.length){el.innerHTML+='<p>오늘 예정된 환자를 모두 만났습니다.</p>';return}for(const id of s.queueItems){const n=villageNPCs.find(n=>n.id===id);if(!n)continue;const b=document.createElement('div');b.className='mini-card';b.innerHTML=`<b>${safe(n.name)}</b><p>${safe(n.lines[s.day%2])}</p>`;actionWrap(b,[['상담 시작',()=>queueVisit(id),done('queueVisit')||w.name==='모래폭풍'],['방문을 내일로 미루기',()=>{s.queueItems=s.queueItems.filter(x=>x!==id);record(`${s.day}일 차: ${n.name}의 방문 일정 조정`);save(false);render()}]]);el.appendChild(b)}actionWrap(el,[['기존 진료 시스템으로 이동',()=>move('clinic')]]);}
function queueVisit(id){if(done('queueVisit')||weatherFor(s.day).name==='모래폭풍')return;const n=villageNPCs.find(x=>x.id===id);if(!n)return;const el=$('main');el.innerHTML=`<h2 class="sectionTitle">${safe(n.name)} · 상담</h2><div class="dialogue">${safe(n.lines[s.day%2])}\n\n미겔: “앉는다. 오늘은 어디가 불편하지?”</div><div class="notice">게임용 간이 상담입니다. 긴급한 증상은 실제 의료진의 평가가 필요합니다.</div>`;actionWrap(el,[['증상을 자세히 듣고 적절한 진료를 안내한다',()=>{s.flags.queueVisit=true;s.queueItems=s.queueItems.filter(x=>x!==id);s.queueServed.push(id);modify({trust:3,tired:3,coins:2});record(`${s.day}일 차: ${n.name} 예약 상담 완료`);save(false);move('queue')}],['대기열로 돌아가기',()=>move('queue')]]);}
const furniture=[{id:'shelf',name:'약품 선반',emoji:'🗄️'},{id:'chair',name:'대기 의자',emoji:'🪑'},{id:'curtain',name:'가림막',emoji:'🪟'},{id:'lamp',name:'탁상등',emoji:'💡'},{id:'chess',name:'체스판',emoji:'♟️'}];
function decorate(){v05ensure();const el=$('main');el.innerHTML='<h2 class="sectionTitle">🛋️ 진료소 가구 배치</h2><div class="notice">시설 메뉴에서 구입한 물건만 배치할 수 있습니다. 배치는 저장되며 시설 효과와 구입 기록은 그대로 유지됩니다.</div><div class="furniture-grid"></div>';const grid=el.querySelector('.furniture-grid');for(let i=0;i<6;i++){const item=furniture.find(x=>s.furniturePositions[x.id]===i&&s.facilities[x.id]);const cell=document.createElement('div');cell.className='furniture-slot';cell.innerHTML=item?`<span style="font-size:26px">${item.emoji}</span><b>${safe(item.name)}</b>`:`<span>＋</span><small>빈 자리 ${i+1}</small>`;const btn=button(item?'치우기':'배치',()=>{if(item){delete s.furniturePositions[item.id];save(false);render();return}const available=furniture.filter(x=>s.facilities[x.id]&&s.furniturePositions[x.id]===undefined);if(!available.length){alert('배치 가능한 가구가 없습니다. 시설 메뉴에서 구입해 주세요.');return}const name=prompt('배치할 가구 이름을 입력하세요:\n'+available.map(x=>x.name).join(', '),available[0].name);const chosen=available.find(x=>x.name===name);if(!chosen)return;s.furniturePositions[chosen.id]=i;save(false);render()});cell.appendChild(btn);grid.appendChild(cell)}actionWrap(el,[['시설 구입·업그레이드',()=>move('facilities')]]);}
const letters=[{day:2,title:'새로운 주소',body:'코트리먼. 그곳의 생활은 어떠십니까? 저는 여전히 군에서 맡은 일을 하고 있습니다. 다음에 찾아뵐 때는 마을 이야기를 들려주십시오.'},{day:5,title:'휴가 뒤에',body:'코트리먼. 지난 휴가에 뵙게 되어 기뻤습니다. 진료소가 조금씩 자리를 잡는 것 같아 다행입니다.'},{day:9,title:'작은 안부',body:'코트리먼. 바람이 거세다는 소식을 들었습니다. 무리하지 마시고 몸을 돌보십시오. 저는 잘 지내고 있습니다.'},{day:13,title:'다음에 만나면',body:'코트리먼. 다음에 뵈면 체스를 두고 싶습니다. 이번에도 진심으로 두겠습니다.'}];
function lettersUI(){v05ensure();const el=$('main');el.innerHTML='<h2 class="sectionTitle">✉️ 우편함 · 다니엘과의 연락</h2><div class="notice">[게임 확장] 편지 내용과 날짜는 새로 창작한 것으로, 다니엘 오너가 확정한 원작 대사가 아닙니다.</div>';for(const l of letters.filter(x=>s.day>=x.day)){const b=document.createElement('div');b.className='mini-card';b.innerHTML=`<b>${safe(l.title)}</b> <small>· ${l.day}일 차 도착</small><p>${s.lettersRead.includes(l.day)?safe(l.body):'봉투가 도착했다.'}</p>`;actionWrap(b,[[s.lettersRead.includes(l.day)?'읽음':'편지 읽기',()=>{if(!s.lettersRead.includes(l.day)){s.lettersRead.push(l.day);modify({peace:4});record(`${s.day}일 차: 다니엘의 편지 · ${l.title}`)}save(false);render()},s.lettersRead.includes(l.day)]]);el.appendChild(b)}if(s.day<2)el.innerHTML+='<p>아직 도착한 편지가 없습니다.</p>';actionWrap(el,[['다니엘에게 답장 쓰기',()=>{if(done('reply'))return;s.flags.reply=true;s.lettersSent.push(s.day);s.messages.unshift('미겔: “D. 오늘도 진료소는 소란스럽다. 나는 잘 지낸다.”');record(`${s.day}일 차: 다니엘에게 답장`);modify({peace:5});render()},done('reply')],['우편소로 가기',()=>visitSpot(spots.find(x=>x.action==='post'))]]);}
