function minigame(){v06ensure();const el=$('main');el.innerHTML='<h2 class="sectionTitle">🧩 오늘의 진료 미니게임</h2><div class="notice">[게임 확장] 실제 의료 진단이 아닌 가벼운 문진·관찰 게임입니다. 기존 자유 진료와 대기열은 그대로 이용할 수 있습니다. 하루 1회 완료 보상.</div>';
 if(s.story!=='free'){el.innerHTML+='<p>프롤로그 완료 후 이용할 수 있습니다.</p>';return}
 const a=s.v06ActiveMini;
 if(!a){for(const c of miniCases){const b=document.createElement('div');b.className='mini-card';b.innerHTML=`<b>${safe(c.name)}</b><p>${safe(c.scene)}</p>`;actionWrap(b,[['이 환자 진료하기',()=>{s.v06ActiveMini={id:c.id,step:0,score:0};save(false);render()}]]);el.appendChild(b)}return}
 const c=miniCases.find(x=>x.id===a.id);if(!c){s.v06ActiveMini=null;save(false);render();return}
 const st=c.steps[a.step];if(!st){s.v06ActiveMini=null;save(false);render();return}
 el.innerHTML+=`<h3>${safe(c.name)}</h3><div class="dialogue">${safe(c.scene)}</div><div class="game-steps"><span class="step-pill on">${a.step+1} / ${c.steps.length}단계</span><span class="step-pill">확인 점수 ${a.score}</span></div><h3>${safe(st.q)}</h3>`;
 actionWrap(el,st.options.map((o,i)=>[o,()=>{const ok=i===st.answer;a.score+=ok?1:0;const feedback=st.feedback+(ok?'\n\n차분하게 확인했습니다.':'\n\n환자를 다시 확인할 필요가 있겠습니다.');a.step++;if(a.step>=c.steps.length){const reward=!done('v06Mini');s.flags.v06Mini=true;s.v06MiniWins+=(a.score===c.steps.length?1:0);s.v06MiniHistory.unshift(`${s.day}일 차 · ${c.name} · ${a.score}/${c.steps.length}`);s.v06MiniHistory=s.v06MiniHistory.slice(0,30);if(reward)modify({trust:a.score===c.steps.length?4:1,peace:2,coins:2,tired:3});relGain(c.id,a.score===c.steps.length?6:2);record(`${s.day}일 차: 진료 미니게임 · ${c.name}`);s.v06ActiveMini=null;save(false);el.innerHTML=`<h2>진료 완료</h2><div class="dialogue">${safe(feedback)}</div><p>확인 점수 ${a.score}/${c.steps.length} · ${reward?'오늘의 보상 지급':'오늘의 보상은 이미 받았습니다'}</p>`;actionWrap(el,[['다른 환자 만나기',()=>render()]]);}else{save(false);el.innerHTML=`<h2>진료 진행</h2><div class="dialogue">${safe(feedback)}</div>`;actionWrap(el,[['다음 단계',()=>render()]])}}]));actionWrap(el,[['진료 중단',()=>{s.v06ActiveMini=null;save(false);render()}]])}
function visualRoom(){v06ensure();const el=$('main');el.innerHTML='<h2 class="sectionTitle">🛋️ 한눈에 보는 진료소</h2><p class="muted">기존 6칸 가구 배치 데이터를 그대로 사용합니다. 빈 칸을 누르면 배치할 가구를 선택할 수 있습니다.</p><div class="visual-room"></div>';const grid=el.querySelector('.visual-room');for(let i=0;i<6;i++){const it=furniture.find(x=>s.facilities[x.id]&&s.furniturePositions[x.id]===i);const tile=document.createElement('div');tile.className='room-tile';tile.innerHTML=it?`<strong>${it.emoji}</strong><span>${safe(it.name)}</span>`:`<strong>＋</strong><span>공간 ${i+1}</span>`;const b=button(it?'치우기':'배치하기',()=>{if(it){delete s.furniturePositions[it.id];save(false);render();return}const available=furniture.filter(x=>s.facilities[x.id]&&s.furniturePositions[x.id]===undefined);if(!available.length){alert('시설 메뉴에서 가구를 구입해 주세요.');return}const chooser=document.createElement('div');chooser.className='notice';chooser.textContent='배치할 가구를 선택하세요: ';for(const f of available)chooser.appendChild(button(f.emoji+' '+f.name,()=>{s.furniturePositions[f.id]=i;save(false);render()}));tile.appendChild(chooser)},false);tile.appendChild(b);grid.appendChild(tile)}actionWrap(el,[['시설 구매',()=>move('facilities')],['기존 배치 메뉴',()=>move('decorate')]])}
