function v07games(){v07ensure();const el=$('main');el.innerHTML='<h2 class="sectionTitle">🎯 새 진료 미니게임</h2><div class="notice">[게임 확장] 물품 분류·목소리 단서·안전 준비 게임입니다. 의료 진단을 대신하지 않습니다. 하루에 각 게임 1회 보상을 받을 수 있습니다.</div>';if(s.story!=='free'){el.innerHTML+='<p>프롤로그 이후 이용할 수 있습니다.</p>';return}
 const a=s.v07GameActive;if(!a){for(const g of v07Games){const b=document.createElement('div');b.className='v07-option';b.innerHTML=`<b>${safe(g.name)}</b><p>${safe(g.intro)}</p><small>${s.v07Played[g.id]===s.day?'오늘 완료':'오늘 플레이 가능'}</small>`;actionWrap(b,[['플레이',()=>{s.v07GameActive={id:g.id,step:0,score:0};save(false);render()}]]);el.appendChild(b)}return}
 const g=v07Games.find(x=>x.id===a.id);if(!g){s.v07GameActive=null;save(false);render();return}const q=g.questions[a.step];if(!q){s.v07GameActive=null;save(false);render();return}el.innerHTML+=`<h3>${safe(g.name)}</h3><div class="dialogue">${safe(g.intro)}</div><div class="v07-progress"><span style="width:${a.step/g.questions.length*100}%"></span></div><h3>${a.step+1}/${g.questions.length} · ${safe(q[0])}</h3>`;actionWrap(el,q[1].map((option,i)=>[option,()=>{a.score+=i===q[2]?1:0;a.step++;if(a.step>=g.questions.length){const first=s.v07Played[g.id]!==s.day;s.v07Played[g.id]=s.day;const score=a.score;s.v07GamesLog.unshift(`${s.day}일 차 ${g.name} · ${score}/${g.questions.length}`);s.v07GamesLog=s.v07GamesLog.slice(0,20);s.v07GameActive=null;if(first)modify({trust:score===3?4:1,coins:2,peace:2,tired:2});record(`${s.day}일 차: ${g.name} (${score}/3)`);save(false);el.innerHTML=`<h2>활동 완료</h2><div class="dialogue">${safe(g.person)}: “도와주셔서 감사합니다!”\n\n확인 ${score}/3 · ${first?'오늘의 지원금 2코인 지급':'오늘의 보상은 이미 지급되었습니다.'}</div>`;actionWrap(el,[['목록으로',()=>render()]])}else{save(false);render()}}]));actionWrap(el,[['중단',()=>{s.v07GameActive=null;save(false);render()}]])}
const v07Bonds={cactus:[{need:15,title:'선인장의 이름',text:'남자는 화분 이름표를 내민다. “선생님도 이름 하나 지어주시겠어요?”\n미겔: “이미 이름이 적혀 있다. 네가 고른 이름이다.”\n남자는 한참 웃다가 이름표를 다시 꽂는다.',choices:['이름표를 고쳐 준다','그대로 두도록 한다']},{need:35,title:'화분이 자란 만큼',text:'“선생님, 새 가시가 났어요!”\n미겔: “정상적인 성장이다.”\n“그러니까요. 저도 이제 알아요.”\n그는 작은 빈 화분을 진료소 창가에 놓고 간다.',choices:['고맙다고 말한다','창가 자리를 비운다']}],sleep:[{need:15,title:'두 시간에서 여섯 시간',text:'청년이 졸린 눈으로 웃는다. “어제는 게임을 끄고 일찍 누웠어요.”\n미겔: “그럼 오늘도 쉬어라.”',choices:['생활 기록을 칭찬한다','무리하지 말라고 한다']},{need:35,title:'낮의 심부름',text:'청년이 약품 상자를 옮겨 준다. “오늘은 깨어 있을 때 왔습니다!”\n미겔: “확인했다.”',choices:['고맙다고 말한다','물 한 잔을 건넨다']}],grandma:[{need:15,title:'차 한 잔의 이유',text:'할머니는 자신이 가져온 찻잎을 건넨다. “이제는 의사 선생님도 좀 앉아요.”\n미겔: “진료가 끝나면.”',choices:['잠깐 함께 앉는다','찻잎을 보관한다']},{need:35,title:'마을의 오래된 지도',text:'할머니가 오래된 손그림 지도를 펼친다. “여기 길은 내가 더 잘 알지.”\n미겔: “도움이 된다.”',choices:['지도를 수첩에 옮긴다','길 이야기를 듣는다']}],merchant:[{need:15,title:'무료 진료의 값',text:'상인이 작은 천을 내민다. “돈은 안 받는다면서요. 그럼 이건 그냥 선물!”\n미겔: “고맙다.”',choices:['선물을 받는다','필요한 사람과 나눈다']},{need:35,title:'천막 수선',text:'상인이 진료소의 낡은 차양을 고쳐 준다. “우리 마을 의사 선생님이잖아요.”\n미겔: “고맙다. 수고했다.”',choices:['차를 내온다','수선을 함께 확인한다']}],chess:[{need:15,title:'첫 번째 수',text:'할아버지가 체스판을 꺼낸다. “한 판만 하세.”\n미겔: “봐주지는 않는다.”\n“그걸 바랐겠나!”',choices:['정면으로 승부한다','다음 수를 기다린다']},{need:35,title:'체스판의 작은 흠',text:'할아버지는 낡은 체스판 모서리를 쓰다듬는다. “오래됐지만 아직 쓸 만해.”\n미겔: “그렇다. 충분하다.”',choices:['판을 닦아 준다','한 판 더 둔다']}]};
function v07bonds(){v07ensure();const el=$('main');el.innerHTML='<h2 class="sectionTitle">🎁 이웃 관계 전용 이야기</h2><p class="muted">[게임 확장] 관계 점수 15/35 이상에서 각 인물의 특별한 일상을 열 수 있습니다. 점수는 우정과 교류의 지표입니다.</p>';if(s.story!=='free'){el.innerHTML+='<p>프롤로그 이후 열립니다.</p>';return}for(const n of villageNPCs){const b=document.createElement('div');b.className='v07-option';b.innerHTML=`<b>${safe(n.name)}</b> · 교류 ${rel(n.id)}/100`;for(let i=0;i<(v07Bonds[n.id]||[]).length;i++){const ev=v07Bonds[n.id][i],key=n.id+'_'+i,seen=s.v07BondEvents.includes(key);const line=document.createElement('div');line.innerHTML=`<p>${seen?'✓ ':''}${safe(ev.title)} · ${ev.need} 이상</p>`;actionWrap(line,[[seen?'감상 완료':rel(n.id)<ev.need?'관계 단계 미달':'이야기 보기',()=>{if(seen||rel(n.id)<ev.need)return;const view=$('main');view.innerHTML=`<h2>${safe(ev.title)}</h2><div class="dialogue">${safe(ev.text)}</div><p class="muted">원작의 신규 공식 사건이 아닌 게임용 창작입니다.</p>`;actionWrap(view,ev.choices.map((choice,j)=>[choice,()=>{s.v07BondEvents.push(key);modify({peace:j?2:3,trust:2});record(`${s.day}일 차: ${ev.title}`);save(false);render()}]));},seen||rel(n.id)<ev.need]]);b.appendChild(line)}el.appendChild(b)}}
function v07room(){v07ensure();v05ensure();const el=$('main');el.innerHTML='<h2 class="sectionTitle">🏡 진료소 풍경</h2><p class="muted">v0.5의 6칸 배치 데이터와 v0.4의 구입 시설을 그대로 사용합니다. 방 테마만 별도 저장합니다.</p>';const themes=[['natural','따뜻한 목재'],['light','밝은 회벽'],['evening','노을빛']];const bar=document.createElement('div');bar.className='choices';for(const [id,name] of themes)bar.appendChild(button((s.v07DecorTheme===id?'✓ ':'')+name,()=>{s.v07DecorTheme=id;save(false);render()}));el.appendChild(bar);const room=document.createElement('div');room.className='v07-room';if(s.v07DecorTheme==='light')room.style.background='linear-gradient(#f6eee7 0 65%,#c7b9ac 65%)';if(s.v07DecorTheme==='evening')room.style.background='linear-gradient(#e8b9a6 0 65%,#ab8076 65%)';for(let i=0;i<6;i++){const it=furniture.find(x=>s.facilities[x.id]&&s.furniturePositions[x.id]===i),cell=document.createElement('div');cell.className='v07-tile';cell.innerHTML=`<strong>${it?it.emoji:'＋'}</strong><small>${it?safe(it.name):'빈 공간 '+(i+1)}</small>`;const choices=document.createElement('div');choices.className='choices';if(it)choices.appendChild(button('치우기',()=>{delete s.furniturePositions[it.id];save(false);render()}));else{const available=furniture.filter(x=>s.facilities[x.id]&&s.furniturePositions[x.id]===undefined);if(available.length)choices.appendChild(button('배치',()=>{cell.querySelector('.choices').replaceChildren(...available.map(f=>button(f.emoji+' '+f.name,()=>{s.furniturePositions[f.id]=i;save(false);render()})))}));}cell.appendChild(choices);room.appendChild(cell)}el.appendChild(room);actionWrap(el,[['시설 구입하기',()=>move('facilities')],['기존 배치 화면',()=>move('decorate')]])}
function v07seasons(){v07ensure();const [emoji,desc,cls]=v07SeasonData(),key=`${Math.floor((s.day-1)/7)}_${v07Season()}`;const el=$('main');el.innerHTML=`<h2 class="sectionTitle">🍂 사막 마을의 사계절</h2><div class="season-banner ${cls}"><h2>${emoji} ${v07Season()} · ${s.day}일 차</h2><p>${safe(desc)}</p><p>${weatherFor(s.day).icon} 오늘의 날씨: ${safe(weatherFor(s.day).name)}</p></div><p class="muted">[게임 확장] 7일 단위 계절 순환. 델하르사 공식 기후 주기가 아니라 게임 플레이용 연출입니다.</p>`;const stories={봄:['창가의 새싹','작은 잎이 흙을 뚫고 나온다. 미겔은 물의 양을 확인한다.','화분을 돌본다'],여름:['그늘을 나누는 오후','시장 상인이 진료소 차양 아래 의자를 가져다 둔다. 미겔은 물병을 건넨다.','함께 그늘을 만든다'],가을:['따뜻한 저녁의 기록','저녁 바람이 문틈으로 들어온다. 미겔은 오래된 기록을 정리하고 오늘의 진료 기록을 덧붙인다.','수첩을 정리한다'],겨울:['작은 난로의 온기','밤공기가 차갑다. 주민이 가져온 담요가 대기실 의자 위에 접혀 있다.','담요를 정리한다']};const ev=stories[v07Season()];el.innerHTML+=`<h3>${ev[0]}</h3><div class="dialogue">${ev[1]}</div>`;actionWrap(el,[[ev[2],()=>{if(s.v07SeasonSeen.includes(key))return;s.v07SeasonSeen.push(key);modify({peace:6,trust:2});record(`${s.day}일 차: ${ev[0]}`);save(false);render()},s.story!=='free'||s.v07SeasonSeen.includes(key)],['기존 날씨 이벤트',()=>move('weatherstory')]])}
const v07DanielEvents=[{id:'voice',day:3,title:'목소리 하나',text:'진료소 문밖에서 익숙한 발소리가 들린다. 그러나 문을 연 사람은 우편배달부다.\n\n그날 밤, 전화기 너머에서 다니엘이 말한다.\n다니엘: “코트리먼, 오늘은 어떠셨습니까?”\n미겔: “시끄러웠다. 나쁘지 않았다.”',choices:[['오늘의 환자 이야기를 들려준다',{peace:5}],['그의 하루를 묻는다',{peace:4,trust:1}]]},{id:'chess',day:9,title:'승부는 승부',text:'휴가를 맞은 다니엘이 낡은 체스판을 정리한다.\n다니엘: “이번에는 조금 봐주실 수 없겠습니까?”\n미겔: “없다.”\n다니엘: “그럴 줄 알았습니다.”\n미겔은 기물을 정중앙에 놓는다. 이기는 일과 사랑하는 일은 별개다.',choices:[['정식으로 한 판 둔다',{peace:7}],['차를 마시고 다시 둔다',{peace:6,tired:-3}]]},{id:'flower',day:13,title:'꽃을 꽂는 손',text:'다니엘의 편지 옆에 작은 꽃병이 놓여 있다. 미겔은 말없이 물을 갈고, 꽃잎이 꺾이지 않게 줄기를 고쳐 놓는다.\n\n어떤 것은 특별한 이유가 없어도 곁에 두고 싶다.',choices:[['창가에 놓는다',{peace:6}],['편지 옆에 둔다',{peace:6}]]},{id:'dayoff',day:17,title:'아무 일도 없는 휴일',text:'다니엘은 잠시 부대를 떠나 방문했다. 환자도 없고, 급한 편지도 없다.\n다니엘: “코트리먼, 오늘은 뭘 하실 겁니까?”\n미겔: “쉰다.”\n다니엘: “……저도 함께 쉬어도 됩니까?”\n미겔: “그렇다, D.”',choices:[['함께 산책한다',{peace:9,tired:-4}],['진료소에서 차를 마신다',{peace:9}]]}];
function v07daniel(){v07ensure();const el=$('main');el.innerHTML='<h2 class="sectionTitle">💌 두 사람의 하루</h2><div class="notice">[게임 확장] 원작의 사랑·체스·꽃·목소리 모티프를 바탕으로 한 신규 장면입니다. 다니엘의 대사는 오너가 확정한 원문이 아닙니다. 그는 현역 군인으로 휴가 때만 방문합니다.</div>';for(const ev of v07DanielEvents){const b=document.createElement('div');b.className='v07-option';b.innerHTML=`<b>${safe(ev.title)}</b><p>${s.day<ev.day?ev.day+'일 차부터 열립니다.':s.v07DanielSeen.includes(ev.id)?'✓ 이미 함께한 하루':'오늘의 기억을 열어 보세요.'}</p>`;actionWrap(b,[['이야기 보기',()=>{if(s.story!=='free'||s.day<ev.day||s.v07DanielSeen.includes(ev.id))return;const view=$('main');view.innerHTML=`<h2>${safe(ev.title)}</h2><div class="dialogue">${safe(ev.text)}</div><p class="muted">[게임 확장 · 신규 대사]</p>`;actionWrap(view,ev.choices.map(([label,delta])=>[label,()=>{s.v07DanielSeen.push(ev.id);modify(delta);record(`${s.day}일 차: ${ev.title}`);save(false);render()}]));},s.story!=='free'||s.day<ev.day||s.v07DanielSeen.includes(ev.id)]]);el.appendChild(b)}}
