const box=document.createElement('div');box.className='v10-board';const tasks=[['open','🧹 문 열고 진료 준비','아침·낮','준비를 마쳤다.','진료 준비',{tired:2,peace:1}],['care','🩺 오늘의 진료 확인','낮·저녁','환자 기록을 확인했다.','환자 기록 정리',{trust:2,tired:3}],['rest','🍵 잠시 쉬기','언제든','자신을 위한 시간을 남겨 두었다.','자기 돌봄',{peace:7,tired:-10}],['close','🌙 진료소 마감','저녁·밤','오늘도 문을 닫는다.','진료소 마감',{peace:3,tired:-4}]];
for(const [key,label,when,desc,rec,delta] of tasks){const doneToday=!!s.v10Daily[s.day+'_'+key];const valid=key==='open'?s.phase<=1:key==='care'?s.phase>=1&&s.phase<=2:key==='close'?s.phase>=2:true;const card=document.createElement('div');card.className='v10-tile';card.innerHTML=`<b>${label}</b><p class="v10-small">${when} · ${doneToday?'✓ 완료':desc}</p>`;actionWrap(card,[[doneToday?'오늘 완료':'진행하기',()=>{if(v10Mark(key,delta,rec))v10Dashboard()},!free||doneToday||!valid]]);box.appendChild(card)}el.appendChild(box);
