function v11ensure(){
 if(!s.v11||typeof s.v11!=='object'||Array.isArray(s.v11))s.v11={};
 const v=s.v11;
 if(!v.recovery||typeof v.recovery!=='object'||Array.isArray(v.recovery))v.recovery={};
 if(!v.stock||typeof v.stock!=='object'||Array.isArray(v.stock))v.stock={};
 if(!v.actions||typeof v.actions!=='object'||Array.isArray(v.actions))v.actions={};
 if(!Array.isArray(v.seasons))v.seasons=[];
 if(!Array.isArray(v.daniel))v.daniel=[];
 if(!v.choices||typeof v.choices!=='object')v.choices={};
 if(!Number.isFinite(v.budgetSpent))v.budgetSpent=0;
 // This is a separate stock ledger; legacy v07Medicine and s.supplies are never overwritten.
 for(const [id,n] of Object.entries({bandage:4,disinfectant:4,gloves:6,water:5}))if(!Number.isFinite(v.stock[id]))v.stock[id]=n;
 for(const p of v11Patients){const r=v.recovery[p.id];if(!r||typeof r!=='object')v.recovery[p.id]={stage:0,lastDay:0,notes:[]};else{r.stage=Math.max(0,Math.min(3,Number(r.stage)||0));r.lastDay=Number(r.lastDay)||0;if(!Array.isArray(r.notes))r.notes=[];}}
}
function v11Day(){return s.story==='free'&&s.day>=2}
function v11Season(){const n=Math.floor(Math.max(0,s.day-2)/7)%4;return ['spring','summer','autumn','winter'][n]}
function v11UseOnce(key){v11ensure();const k=s.day+'_'+key;if(s.v11.actions[k])return false;s.v11.actions[k]=true;return true}
function v11Recovery(){v11ensure();const el=$('main');el.innerHTML='<h2 class="sectionTitle">🩺 이웃들의 회복 수첩</h2><div class="notice">[게임 확장] 재방문은 최소 2일 간격으로 진행됩니다. 의학적 처치를 흉내 내는 시스템이 아니라 이웃의 경과를 듣는 서사형 콘텐츠입니다. 기존 진료 기록은 그대로 보존됩니다.</div>';
 const grid=document.createElement('div');grid.className='v11-grid';for(const p of v11Patients){const r=s.v11.recovery[p.id],done=r.stage===3,can=v11Day()&&!done&&(r.lastDay===0||s.day-r.lastDay>=2);const card=document.createElement('article');card.className='v11-card';card.innerHTML=`<h3>${safe(p.name)}</h3><p class="v11-note">${safe(p.symptom)}</p><div class="v11-meter" role="progressbar" aria-label="${safe(p.name)} 회복 단계" aria-valuenow="${r.stage}" aria-valuemin="0" aria-valuemax="3"><span style="width:${r.stage/3*100}%"></span></div><p>${r.stage}/3 단계 · ${done?'경과 확인 완료':r.lastDay?'다음 방문 '+(r.lastDay+2)+'일 차부터':'첫 경과 상담 가능'}</p><p>${safe(done?p.finish:p.lines[r.stage])}</p>`;
 const buttons=document.createElement('div');buttons.className='v11-buttons';buttons.appendChild(button(done?'✓ 이야기 완료':r.stage?'다시 진료하기':'첫 경과 확인',()=>{if(!can)return;r.notes.push({day:s.day,text:p.lines[r.stage]});r.stage++;r.lastDay=s.day;modify({trust:2,tired:2,peace:1});record(`${s.day}일 차: ${p.name} 경과 상담 ${r.stage}/3`);save(false);v11Recovery()},!can));card.appendChild(buttons);if(r.notes.length)card.insertAdjacentHTML('beforeend',`<p class="v11-note">최근 기록: ${safe(r.notes[r.notes.length-1].day+'일 차 · '+r.notes[r.notes.length-1].text)}</p>`);grid.appendChild(card)}el.appendChild(grid);
}
const v11Goods=[['bandage','🩹 붕대',3,2],['disinfectant','🧴 소독 용품',4,2],['gloves','🧤 장갑',3,3],['water','💧 식수',2,3]];
function v11Economy(){v11ensure();const el=$('main');el.innerHTML=`<h2 class="sectionTitle">📦 물자·지원금 관리</h2><div class="notice">무료 진료 원칙을 유지합니다. 물품 구입은 기존 운영 지원금(코인)을 사용하며, 주민에게 진료비를 청구하지 않습니다. 기존 공용 물품과 v0.7 개별 약품 재고는 별도로 유지됩니다.</div><div class="v11-banner">🪙 운영 지원금 <strong>${s.coins}</strong> · 🧰 기존 공용 물품 <strong>${s.supplies}</strong><p class="v11-note">신규 물자 지출 누적 ${s.v11.budgetSpent}코인 · 신규 재고는 이 화면에서만 사용됩니다.</p></div>`;
 const grid=document.createElement('div');grid.className='v11-grid';for(const [id,name,price,qty] of v11Goods){const card=document.createElement('article');card.className='v11-card';card.innerHTML=`<h3>${name}</h3><p>현재 ${s.v11.stock[id]}개 · ${price}코인으로 ${qty}개 보충</p>`;const acts=document.createElement('div');acts.className='v11-buttons';acts.appendChild(button('물품 보충',()=>{if(s.coins<price)return;s.coins-=price;s.v11.stock[id]+=qty;s.v11.budgetSpent+=price;record(`${s.day}일 차: ${name} ${qty}개 보충`);save(false);v11Economy()},!v11Day()||s.coins<price));acts.appendChild(button('물품 점검 (하루 1회)',()=>{if(s.v11.stock[id]<1||!v11UseOnce('inspect_'+id))return;s.v11.stock[id]--;modify({trust:1,peace:1});record(`${s.day}일 차: ${name} 물품 점검`);save(false);v11Economy()},!v11Day()||s.v11.stock[id]<1||!!s.v11.actions[s.day+'_inspect_'+id]));card.appendChild(acts);grid.appendChild(card)}el.appendChild(grid);
 const note=document.createElement('div');note.className='v11-card';note.innerHTML='<h3>운영 지원 요청</h3><p>마을의 작은 후원과 행정 지원을 요청합니다. 하루 한 번 가능하며, 지원 여부는 게임용 운영 규칙입니다.</p>';actionWrap(note,[['지원 요청 (+4코인)',()=>{if(!v11Day()||!v11UseOnce('grant'))return;s.coins+=4;record(`${s.day}일 차: 운영 지원금 4코인`);save(false);v11Economy()},!v11Day()||!!s.v11.actions[s.day+'_grant']]]);el.appendChild(note);
}
function v11SeasonUI(){v11ensure();const el=$('main');const season=v11Season(),ev=v11SeasonEvents.find(x=>x.id===season);const cycle=Math.floor(Math.max(0,s.day-2)/28);const key=cycle+'_'+season;const seen=s.v11.seasons.includes(key);el.innerHTML=`<h2 class="sectionTitle">${ev.emoji} 마을의 사계절</h2><div class="v11-banner"><b>${safe(ev.title)}</b><p>7일마다 계절이 바뀌는 게임용 달력입니다. 실제 델하르사 기후나 원작 공식 축제 설정은 아닙니다.</p></div><div class="v11-card"><p>${seen?'이번 계절의 행사를 이미 즐겼습니다.':'이번 계절에 열리는 작은 행사입니다.'}</p></div>`;actionWrap(el,[['행사 참여',()=>{if(!v11Day()||seen)return;const box=document.createElement('div');box.className='v11-card';box.innerHTML=`<h3>${safe(ev.title)}</h3><p>${safe(ev.text)}</p>`;actionWrap(box,ev.choices.map(c=>[c,()=>{s.v11.seasons.push(key);s.v11.choices['season_'+key]=c;modify({peace:5,trust:3});record(`${s.day}일 차: ${ev.title} · ${c}`);save(false);v11SeasonUI()}]));el.appendChild(box)},!v11Day()||seen]]);
}
function v11DanielUI(){v11ensure();const el=$('main');el.innerHTML='<h2 class="sectionTitle">💜 다니엘 · 일상의 조각</h2><div class="notice">[원작 확정] 두 사람은 연인이며 다니엘은 현역 군인입니다. [게임 확장] 날짜, 편지, 휴가, 대사는 모두 신규 창작이며 원작 공식 로그가 아닙니다.</div>';const grid=document.createElement('div');grid.className='v11-grid';for(const ev of v11Daniel){const seen=s.v11.daniel.includes(ev.id),can=v11Day()&&s.day>=ev.day;const card=document.createElement('article');card.className='v11-card';card.innerHTML=`<h3>${ev.type==='휴가'?'🏡':'✉️'} ${safe(ev.title)}</h3><p>${seen?'✓ 완료':can?'이야기를 읽을 수 있습니다.':ev.day+'일 차부터 개방'}</p>`;actionWrap(card,[['이야기 보기',()=>{card.innerHTML=`<h3>${safe(ev.title)}</h3><p>${safe(ev.text)}</p>`;actionWrap(card,ev.choices.map(c=>[c,()=>{if(s.v11.daniel.includes(ev.id))return;s.v11.daniel.push(ev.id);s.v11.choices['daniel_'+ev.id]=c;modify({peace:5,tired:-2});record(`${s.day}일 차: 다니엘 · ${ev.title}`);save(false);v11DanielUI()}]))},!can||seen]]);grid.appendChild(card)}el.appendChild(grid)}
const v11PriorRender=render;render=function(){v11ensure();v11PriorRender();const screens={v11recovery:v11Recovery,v11economy:v11Economy,v11seasons:v11SeasonUI,v11daniel:v11DanielUI};if(screens[s.tab])screens[s.tab]()};
