function v12Actions(el,items){const r=document.createElement('div');r.className='v12-actions';for(const [label,fn,disabled] of items)r.appendChild(button(label,fn,!!disabled));el.appendChild(r)}
function v12Village(){v12ensure();const el=$('main');el.innerHTML='<h2 class="sectionTitle">🏘️ 이웃들이 바꾼 정착촌</h2><div class="notice">[게임 확장] v1.1 장기 회복 단계가 마을의 작은 변화로 이어집니다. 기존 진료 기록·주민 친밀도·계절 행사 진행은 변경하지 않습니다.</div>';const grid=document.createElement('div');grid.className='v12-grid';for(const a of v12Community){const unlocked=v12Unlocked(a);const c=document.createElement('article');c.className='v12-card';c.innerHTML=`<h3>${a.emoji} ${safe(a.title)}</h3><p class="v12-tag">${safe(a.place)} · ${unlocked?'변화 발생':'회복 상담 2단계부터'}</p><p>${safe(unlocked?a.desc:'환자의 회복 수첩을 진행하면 이곳에 새로운 이야기가 생깁니다.')}</p>`;if(unlocked)v12Actions(c,[['이웃의 이야기 듣기',()=>{c.insertAdjacentHTML('beforeend',`<p role="status">${safe(a.line)}</p>`);const key='village_'+a.id;if(!s.v12.community[key]){s.v12.community[key]=s.day;record(`${s.day}일 차: ${a.title}`);save(false)}},!v11Day()]]);grid.appendChild(c)}el.appendChild(grid)}
function v12Balance(){v12ensure();v11ensure();const el=$('main');const goods=v11Goods;const low=goods.filter(([id])=>s.v11.stock[id]<2);const spent=s.v11.budgetSpent;const dayKey='support_'+s.day;const can=v11Day()&&!s.v12.daily[dayKey];el.innerHTML=`<h2 class="sectionTitle">⚖️ 무료 진료소 운영 균형</h2><div class="notice">기존 코인·공용 물품·v0.7 약품·v1.1 물자 장부를 그대로 사용합니다. 무료 진료 원칙은 유지되며 물자 소비는 여기서 선택할 때만 발생합니다.</div><div class="v12-grid"><div class="v12-card"><h3>🪙 운영 지원금</h3><p>${s.coins}코인 · 누적 지출 ${spent}코인</p><p class="v12-tag">하루 운영 지원 요청은 v1.1 물자 경제 메뉴에서 계속 이용할 수 있습니다.</p></div><div class="v12-card"><h3>📦 부족한 물자</h3><p>${low.length?low.map(x=>x[1]).join(' · '):'현재 긴급 보충 대상 없음'}</p><p class="v12-tag">2개 미만이면 보충을 권장합니다.</p></div><div class="v12-card"><h3>🤝 이웃의 작은 후원</h3><p>장기 회복 상담을 마친 이웃이 늘면 하루 한 번 물품 후원을 받을 수 있습니다. 후원은 진료비가 아닙니다.</p></div></div>`;const done=v12Community.filter(a=>v12Unlocked(a)).length;const c=document.createElement('div');c.className='v12-card';c.innerHTML=`<h3>오늘의 이웃 후원</h3><p>회복 2단계 이상 이웃 ${done}/5명 · 오늘 ${s.v12.daily[dayKey]?'수령 완료':'아직 수령하지 않음'}</p>`;v12Actions(c,[['후원 물품 받기',()=>{if(!can||done<1)return;s.v12.daily[dayKey]=true;const amount=Math.min(3,done);s.v11.stock.water+=amount;s.v12.totalGrant+=amount;record(`${s.day}일 차: 주민 후원 식수 ${amount}개`);save(false);v12Balance()},!can||done<1],['기존 물자 경제 열기',()=>move('v11economy'),false]]);el.appendChild(c);const ledger=document.createElement('div');ledger.className='v12-card';ledger.innerHTML='<h3>현재 물자 장부</h3>';for(const [id,name] of goods){const n=s.v11.stock[id];ledger.insertAdjacentHTML('beforeend',`<p>${name} ${n}개</p><div class="v12-bar" role="progressbar" aria-label="${safe(name)} 재고" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="12"><span style="width:${Math.min(100,n/12*100)}%"></span></div>`)}el.appendChild(ledger)}
function v12Festival(){v12ensure();const el=$('main');const ev=v11SeasonEvents.find(x=>x.id===v11Season());const people=villageNPCs.filter(n=>s.day>=n.start&&n.times.includes(s.phase));el.innerHTML=`<h2 class="sectionTitle">🎪 계절 행사와 주민 일정</h2><div class="notice">${s.day}일 차 · ${phases[s.phase]} · [게임 확장] 7일 주기의 계절 행사를 기존 주민 시간표와 함께 보여 줍니다. 공식 델하르사 기후나 축제가 아닙니다.</div><div class="v12-card"><h3>${ev.emoji} ${safe(ev.title)}</h3><p>현재 시간대에 만날 수 있는 주민: ${people.length}명</p></div>`;const map=document.createElement('div');map.className='v12-map';for(const place of ['진료소','시장','급수대','우편소']){const c=document.createElement('section');c.className='v12-location';const list=people.filter(n=>n.spot===place);c.innerHTML=`<h3>📍 ${safe(place)}</h3><p>${list.length?list.map(n=>safe(n.name)).join(' · '):'지금은 조용합니다.'}</p>`;map.appendChild(c)}el.appendChild(map);v12Actions(el,[['기존 계절 행사 참여',()=>move('v11seasons'),false],['주민 일정 자세히 보기',()=>move('v09npc'),false]])}
function v12Daniel(){v12ensure();const el=$('main');el.innerHTML='<h2 class="sectionTitle">💜 다니엘 · 작은 안부</h2><div class="notice">[원작 확정] 연인 관계, 다니엘의 현역 군 복무, 호칭 코트리먼·D. [게임 확장] 아래 일정·대사·선택지는 공식 로그가 아닌 신규 창작입니다. 다니엘의 내면이나 과거를 확정하지 않습니다.</div>';const grid=document.createElement('div');grid.className='v12-grid';for(const ev of v12Stories){const seen=s.v12.stories.includes(ev.id),can=v11Day()&&s.day>=ev.day;const c=document.createElement('article');c.className='v12-card';c.innerHTML=`<h3>✉️ ${safe(ev.title)}</h3><p>${seen?'✓ 읽음':can?'새 이야기':'개방: '+ev.day+'일 차'}</p>`;v12Actions(c,[['이야기 읽기',()=>{c.innerHTML=`<h3>${safe(ev.title)}</h3><p>${safe(ev.text)}</p>`;v12Actions(c,ev.choices.map(choice=>[choice,()=>{if(s.v12.stories.includes(ev.id))return;s.v12.stories.push(ev.id);s.v12.choices[ev.id]=choice;modify({peace:3});record(`${s.day}일 차: 다니엘 · ${ev.title}`);save(false);v12Daniel()}]))},!can||seen]]);grid.appendChild(c)}el.appendChild(grid)}
const v12PreviousRender=render;render=function(){v12ensure();v12PreviousRender();const screens={v12village:v12Village,v12balance:v12Balance,v12festival:v12Festival,v12daniel:v12Daniel};if(screens[s.tab])screens[s.tab]()};
for(const [id,label] of [['v12village','🏘️ 마을 변화'],['v12balance','⚖️ 운영 균형'],['v12festival','🎪 행사 일정'],['v12daniel','💜 작은 안부']]){const b=document.createElement('button');b.dataset.tab=id;b.textContent=label;b.addEventListener('click',()=>move(id));document.querySelector('nav.tabs').insertBefore(b,document.querySelector('[data-tab="updates"]'))}
const v12PreviousUpdates=updates;updates=function(){v12PreviousUpdates();const el=$('main');el.insertAdjacentHTML('beforeend','<div class="notice"><b>v1.2</b> · 장기 회복과 마을 변화 5곳 연동 · 기존 물자 경제 장부를 이용한 균형 점검·주민 후원 · 주민 일정과 계절 행사 지도 · 다니엘 신규 일상 4편 · 반응형 모바일 UX.</div>')};v12ensure();render();

