function v14ensure(){if(!s.v14||typeof s.v14!=='object'||Array.isArray(s.v14))s.v14={};const x=s.v14;for(const k of ['appointments','treatments','requests','rumors','daniel','choices'])if(!x[k]||typeof x[k]!=='object'||Array.isArray(x[k]))x[k]={};if(!Array.isArray(x.history))x.history=[];}
function v14Text(tag,text,cls){const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e}
function v14Actions(el,items){const r=document.createElement('div');r.className='v14-buttons';for(const [label,fn,disabled] of items)r.appendChild(button(label,fn,!!disabled));el.appendChild(r)}
function v14Card(title,desc){const c=document.createElement('article');c.className='v14-card';c.appendChild(v14Text('h3',title));if(desc)c.appendChild(v14Text('p',desc));return c}
function v14Page(title,desc){const el=$('main');el.replaceChildren(v14Text('h2',title,'sectionTitle'),v14Text('p',desc,'notice'));return el}
function v14Record(line){s.v14.history.unshift({day:s.day,text:line});s.v14.history=s.v14.history.slice(0,60);record(`${s.day}일 차: ${line}`);save(false)}
function v14Schedule(){v14ensure();v11ensure();const el=v14Page('📅 주민 일정과 진료 예약','[게임 확장] 주민의 이동 시간표와 예약을 연결합니다. 예약은 진료비가 없으며 원작의 공식 일정이 아닙니다.');const grid=document.createElement('div');grid.className='v14-grid';const slot=s.day+'_'+s.phase;const occupied=Object.values(s.v14.appointments).filter(x=>x&&x.day===s.day&&x.phase===s.phase).length;
for(const p of v14Patients){const key=p.id+'_'+s.day;const ap=s.v14.appointments[key];const current=v13NpcPlace(villageNPCs.find(n=>n.id===p.id));const c=v14Card(p.name,`오늘의 이동: ${current} · 권장 방문: ${phases[p.phase]} · 예약: ${ap?phases[ap.phase]+' 확정':'없음'}`);c.appendChild(v14Text('p',`현재 ${phases[s.phase]} · 진료 예약은 하루 3건까지 가능합니다.`,'v14-tag'));v14Actions(c,[['현재 시간대 예약',()=>{if(s.v14.appointments[key]||occupied>=3||!v11Day())return;s.v14.appointments[key]={day:s.day,phase:s.phase,status:'reserved'};v14Record(`${p.name} 진료 예약`);v14Schedule()},!!ap||occupied>=3||!v11Day()],['진료 기록 보기',()=>move('v14care'),false]]);grid.appendChild(c)}el.appendChild(grid);el.appendChild(v14Text('p','예약을 잡은 환자는 같은 날짜의 진료 선택 화면에서 확인할 수 있습니다.','v14-status'))}
function v14Care(){v14ensure();v11ensure();const el=v14Page('🩺 진료 선택과 결과','[게임 확장] 현실 의료 처방이 아닌 이야기 중심의 상담 선택입니다. 기존 진료 미니게임과 환자 기록은 유지합니다.');const grid=document.createElement('div');grid.className='v14-grid';for(const p of v14Patients){const key=p.id+'_'+s.day;const appointment=s.v14.appointments[key];const treatment=s.v14.treatments[key];const due=appointment&&appointment.phase<=s.phase;const c=v14Card(p.name,p.issue);c.appendChild(v14Text('p',treatment?'오늘 진료 완료 · '+treatment.choice:appointment?`예약 ${phases[appointment.phase]} · ${due?'진료 가능':'예약 시간 전'}`:'예약 없이 상담 가능','v14-tag'));if(treatment)c.appendChild(v14Text('p',treatment.result,'v14-status'));v14Actions(c,[['상태부터 확인하기',()=>v14Treat(p,key,'상태 확인'),!!treatment||!v11Day()||!!appointment&&!due],['먼저 이야기 듣기',()=>v14Treat(p,key,'대화'),!!treatment||!v11Day()||!!appointment&&!due]]);grid.appendChild(c)}el.appendChild(grid);v14Actions(el,[['기존 진료 미니게임',()=>move('v08clinic'),false],['기존 환자 기록',()=>move('v07charts'),false]])}
function v14Treat(p,key,choice){v14ensure();if(s.v14.treatments[key]||!v11Day())return;const ap=s.v14.appointments[key];if(ap&&ap.phase>s.phase)return;const result=(choice==='상태 확인'?p.good:p.other)+' '+p.result;s.v14.treatments[key]={day:s.day,choice,result,patient:p.id};if(ap)ap.status='completed';modify({trust:choice==='상태 확인'?2:1,tired:1,peace:1});v14Record(`${p.name} · ${choice}`);v14Care()}
function v14Village(){v14ensure();v11ensure();const el=v14Page('📣 마을 소문과 작은 부탁','[게임 확장] 환자 회복 진행과 마을의 소문이 연결됩니다. 하루에 하나의 부탁을 도울 수 있습니다.');const grid=document.createElement('div');grid.className='v14-grid';const today=Object.keys(s.v14.requests).some(k=>k.endsWith('_'+s.day));for(const r of v14Rumors){const stage=s.v11.recovery[r.need]?.stage||0;const unlocked=stage>=2;const key=r.id+'_'+s.day;const c=v14Card(r.title,unlocked?r.text:'회복 수첩 2단계 이후 이웃의 소문이 열립니다.');c.appendChild(v14Text('p',unlocked?'부탁: '+r.request:`회복 진행: ${stage}/3`,'v14-tag'));if(s.v14.requests[key])c.appendChild(v14Text('p',r.effect,'v14-status'));v14Actions(c,[['부탁 도와주기',()=>{if(s.v14.requests[key]||today||!v11Day()||!unlocked)return;s.v14.requests[key]={day:s.day};s.v14.rumors[r.id]=true;modify({trust:2,peace:1,tired:1});v14Record(r.request);v14Village()},!unlocked||today||!v11Day()]]);grid.appendChild(c)}el.appendChild(grid);v14Actions(el,[['회복 수첩',()=>move('v11recovery'),false],['주민 생활 지도',()=>move('v13living'),false]])}
function v14DanielUI(){v14ensure();const el=v14Page('💜 다니엘과 평범한 하루','[원작 확정] 두 사람은 연인이며 다니엘은 현역 군인입니다. 호칭은 코트리먼·D. [게임 확장] 아래 일정과 대사, 선택지는 비공식 신규 창작입니다.');const grid=document.createElement('div');grid.className='v14-grid';for(const ev of v14DanielScenes){const seen=s.v14.daniel[ev.id],can=v11Day()&&s.day>=ev.day;const c=v14Card(ev.title,`${ev.type} · ${seen?'읽음':can?'읽기 가능':ev.day+'일 차 개방'}`);if(seen)c.appendChild(v14Text('p',`선택: ${seen.choice}`,'v14-status'));v14Actions(c,[['이야기 열기',()=>{if(seen)return;c.appendChild(v14Text('p',ev.text.replace(/\\n/g,'\n'),'v14-status'));v14Actions(c,ev.choices.map(choice=>[choice,()=>{if(s.v14.daniel[ev.id])return;s.v14.daniel[ev.id]={day:s.day,choice};s.v14.choices[ev.id]=choice;modify({peace:3});v14Record(`다니엘 · ${ev.title}`);v14DanielUI()},false]))},!can||!!seen]]);grid.appendChild(c)}el.appendChild(grid)}
function v14Overview(){v14ensure();const el=v14Page('🌿 v1.4 진료소 일지','[게임 확장] 새로운 예약·진료·주민 부탁·편지 진행 상황을 한곳에서 확인합니다. 기존 시스템은 다른 메뉴에서 계속 이용할 수 있습니다.');const g=document.createElement('div');g.className='v14-grid';const day=s.day;const completed=Object.values(s.v14.treatments).filter(x=>x&&x.day===day).length;const reserved=Object.values(s.v14.appointments).filter(x=>x&&x.day===day).length;for(const [title,detail,tab] of [['오늘의 예약',`${reserved}건 · 오늘 진료 ${completed}건`,'v14schedule'],['마을 부탁',`${Object.keys(s.v14.requests).filter(x=>x.endsWith('_'+day)).length}건 완료`,'v14village'],['다니엘의 안부',`${Object.keys(s.v14.daniel).length}/${v14DanielScenes.length}편 기록`,'v14daniel']]){const c=v14Card(title,detail);v14Actions(c,[['자세히 보기',()=>move(tab),false]]);g.appendChild(c)}el.appendChild(g);const c=v14Card('최근 기록','새로운 행동은 기존 일지에도 함께 남습니다.');for(const x of s.v14.history.slice(0,7))c.appendChild(v14Text('p',`${x.day}일 차 · ${x.text}`));el.appendChild(c)}
const v14PreviousRender=render;render=function(){v14ensure();v14PreviousRender();const pages={v14overview:v14Overview,v14schedule:v14Schedule,v14care:v14Care,v14village:v14Village,v14daniel:v14DanielUI};if(pages[s.tab])pages[s.tab]()};
for(const [id,label] of [['v14overview','🌿 v1.4 일지'],['v14schedule','📅 진료 예약'],['v14care','🩺 진료 선택'],['v14village','📣 마을 소문'],['v14daniel','💜 새 안부']]){if(!document.querySelector(`[data-tab="${id}"]`)){const b=document.createElement('button');b.dataset.tab=id;b.textContent=label;b.addEventListener('click',()=>move(id));const nav=document.querySelector('nav.tabs');nav.insertBefore(b,nav.querySelector('[data-tab="updates"]'))}}
const v14PreviousUpdates=updates;updates=function(){v14PreviousUpdates();$('main').appendChild(v14Text('p','v1.4: 주민 일정·예약, 환자별 진료 선택, 회복 연동 마을 부탁, 다니엘 신규 일상 4편, 모바일 터치 및 키보드 접근성 개선. [게임 확장]','notice'))};


