const v15Followups={cactus:['장갑을 챙겨 왔다. 이제 선인장을 탓하기 전에 손을 살핀다.','화분 운반법을 친구에게 알려 줬다고 자랑한다.'],sleep:['잠드는 시간을 수첩에 적어 왔다.','늦은 라디오를 줄이고 낮에 조금 더 깨어 있다.'],grandma:['작은 찻잔을 들고 다시 왔다.','차를 나누는 자리가 이웃들에게도 익숙해졌다.'],merchant:['천막 줄을 쉬어 가며 고친다고 한다.','시장 상인들과 교대 수리 당번을 정했다.'],chess:['손을 쉬는 시간을 늘렸다고 말한다.','체스판 앞에 앉아도 중간중간 쉬어 간다.']};
const v15Chain=[{id:'cactus',title:'시장에 붙은 장갑 안내',need:'cactus',next:'merchant',text:'화분 안내문을 본 상인이 천막 수리에도 장갑을 쓰자고 제안했다.'},{id:'merchant',title:'천막 아래의 쉼터',need:'merchant',next:'grandma',text:'천막 수리 당번이 정해지자 할머니가 그늘에 찻잔을 가져왔다.'},{id:'grandma',title:'낮잠보다 좋은 차 한 잔',need:'grandma',next:'sleep',text:'할머니의 조용한 쉼터 이야기가 잠 못 자는 청년에게도 전해졌다.'},{id:'sleep',title:'밤 라디오의 새 시간표',need:'sleep',next:'chess',text:'라디오 시간을 조정한 주민들이 저녁 체스 모임을 제안했다.'},{id:'chess',title:'돌아오는 이야기',need:'chess',next:null,text:'체스판 옆에 작은 마을 게시판이 생겼다. 진료소에서 시작된 이야기가 다시 진료소로 돌아왔다.'}];
const v15Daniel=[{id:'supply-note',day:12,title:'정확히 세 장',type:'편지',text:'미겔은 필요한 물품을 종이에 적었다.\n“D. 종이는 세 장이면 충분하다.”\n다음 편지에는 짧은 확인 문장이 적혀 있었다. “알겠습니다, 코트리먼.”',choices:['물품 목록을 정리한다','편지 끝에 안부를 덧붙인다']},{id:'doorstep',day:23,title:'문턱의 먼지',type:'휴가',text:'다니엘이 진료소 문턱에 묻은 모래를 털었다.\n“코트리먼, 여긴 제가 할게요.”\n“D. 그럼 나는 물을 가져오겠다.”',choices:['물 한 잔을 건넨다','함께 문턱을 정돈한다']},{id:'postcard',day:34,title:'빈 엽서의 뒷면',type:'편지',text:'미겔은 별다른 사건이 없었던 하루를 적었다.\n“D. 오늘은 별일 없었다. 그게 좋았다.”\n우편소로 향하는 발걸음은 가벼웠다.',choices:['오늘의 날씨를 적는다','진료소 화분을 그린다']},{id:'chess-break',day:45,title:'한 수와 휴식',type:'휴가',text:'체스판 위에서 미겔의 손이 멈췄다.\n“D. 쉬었다 해도 승부는 봐주지 않는다.”\n다니엘이 찻잔을 옆으로 옮겼다. “알겠습니다, 코트리먼.”',choices:['승부를 이어간다','잠시 차를 마신다']}];
function v15ensure(){if(!s.v15||typeof s.v15!=='object'||Array.isArray(s.v15))s.v15={};const x=s.v15;for(const k of ['queue','followups','chains','requests','daniel'])if(!x[k]||typeof x[k]!=='object'||Array.isArray(x[k]))x[k]={};if(!Array.isArray(x.history))x.history=[];}
function v15Log(t){v15ensure();s.v15.history.unshift({day:s.day,text:t});s.v15.history=s.v15.history.slice(0,65);record(`${s.day}일 차: ${t}`);save(false)}
function v15Card(title,desc){const c=document.createElement('article');c.className='v15-card';c.appendChild(v14Text('h3',title));if(desc)c.appendChild(v14Text('p',desc));return c}
function v15Actions(c,actions){const r=document.createElement('div');r.className='v15-actions';actions.forEach(([label,fn,disabled])=>r.appendChild(button(label,fn,!!disabled)));c.appendChild(r)}
function v15Page(title,desc){const el=$('main');el.replaceChildren(v14Text('h2',title,'sectionTitle'),v14Text('p',desc,'notice'));return el}
function v15Queue(){v15ensure();v14ensure();const el=v15Page('📋 오늘의 실제 대기열','[게임 확장] v1.4 예약과 연결된 대기열입니다. 예약 시간 전에는 접수되지 않고, 진료 선택 후 완료로 이동합니다. 무료 진료 원칙을 유지합니다.');const g=document.createElement('div');g.className='v15-grid';const list=v14Patients.map(p=>({p,key:p.id+'_'+s.day,ap:s.v14.appointments[p.id+'_'+s.day]})).filter(x=>x.ap).sort((a,b)=>a.ap.phase-b.ap.phase);if(!list.length)el.appendChild(v14Text('p','오늘 예약이 없습니다. 예약 메뉴에서 주민을 먼저 접수해 주세요.','v15-line'));for(const {p,key,ap} of list){const tr=s.v14.treatments[key];const status=tr?'진료 완료':ap.phase>s.phase?'예약 시간 대기':ap.status==='checked-in'?'접수 완료 · 진료 대기':'도착 · 접수 가능';const c=v15Card(p.name,`${phases[ap.phase]} 예약 · ${status}`);if(tr)c.appendChild(v14Text('p',tr.result,'v15-line'));v15Actions(c,[['접수하기',()=>{if(ap.phase>s.phase||tr)return;ap.status='checked-in';s.v15.queue[key]={day:s.day,patient:p.id,checkedIn:true};v15Log(`${p.name} 예약 접수`);v15Queue()},!!tr||ap.phase>s.phase||ap.status==='checked-in'],['상담 진행',()=>{if(ap.status!=='checked-in'||tr)return;move('v14care')},!!tr||ap.status!=='checked-in']]);g.appendChild(c)}el.appendChild(g);v15Actions(el,[['예약 추가하기',()=>move('v14schedule')],['기존 진료 기록',()=>move('v07charts')]])}
