const v15OldTreat=v14Treat;v14Treat=function(p,key,choice){v14ensure();v15ensure();const ap=s.v14.appointments[key];if(ap&&ap.status!=='checked-in'&&ap.status!=='completed'){alert('예약 환자는 먼저 대기열에서 접수해 주세요.');return}const was=!!s.v14.treatments[key];v15OldTreat(p,key,choice);if(!was&&s.v14.treatments[key]){const t=s.v14.treatments[key];s.v15.followups[p.id]={due:s.day+2,sourceDay:s.day,choice,stage:0,result:t.result};v15Log(`${p.name}의 ${choice} 결과에 따른 후속 방문 예약`);}};
function v15FollowupUI(){v15ensure();const el=v15Page('🌱 진료 이후의 재방문','[게임 확장] 선택형 진료를 마친 환자는 이틀 뒤 경과를 이야기합니다. 기존 회복 수첩은 별도로 유지됩니다.');const g=document.createElement('div');g.className='v15-grid';for(const p of v14Patients){const f=s.v15.followups[p.id];const c=v15Card(p.name,f?`마지막 선택: ${f.choice} · 다음 확인 ${f.due}일 차`:'아직 v1.5 후속 진료가 없습니다. 진료 선택 메뉴에서 상담을 진행해 주세요.');if(f){const stage=Math.min(f.stage||0,2);c.appendChild(v14Text('p',stage?`최근 이야기: ${v15Followups[p.id][stage-1]}`:'첫 번째 경과 상담을 기다리고 있습니다.','v15-line'));v15Actions(c,[['경과 확인',()=>{if(s.day<f.due||f.stage>=2)return;const n=f.stage;f.stage++;f.due=s.day+2;v15Log(`${p.name} 후속 방문 ${f.stage}단계: ${v15Followups[p.id][n]}`);modify({trust:1,peace:1});v15FollowupUI()},s.day<f.due||stage>=2]])}g.appendChild(c)}el.appendChild(g)}
function v15RumorUI(){v15ensure();v14ensure();const el=v15Page('📣 이어지는 마을 소문','[게임 확장] v1.4의 주민 부탁을 완료하면 소문이 다음 이웃에게 전해집니다. 연쇄 사건은 하루 한 단계만 진행됩니다.');const g=document.createElement('div');g.className='v15-grid';const already=Object.values(s.v15.chains).some(x=>x&&x.day===s.day);for(let i=0;i<v15Chain.length;i++){const e=v15Chain[i];const prior=i===0?Object.keys(s.v14.requests).some(k=>k.startsWith('cactus_')):!!s.v15.chains[v15Chain[i-1].id];const unlocked=prior;const c=v15Card(e.title,unlocked?e.text:'이전 이웃의 부탁이나 소문이 아직 이어지지 않았습니다.');const seen=s.v15.chains[e.id];if(seen)c.appendChild(v14Text('p',`${seen.day}일 차에 마을에 전해졌습니다.`,'v15-line'));v15Actions(c,[['소문 전하기',()=>{if(!unlocked||seen||already)return;s.v15.chains[e.id]={day:s.day};v15Log(e.title);modify({trust:1,peace:1});v15RumorUI()},!unlocked||!!seen||already]]);g.appendChild(c)}el.appendChild(g);v15Actions(el,[['기존 마을 부탁',()=>move('v14village')]])}
function v15RequestsUI(){v15ensure();v11ensure();const el=v15Page('🤝 친밀도에 따른 주민 부탁','[게임 확장] 주민과 친해질수록 더 구체적인 부탁이 생깁니다. 하루 한 건만 도울 수 있습니다.');const g=document.createElement('div');const today=Object.values(s.v15.requests).some(x=>x.day===s.day);g.className='v15-grid';for(const p of v14Patients){const affinity=Number(s.v06?.relations?.[p.id]??s.v06?.friendship?.[p.id]??s.v07?.friendship?.[p.id]??s.v09?.relations?.[p.id]??0);const recovery=Number(s.v11.recovery[p.id]?.stage||0);const tier=recovery>=3||affinity>=6?2:recovery>=1||affinity>=2?1:0;const tasks=[`${p.name}에게 오늘의 안부 전하기`,`${p.name}의 일상 준비 돕기`,`${p.name}와 함께 이웃을 위한 작은 일 하기`];const key=p.id+'_'+tier;const c=v15Card(p.name,`관계 단계 ${tier+1}/3 · 회복 ${recovery}/3 · ${tasks[tier]}`);if(s.v15.requests[key])c.appendChild(v14Text('p','이미 도운 부탁입니다.','v15-line'));v15Actions(c,[['부탁 도와주기',()=>{if(today||s.v15.requests[key])return;s.v15.requests[key]={day:s.day,tier};v15Log(tasks[tier]);modify({trust:1,peace:1,tired:1});v15RequestsUI()},today||!!s.v15.requests[key]]]);g.appendChild(c)}el.appendChild(g)}
function v15DanielUI(){v15ensure();const el=v15Page('💜 다니엘과의 일상','[원작 확정] 두 사람은 연인이며, 다니엘은 군 복무 중입니다. 미겔은 D, 다니엘은 코트리먼이라고 부릅니다. [게임 확장] 아래 신규 대사와 날짜·선택지는 비공식 창작입니다.');const g=document.createElement('div');g.className='v15-grid';for(const e of v15Daniel){const seen=s.v15.daniel[e.id];const c=v15Card(e.title,`${e.type} · ${seen?'기록됨':s.day>=e.day?'열람 가능':e.day+'일 차부터'}`);if(seen)c.appendChild(v14Text('p',`선택: ${seen.choice}`,'v15-line'));v15Actions(c,[['이야기 읽기',()=>{if(seen||s.day<e.day)return;c.appendChild(v14Text('p',e.text.replace(/\\n/g,'\n'),'v15-line'));v15Actions(c,e.choices.map(choice=>[choice,()=>{if(s.v15.daniel[e.id])return;s.v15.daniel[e.id]={day:s.day,choice};modify({peace:2});v15Log(`다니엘 · ${e.title}`);v15DanielUI()}]))},!!seen||s.day<e.day]]);g.appendChild(c)}el.appendChild(g)}
