function v16ensure(){if(!s.v16||typeof s.v16!=='object'||Array.isArray(s.v16))s.v16={};const x=s.v16;for(const k of ['arrivals','aftercare','town','operations','comedy','daniel'])if(!x[k]||typeof x[k]!=='object'||Array.isArray(x[k]))x[k]={};if(!Array.isArray(x.history))x.history=[];}
function v16log(t){v16ensure();s.v16.history.unshift({day:s.day,phase:s.phase,text:t});s.v16.history=s.v16.history.slice(0,70);record(`${s.day}일 차: ${t}`);save(false)}
function v16card(title,desc){const c=document.createElement('article');c.className='v16-card';c.appendChild(v14Text('h3',title));if(desc)c.appendChild(v14Text('p',desc));return c}
function v16actions(c,items){const r=document.createElement('div');r.className='v16-actions';for(const [label,fn,disabled] of items)r.appendChild(button(label,fn,!!disabled));c.appendChild(r)}
function v16page(title,desc){const el=$('main');el.replaceChildren(v14Text('h2',title,'sectionTitle'),v14Text('p',desc,'notice'));return el}
function v16npc(p){const n=villageNPCs.find(n=>n.id===p.id);return n?v13NpcPlace(n):p.spot}
function v16arrived(p,ap){return !!ap&&s.phase>=ap.phase&&v16npc(p)==='진료소'}
function v16arrivalUI(){v16ensure();v14ensure();v15ensure();const el=v16page('🚶 주민 동선과 진료 대기열','[게임 확장] 현재 시간대의 실제 NPC 위치를 표시합니다. 예약 시간이 되어도 진료소에 도착하지 않았다면 대기열 접수는 보류됩니다. 기존 예약 기록은 유지됩니다.');const grid=document.createElement('div');grid.className='v16-grid';for(const p of v14Patients){const key=p.id+'_'+s.day,ap=s.v14.appointments[key],where=v16npc(p),treated=!!s.v14.treatments[key],arrived=v16arrived(p,ap),checked=ap?.status==='checked-in'||ap?.status==='completed';const c=v16card(p.name,`현재 위치: ${where} · ${ap?'예약 '+phases[ap.phase]:'예약 없음'}`);c.appendChild(v14Text('p',treated?'오늘 진료 완료':!ap?'예약을 먼저 잡아 주세요.':checked?'접수 완료':arrived?'진료소 도착 · 접수 가능':s.phase<ap.phase?'예약 시간 전':'아직 진료소에 도착하지 않았습니다.','v15-line'));v16actions(c,[['현재 위치 확인',()=>{v16log(`${p.name} 현재 위치 확인: ${v16npc(p)}`);v16arrivalUI()},false],['도착 접수',()=>{if(!v16arrived(p,ap)||checked||treated)return;ap.status='checked-in';s.v15.queue[key]={day:s.day,patient:p.id,checkedIn:true,where:'진료소'};s.v16.arrivals[key]={day:s.day,phase:s.phase};v16log(`${p.name} 실제 도착 확인 후 접수`);v16arrivalUI()},!arrived||checked||treated],['진료 선택',()=>move('v14care'),!checked||treated]]);grid.appendChild(c)}el.appendChild(grid);v16actions(el,[['예약 등록',()=>move('v14schedule')],['기존 대기열',()=>move('v15queue')]])}
function v16aftercareUI(){v16ensure();v15ensure();const el=v16page('🌿 회복과 마을의 변화','[게임 확장] 기존 v1.5 경과 상담을 1단계 이상 마친 환자의 변화가 마을 게시판에 반영됩니다. 원래 회복 기록은 덮어쓰지 않습니다.');const grid=document.createElement('div');grid.className='v16-grid';const impacts={cactus:['시장의 화분 운반 장갑을 함께 정리했다.','시장에 안전한 화분 운반 코너가 자리 잡았다.'],sleep:['급수대에 조용한 휴식 시간표가 붙었다.','늦은 라디오 소리가 줄었다는 이웃의 소식이 전해졌다.'],grandma:['진료소 대기석에 작은 찻잔 자리를 만들었다.','찻잔 자리에서 이웃들이 소식을 나누기 시작했다.'],merchant:['천막 수리 도구를 한곳에 모았다.','시장 상인들이 교대로 천막을 손보기 시작했다.'],chess:['체스판 옆 손 쉬는 안내문을 붙였다.','체스 모임에 쉬는 시간이 생겼다.']};for(const p of v14Patients){const f=s.v15.followups[p.id],stage=Math.min(2,Number(f?.stage||0)),done=Number(s.v16.town[p.id]||0);const c=v16card(p.name,`후속 진료 ${stage}/2단계 · 마을 반영 ${done}/2단계`);if(done)c.appendChild(v14Text('p',impacts[p.id][done-1],'v15-line'));v16actions(c,[['마을 변화 반영',()=>{if(done>=stage||done>=2)return;const n=done+1;s.v16.town[p.id]=n;v16log(`${p.name}: ${impacts[p.id][n-1]}`);modify({trust:1,peace:1});v16aftercareUI()},done>=stage||done>=2]]);grid.appendChild(c)}el.appendChild(grid);v16actions(el,[['후속 방문 확인',()=>move('v15follow')]])}
function v16operationsUI(){v16ensure();v11ensure();const el=v16page('⚖️ 오늘의 운영과 이웃 관계','[게임 확장] 하루 한 번 무료 진료소의 운영 방향을 정합니다. 기존 재고·지원금·신뢰도 수치에 연동되며 주민 친밀도는 새 보조 기록으로 누적합니다.');const done=s.v16.operations[s.day],grid=document.createElement('div');grid.className='v16-grid';const options=[{id:'supplies',title:'물자 정리',desc:'물품 2개를 정돈하고 소모품 1개를 아낍니다.',cost:0,effect:{supplies:1,tired:2},bond:'merchant'},{id:'rest',title:'주민과 쉬는 시간',desc:'진료소의 휴식 시간을 정해 주민의 피로를 덜어 줍니다.',cost:0,effect:{peace:3,tired:-2},bond:'grandma'},{id:'delivery',title:'이웃에게 소모품 전달',desc:'물품 2개를 나누고 신뢰를 쌓습니다.',cost:2,effect:{supplies:-2,trust:3,peace:1},bond:'cactus'}];for(const o of options){const c=v16card(o.title,o.desc);v16actions(c,[['오늘 선택하기',()=>{if(s.v16.operations[s.day]||s.supplies<o.cost)return;modify(o.effect);s.v16.operations[s.day]=o.id;const k='bond_'+o.bond;s.v16.operations[k]=Number(s.v16.operations[k]||0)+1;v16log(`운영 선택: ${o.title} · ${o.bond} 이웃 관계 +1`);v16operationsUI()},!!done||s.supplies<o.cost]]);grid.appendChild(c)}el.appendChild(grid);el.appendChild(v14Text('p',done?`오늘의 운영 선택: ${options.find(x=>x.id===done)?.title||done}`:'오늘은 아직 운영 방향을 정하지 않았습니다.','v15-line'));el.appendChild(v14Text('p',`물품 ${s.supplies} · 신뢰 ${s.trust} · 평온 ${s.peace} · 피로 ${s.tired}`,'v16-muted'));v16actions(el,[['기존 물자 장부',()=>move('v11economy')],['주민 관계',()=>move('relations')]])}
function v16comedyUI(){v16ensure();const el=v16page('🎭 오늘의 엉뚱한 환자','[게임 확장] 새 코미디 환자 네 명. 하루에 한 번만 진료하며 실제 의료 처방이나 원작 확정 사건이 아닙니다.');const today=v16Comedy[(s.day-1)%v16Comedy.length],key='day_'+s.day,done=s.v16.comedy[key],c=v16card(`${today.title} · ${today.who}`,today.issue);c.appendChild(v14Text('p',`등장 시간: ${phases[today.phase]} · 장소: ${today.where}`,'v16-muted'));if(done)c.appendChild(v14Text('p',done.result,'v15-line'));v16actions(c,today.options.map((label,i)=>[label,()=>{if(s.v16.comedy[key]||s.phase<today.phase)return;s.v16.comedy[key]={patient:today.id,choice:i,result:today.answers[i]};modify({trust:1,peace:1,tired:1});v16log(`${today.who} 진료: ${today.answers[i]}`);v16comedyUI()},!!done||s.phase<today.phase]));el.appendChild(c)}
function v16danielUI(){v16ensure();const el=v16page('💜 다니엘과의 새로운 일상','[원작 확정] 미겔은 자발적으로 전역해 무료 진료소를 운영하고, 다니엘은 군 복무 중인 연인입니다. 호칭은 D·코트리먼. [게임 확장] 아래 일정과 대사는 비공식 창작입니다.');const grid=document.createElement('div');grid.className='v16-grid';for(const e of v16Daniel){const seen=s.v16.daniel[e.id],c=v16card(e.title,`${e.kind} · ${seen?'기록 완료':s.day>=e.day?'열람 가능':e.day+'일 차부터'}`);if(seen)c.appendChild(v14Text('p',`선택: ${seen.choice}`,'v15-line'));v16actions(c,[['이야기 열기',()=>{if(seen||s.day<e.day)return;c.appendChild(v14Text('p',e.text.replace(/\\n/g,'\n'),'v15-line'));v16actions(c,e.choices.map(choice=>[choice,()=>{if(s.v16.daniel[e.id])return;s.v16.daniel[e.id]={day:s.day,choice};modify({peace:2});v16log(`다니엘 · ${e.title}`);v16danielUI()},false]))},!!seen||s.day<e.day]]);grid.appendChild(c)}el.appendChild(grid)}
