function v17ensure(){if(!s.v17||typeof s.v17!=='object'||Array.isArray(s.v17))s.v17={};for(const k of ['visits','links','economy','daniel','arrivals'])if(!s.v17[k]||typeof s.v17[k]!=='object'||Array.isArray(s.v17[k]))s.v17[k]={};if(!Array.isArray(s.v17.history))s.v17.history=[];}
function v17log(t){v17ensure();s.v17.history.unshift({day:s.day,phase:s.phase,text:t});s.v17.history=s.v17.history.slice(0,80);record(`${s.day}일 차: ${t}`);save(false)}
function v17page(title,description){const el=$('main');el.replaceChildren(v14Text('h2',title,'sectionTitle'),v14Text('p',description,'notice'));return el}
function v17card(title,desc){const c=document.createElement('article');c.className='v17-card';c.appendChild(v14Text('h3',title));c.appendChild(v14Text('p',desc));return c}
function v17actions(c,items){const r=document.createElement('div');r.className='v17-actions';for(const [label,fn,disabled] of items)r.appendChild(button(label,fn,!!disabled));c.appendChild(r)}
function v17clock(){v17ensure();v14ensure();const el=v17page('🕒 하루의 주민 동선','[게임 확장] 게임 속 하루의 아침·낮·오후·저녁을 기준으로 NPC의 현재 위치와 예약 상태를 함께 보여 줍니다. 실제 시계나 GPS가 아니라 게임 내 시간입니다.');const tr=document.createElement('div');tr.className='v17-track';phases.forEach((ph,i)=>{const e=v14Text('span',ph,'v17-step'+(i===s.phase?' active':''));tr.appendChild(e)});el.appendChild(tr);const g=document.createElement('div');g.className='v17-grid';for(const p of v14Patients){const key=p.id+'_'+s.day,ap=s.v14.appointments[key],where=v16npc(p),done=!!s.v14.treatments[key];const c=v17card(p.name,`현재 ${where} · ${ap?'예약 '+phases[ap.phase]:'예약 없음'} · ${done?'진료 완료':ap?.status==='checked-in'?'접수 완료':'미접수'}`);const arrived=!!ap&&s.phase>=ap.phase&&where==='진료소';v17actions(c,[['위치·접수 열기',()=>move('v16arrivals'),!ap||done],['예약 화면',()=>move('v14schedule'),false]]);if(ap&&!done&&!arrived)c.appendChild(v14Text('p','현재 위치에서는 접수할 수 없습니다. 다른 시간대에 다시 확인하거나 예약을 조정하세요.','v17-muted'));g.appendChild(c)}el.appendChild(g);v17actions(el,[['다음 시간대로 진행',()=>next(),false],['대기열 확인',()=>move('v15queue'),false]])}
function v17comedy(){v17ensure();v16ensure();const el=v17page('🎭 엉뚱한 환자 재방문','[게임 확장] v1.6의 코미디 진료를 완료한 환자가 이틀 뒤 다시 방문합니다. 상담은 2단계까지 진행되며 기존 진료 기록을 변경하지 않습니다.');const g=document.createElement('div');g.className='v17-grid';for(const p of v16Comedy){const history=Object.entries(s.v16.comedy).filter(([k,v])=>k.startsWith('day_')&&v?.patient===p.id).map(([k])=>Number(k.slice(4))).sort((a,b)=>a-b);const first=history[0],x=s.v17.visits[p.id]||{stage:0,due:first+2},stage=x.stage||0;const c=v17card(p.who,first?`첫 진료 ${first}일 차 · 후일담 ${stage}/2 · 다음 방문 ${x.due}일 차`:'먼저 🎭 새 환자 메뉴에서 이 환자를 진료해야 합니다.');if(stage)c.appendChild(v14Text('p',v17Stories[p.id][stage-1],'v17-muted'));v17actions(c,[['재방문 상담',()=>{if(!first||stage>=2||s.day<x.due)return;const n=stage+1;s.v17.visits[p.id]={stage:n,due:s.day+2,firstDay:first};v17log(`${p.who} 재방문 ${n}단계: ${v17Stories[p.id][n-1]}`);modify({trust:1,peace:1});v17comedy()},!first||stage>=2||s.day<x.due]]);g.appendChild(c)}el.appendChild(g);v17actions(el,[['첫 진료 열기',()=>move('v16comedy'),false]])}
function v17village(){v17ensure();v15ensure();v16ensure();const el=v17page('🏘️ 관계가 이어지는 마을','[게임 확장] 기존 후속 진료와 주민 관계 기록을 조건으로 여는 연쇄 이벤트입니다. 이전 친밀도·회복·소문 기록은 덮어쓰지 않습니다.');const g=document.createElement('div');g.className='v17-grid';for(let i=0;i<v17Links.length;i++){const e=v17Links[i],prev=i===0||!!s.v17.links[v17Links[i-1].id],f=Number(s.v15.followups[e.need]?.stage||0),bond=Number(s.v16.operations['bond_'+e.bond]||0),relation=Number(s.v06?.relations?.[e.bond]??s.v07?.friendship?.[e.bond]??0),ready=prev&&(f>=1||bond>=1||relation>=2),done=s.v17.links[e.id];const c=v17card(e.title,done?e.text:ready?'이웃에게 소식을 전할 준비가 됐습니다.':'이전 소문과 후속 진료 또는 주민 관계가 필요합니다.');if(done)c.appendChild(v14Text('p',`${done.day}일 차 완료`,'v17-muted'));v17actions(c,[['이야기 이어가기',()=>{if(!ready||done||Object.values(s.v17.links).some(v=>v.day===s.day))return;s.v17.links[e.id]={day:s.day};v17log(e.text);modify({trust:1,peace:1});v17village()},!ready||!!done||Object.values(s.v17.links).some(v=>v.day===s.day)]]);g.appendChild(c)}el.appendChild(g)}
function v17economy(){v17ensure();const el=v17page('⚖️ 물자와 이웃의 균형','[게임 확장] 무료 진료를 유지하면서 하루에 한 번 물자를 아끼거나 지원금을 활용합니다. 재고가 부족하면 사용하지 않으며 수치는 0 아래로 떨어지지 않도록 확인합니다.');const day=s.v17.economy[s.day],g=document.createElement('div');g.className='v17-grid';const opts=[{id:'audit',title:'물자 장부 점검',desc:'정리 후 소모품 +1, 피로 +1',need:0,effect:{supplies:1,tired:1}},{id:'share',title:'이웃과 물자 나누기',desc:'소모품 -2, 신뢰 +2, 평온 +1',need:2,effect:{supplies:-2,trust:2,peace:1}},{id:'rest',title:'휴식 시간 지키기',desc:'피로 -3, 평온 +2',need:0,effect:{tired:-3,peace:2}}];for(const o of opts){const c=v17card(o.title,o.desc);v17actions(c,[['선택하기',()=>{if(s.v17.economy[s.day]||Number(s.supplies||0)<o.need)return;modify(o.effect);s.v17.economy[s.day]=o.id;v17log(`운영 균형: ${o.title}`);v17economy()},!!day||Number(s.supplies||0)<o.need]]);g.appendChild(c)}el.appendChild(g);el.appendChild(v14Text('p',`오늘: ${day||'미선택'} · 물자 ${s.supplies} · 신뢰 ${s.trust} · 평온 ${s.peace} · 피로 ${s.tired}`,'v17-muted'));v17actions(el,[['기존 물자 장부',()=>move('v11economy'),false],['기존 운영 선택',()=>move('v16operations'),false]])}
function v17daniel(){v17ensure();const el=v17page('💜 다니엘의 새로운 일상','[원작 확정] 미겔은 자발적으로 전역한 여성 전직 군의관이며, 다니엘은 현역 군인인 연인입니다. [게임 확장] 신규 일정·대사·선택지는 비공식 창작입니다.');const g=document.createElement('div');g.className='v17-grid';for(const e of v17Daniel){const seen=s.v17.daniel[e.id],c=v17card(e.title,`${e.kind} · ${seen?'기록 완료':s.day>=e.day?'열람 가능':e.day+'일 차부터'}`);if(seen)c.appendChild(v14Text('p',`선택: ${seen.choice}`,'v17-muted'));v17actions(c,[['이야기 읽기',()=>{if(seen||s.day<e.day)return;c.appendChild(v14Text('p',e.text.replace(/\\n/g,'\n'),'v17-muted'));v17actions(c,e.choices.map(choice=>[choice,()=>{if(s.v17.daniel[e.id])return;s.v17.daniel[e.id]={day:s.day,choice};modify({peace:2});v17log(`다니엘 · ${e.title}`);v17daniel()},false]))},!!seen||s.day<e.day]]);g.appendChild(c)}el.appendChild(g)}
