function v18checkArrivals(){v18ensure();v14ensure();v15ensure();v16ensure();let changed=false;for(const p of v14Patients){const key=p.id+'_'+s.day,ap=s.v14.appointments[key];if(!ap||s.v14.treatments[key]||ap.status==='checked-in'||ap.status==='completed'||!v16arrived(p,ap))continue;ap.status='checked-in';s.v15.queue[key]={day:s.day,patient:p.id,checkedIn:true,where:'진료소',automatic:true};s.v16.arrivals[key]={day:s.day,phase:s.phase,automatic:true};s.v18.autoArrivals[key]={day:s.day,phase:s.phase};s.v18.history.unshift({day:s.day,phase:s.phase,text:`${p.name} 예약 자동 접수`});changed=true;}if(changed){s.v18.history=s.v18.history.slice(0,80);save(false)}return changed}
const v18OldNext=next;next=function(){v18OldNext();v18checkArrivals();render()};
function v18appointments(){v18ensure();v18checkArrivals();const el=v18page('🕒 예약과 실제 이동','[게임 확장] 게임 내 시간대가 진행될 때 NPC 위치를 확인하여 진료소에 도착한 예약 환자를 자동 접수합니다. 도착하지 않은 예약은 유지됩니다.');const grid=document.createElement('div');grid.className='v17-grid';for(const p of v14Patients){const key=p.id+'_'+s.day,ap=s.v14.appointments[key],where=v16npc(p),treated=!!s.v14.treatments[key];const status=treated?'진료 완료':!ap?'예약 없음':ap.status==='checked-in'?'자동/수동 접수 완료':s.phase<ap.phase?'예약 시간 전':'도착 대기';const c=v18card(p.name,`현재 ${where} · ${ap?'예약 '+phases[ap.phase]:'미예약'} · ${status}`);v18buttons(c,[['예약 확인',()=>move('v14schedule'),false],['대기열',()=>move('v15queue'),!ap],['진료 선택',()=>move('v14care'),!ap||ap.status!=='checked-in'||treated]]);grid.appendChild(c)}el.appendChild(grid);v18buttons(el,[['다음 시간대',()=>next(),false],['기존 위치·접수',()=>move('v16arrivals'),false]])}
function v18village(){v18ensure();v17ensure();const el=v18page('🏘️ 코미디 환자가 바꾼 마을','[게임 확장] v1.7 코미디 환자 재방문 2단계를 마치면 작은 시설·소문 후일담이 개방됩니다. 기존 기록은 변경하지 않습니다.');const grid=document.createElement('div');grid.className='v17-grid';for(const e of v18VillageChanges){const stage=Number(s.v17.visits[e.id]?.stage||0),seen=s.v18.village[e.id],c=v18card(e.title,`장소: ${e.where} · ${seen?'마을 반영 완료':stage>=2?'반영 가능':'재방문 2단계 필요'}`);if(seen)c.appendChild(v14Text('p',e.text,'v17-muted'));v18buttons(c,[['마을에 반영',()=>{if(stage<2||s.v18.village[e.id])return;s.v18.village[e.id]={day:s.day};v18log(e.text);modify({peace:1,trust:1});v18village()},stage<2||!!seen]]);grid.appendChild(c)}el.appendChild(grid);v18buttons(el,[['코미디 환자 재방문',()=>move('v17comedy'),false]])}
function v18relations(){v18ensure();const el=v18page('💬 이웃과 친밀도별 대화','[게임 확장] 기존 주민 친밀도 및 마을 변화 기록을 읽어 대화가 달라집니다. 원작의 확정 대사가 아닙니다.');const grid=document.createElement('div');grid.className='v17-grid';for(const npc of villageNPCs){const id=npc.id,bond=Number(s.v06?.relations?.[id]??s.v07?.friendship?.[id]??0),links=Object.keys(s.v17?.links||{}).length,level=bond>=5||links>=3?2:bond>=2||links>=1?1:0,lines=v18Dialogues[id]?.[0]||['오늘도 좋은 하루예요.'],key=id+'_'+s.day,c=v18card(npc.name,`현재 위치: ${v16npc(npc)} · 관계 단계 ${level+1}/3`);c.appendChild(v14Text('p',s.v18.talks[key]?.text||lines[level],'v17-muted'));v18buttons(c,[['오늘의 대화',()=>{if(s.v18.talks[key])return;s.v18.talks[key]={day:s.day,level,text:lines[level]};v18log(`${npc.name}과 대화`);modify({peace:1});v18relations()},!!s.v18.talks[key]]]);grid.appendChild(c)}el.appendChild(grid);v18buttons(el,[['기존 주민 관계',()=>move('relations'),false]])}
function v18economy(){v18ensure();const el=v18page('⚖️ 물자 경제 점검','[게임 확장] 무료 진료를 유지하며 부족한 재고를 먼저 확인합니다. 하루에 한 번만 선택하며 기존 장부·운영 기록은 보존됩니다.');const day=s.v18.economy[s.day],low=Number(s.supplies||0)<4,c=v18card('오늘의 물자 상태',`소모품 ${s.supplies} · 지원금 ${s.coins} · 신뢰 ${s.trust} · ${low?'재고 주의':'재고 안정'} · 오늘 ${day||'미선택'}`);v18buttons(c,[['지원금으로 물자 보충 (지원금 -3, 물자 +3)',()=>{if(day||s.coins<3)return;modify({coins:-3,supplies:3});s.v18.economy[s.day]='보충';v18log('물자 보충');v18economy()},!!day||s.coins<3],['이웃에게 소모품 지원 (물자 -2, 신뢰 +2)',()=>{if(day||s.supplies<2)return;modify({supplies:-2,trust:2});s.v18.economy[s.day]='나눔';v18log('소모품 나눔');v18economy()},!!day||s.supplies<2],['장부 정리 (피로 +1, 평온 +2)',()=>{if(day)return;modify({tired:1,peace:2});s.v18.economy[s.day]='점검';v18log('장부 정리');v18economy()},!!day]]);el.appendChild(c);v18buttons(el,[['기존 약품별 재고',()=>move('v07stock'),false],['기존 경제 장부',()=>move('v11economy'),false]])}
function v18daniel(){v18ensure();const el=v18page('💜 다니엘과 미겔의 새로운 일상','[원작 확정] 미겔은 여성 전직 군의관으로 자발적으로 전역했고, 다니엘은 현역 군인인 연인입니다. [게임 확장] 아래 편지·휴가·선택지는 비공식 창작입니다.');const grid=document.createElement('div');grid.className='v17-grid';for(const e of v18Daniel){const seen=s.v18.daniel[e.id],c=v18card(e.title,`${e.kind} · ${seen?'완료':s.day>=e.day?'열람 가능':e.day+'일 차부터'}`);if(seen)c.appendChild(v14Text('p',`선택: ${seen.choice}`,'v17-muted'));v18buttons(c,[['이야기 열기',()=>{if(seen||s.day<e.day)return;c.appendChild(v14Text('p',e.text.replace(/\\n/g,'\n'),'v17-muted'));v18buttons(c,e.choices.map(choice=>[choice,()=>{if(s.v18.daniel[e.id])return;s.v18.daniel[e.id]={day:s.day,choice};modify({peace:2});v18log(`다니엘 · ${e.title}`);v18daniel()},false]))},!!seen||s.day<e.day]]);grid.appendChild(c)}el.appendChild(grid)}
const v18PreviousRender=render;render=function(){v18ensure();v18PreviousRender();const pages={v18appointments,v18village,v18relations,v18economy,v18daniel};if(pages[s.tab])pages[s.tab]()};
for(const [id,label] of [['v18appointments','🕒 자동 접수'],['v18village','🏘️ 마을 후일담'],['v18relations','💬 이웃 대화'],['v18economy','⚖️ 물자 점검'],['v18daniel','💜 일상 편지']]){if(!document.querySelector(`[data-tab="${id}"]`)){const b=button(label,()=>move(id));b.dataset.tab=id;document.querySelector('nav.tabs').insertBefore(b,document.querySelector('[data-tab="updates"]'))}}
const v18OldUpdates=updates;updates=function(){v18OldUpdates();$('main').appendChild(v14Text('p','v1.8 · 시간대 전환 시 예약 자동 접수, 코미디 환자 마을 후일담, 관계별 대화, 물자 경제 점검, 다니엘 일상 4편. [게임 확장] 저장 키와 version:2 유지.','notice'))};v18ensure();render();

