function v19ensure(){if(!s.v19||typeof s.v19!=='object'||Array.isArray(s.v19))s.v19={};for(const key of ['alerts','chain','relations','ledger','daniel','choices'])if(!s.v19[key]||typeof s.v19[key]!=='object'||Array.isArray(s.v19[key]))s.v19[key]={};if(!Array.isArray(s.v19.history))s.v19.history=[];}
function v19event(label){v19ensure();s.v19.history.unshift({day:s.day,phase:s.phase,text:label});s.v19.history=s.v19.history.slice(0,100);record(`${s.day}일 차: ${label}`);save(false)}
function v19page(title,desc){const el=$('main');el.replaceChildren(v14Text('h2',title,'sectionTitle'),v14Text('p',desc,'notice'));return el}
function v19card(title,desc){const c=document.createElement('article');c.className='v17-card';c.appendChild(v14Text('h3',title));if(desc)c.appendChild(v14Text('p',desc));return c}
function v19actions(parent,actions){const row=document.createElement('div');row.className='v17-actions';for(const [name,fn,disabled] of actions)row.appendChild(button(name,fn,!!disabled));parent.appendChild(row)}
function v19arrivals(){v19ensure();v18ensure();v14ensure();v15ensure();v18checkArrivals();let changed=false;for(const p of v14Patients){const key=p.id+'_'+s.day,ap=s.v14.appointments[key];if(!ap||s.v14.treatments[key]||ap.status!=='checked-in'||s.v19.alerts[key])continue;s.v19.alerts[key]={day:s.day,phase:s.phase,patient:p.id,name:p.name};s.v19.history.unshift({day:s.day,phase:s.phase,text:`🔔 ${p.name} 진료소 도착 · 대기열 접수`});changed=true}if(changed){s.v19.history=s.v19.history.slice(0,100);save(false)}return changed}
function v19queue(){v19arrivals();const el=v19page('🔔 예약 도착 알림과 대기열','[게임 확장] 게임 내 시간대·NPC 위치를 확인합니다. 자동 접수된 환자는 한 번만 알림을 남기며, 예약/대기열 원본은 그대로 유지합니다.');const grid=document.createElement('div');grid.className='v17-grid';for(const p of v14Patients){const key=p.id+'_'+s.day,ap=s.v14.appointments[key],treated=s.v14.treatments[key],where=v16npc(p),alert=s.v19.alerts[key];const state=treated?'진료 완료':!ap?'예약 없음':ap.status==='checked-in'?'접수 완료':s.phase<ap.phase?'예약 시간 전':'진료소 도착 대기';const c=v19card(p.name,`현재 위치 ${where} · ${ap?'예약 '+phases[ap.phase]:'예약 없음'} · ${state}`);if(alert)c.appendChild(v14Text('p',`🔔 ${phases[alert.phase]} 도착 알림 기록됨`,'v15-line'));v19actions(c,[['예약하기',()=>move('v14schedule'),!!ap],['진료 대기열',()=>move('v15queue'),!ap],['상담 선택',()=>move('v14care'),!ap||ap.status!=='checked-in'||!!treated]]);grid.appendChild(c)}el.appendChild(grid);v19actions(el,[['다음 시간대로',()=>next(),false],['도착 기록 확인',()=>v19journal(),false]])}
function v19chain(){v19ensure();v17ensure();v18ensure();const el=v19page('🏘️ 마을 소문의 연쇄','[게임 확장] 코미디 환자 재방문 2단계와 이전 이야기 완료가 조건입니다. 원작 확정 사건이 아닌 작은 정착촌 후일담입니다.');const grid=document.createElement('div');grid.className='v17-grid';for(const t of v19Tales){const stage=Number(s.v17.visits[t.id]?.stage||0),prior=t.requires.every(id=>!!s.v19.chain[id]),unlocked=stage>=2&&prior,seen=s.v19.chain[t.id],c=v19card(t.title,`${t.name} · ${seen?'완료':unlocked?'이야기 개방':'재방문 2단계와 이전 이야기 필요'}`);if(seen)c.appendChild(v14Text('p',t.text,'v15-line'));v19actions(c,[['마을 이야기 진행',()=>{if(!unlocked||s.v19.chain[t.id])return;s.v19.chain[t.id]={day:s.day};modify({peace:1,trust:1});v19event(t.title);v19chain()},!unlocked||!!seen]]);grid.appendChild(c)}el.appendChild(grid);v19actions(el,[['환자 재방문',()=>move('v17comedy'),false],['기존 마을 후일담',()=>move('v18village'),false]])}
function v19relations(){v19ensure();const el=v19page('💬 이웃 관계가 바꾸는 마을','[게임 확장] 기존 주민 친밀도, 후속 진료, 마을 이야기의 기록을 참고합니다. 새로운 관계 변화는 주민마다 한 번씩 기록됩니다.');const grid=document.createElement('div');for(const n of villageNPCs){const bond=Number(s.v06?.relations?.[n.id]??s.v07?.friendship?.[n.id]??0),done=!!s.v19.relations[n.id],story=!!s.v19.chain[n.id]||!!s.v18?.village?.[n.id],unlocked=bond>=2||story,dayKey=n.id+'_'+s.day;const c=v19card(n.name,`친밀도 ${bond} · ${story?'마을 이야기 진행':'기존 관계 기록'} · ${done?'이웃 변화 기록됨':unlocked?'관계 변화 개방':'친밀도 2 이상 또는 관련 후일담 필요'}`);if(done)c.appendChild(v14Text('p',done.text,'v15-line'));const text=`${n.name}이(가) ${v16npc(n)}에서 이웃에게 진료소의 안부를 전한다. 진료소를 찾는 길도 조금 더 익숙해졌다.`;v19actions(c,[['이웃의 변화 기록',()=>{if(!unlocked||s.v19.relations[n.id])return;s.v19.relations[n.id]={day:s.day,text};modify({trust:1});v19event(`${n.name}의 마을 관계 변화`);v19relations()},!unlocked||!!done],['기존 친밀도 대화',()=>move('v18relations'),false]]);grid.appendChild(c)}grid.className='v17-grid';el.appendChild(grid)}
function v19ledger(){v19ensure();const el=v19page('📒 진료소 물자 장부','[게임 확장] 소모품과 지원금을 기록하고 한 번의 거래가 중복 실행되지 않도록 합니다. 무료 진료는 유지합니다. 기존 재고 장부도 보존합니다.');const dayKey=String(s.day),entry=s.v19.ledger[dayKey],low=Number(s.supplies)<4,c=v19card('오늘의 장부',`소모품 ${s.supplies} · 지원금 ${s.coins} · 신뢰 ${s.trust} · ${low?'⚠️ 물자 부족':'재고 확인'} · ${entry?'오늘 기록 완료':'오늘 기록 가능'}`);const choices=[{name:'필수 소모품 보충',cost:4,gain:4,delta:{coins:-4,supplies:4},detail:'지원금 4를 사용해 소모품 4를 보충'},{name:'공동 물자 나눔',cost:0,gain:0,need:3,delta:{supplies:-3,trust:3,peace:1},detail:'소모품 3을 나누고 신뢰를 얻음'},{name:'재고 목록 재정리',cost:0,gain:0,delta:{tired:1,peace:1},detail:'소모 없이 재고를 정리'}];for(const x of choices)v19actions(c,[[x.name,()=>{if(s.v19.ledger[dayKey]||Number(s.coins)<x.cost||Number(s.supplies)<(x.need||0))return;const before={supplies:s.supplies,coins:s.coins};modify(x.delta);s.v19.ledger[dayKey]={day:s.day,action:x.name,before,after:{supplies:s.supplies,coins:s.coins},detail:x.detail};v19event(`물자 장부: ${x.name}`);v19ledger()},!!entry||Number(s.coins)<x.cost||Number(s.supplies)<(x.need||0)]]);el.appendChild(c);const entries=Object.values(s.v19.ledger).sort((a,b)=>b.day-a.day).slice(0,14);if(entries.length){const log=v19card('최근 운영 기록','이 기록은 v1.9에서 실행한 거래만 보여 줍니다.');for(const x of entries)log.appendChild(v14Text('p',`${x.day}일 차 · ${x.action} · 물자 ${x.before.supplies}→${x.after.supplies} · 지원금 ${x.before.coins}→${x.after.coins}`,'v15-line'));el.appendChild(log)}v19actions(el,[['기존 약품 재고',()=>move('v07stock'),false],['기존 운영 장부',()=>move('v11economy'),false]])}
function v19daniel(){v19ensure();const el=v19page('💜 다니엘의 새로운 일상','[원작 확정] 미겔은 자발적으로 전역한 여성 전직 군의관이며 다니엘은 현역 군인인 연인입니다. [게임 확장] 이 화면의 일정과 대사는 비공식 창작입니다.');const grid=document.createElement('div');grid.className='v17-grid';for(const t of v19Daniel){const seen=s.v19.daniel[t.id],c=v19card(t.title,`${t.kind} · ${seen?'기록 완료':s.day>=t.day?'열람 가능':t.day+'일 차부터'}`);if(seen)c.appendChild(v14Text('p',`선택: ${seen.choice}`,'v15-line'));v19actions(c,[['이야기 열기',()=>{if(s.day<t.day||s.v19.daniel[t.id])return;c.appendChild(v14Text('p',t.text.replace(/\\n/g,'\n'),'v15-line'));v19actions(c,t.choices.map(choice=>[choice,()=>{if(s.v19.daniel[t.id])return;s.v19.daniel[t.id]={day:s.day,choice};modify({peace:2});v19event(`다니엘 · ${t.title}`);v19daniel()},false]))},s.day<t.day||!!seen]]);grid.appendChild(c)}el.appendChild(grid)}
function v19journal(){v19ensure();const el=v19page('📜 v1.9 활동 기록','[게임 확장] 도착 알림, 주민 후일담, 물자 거래, 편지 기록을 최근순으로 보여 줍니다.');for(const e of s.v19.history.slice(0,40))el.appendChild(v14Text('p',`${e.day}일 차 ${phases[e.phase]||''} · ${e.text}`,'v15-line'));if(!s.v19.history.length)el.appendChild(v14Text('p','아직 새 활동 기록이 없습니다.','v15-line'))}
