const v19OldRender=render;render=function(){v19ensure();v19OldRender();const pages={v19queue,v19chain,v19relations,v19ledger,v19daniel,v19journal};if(pages[s.tab])pages[s.tab]()};
for(const [id,label] of [['v19queue','🔔 도착 알림'],['v19chain','🏘️ 연쇄 후일담'],['v19relations','💬 마을 관계'],['v19ledger','📒 운영 장부'],['v19daniel','💜 새 일상'],['v19journal','📜 활동 기록']]){if(!document.querySelector(`[data-tab="${id}"]`)){const b=button(label,()=>move(id));b.dataset.tab=id;document.querySelector('nav.tabs').insertBefore(b,document.querySelector('[data-tab="updates"]'))}}
