const v20KEY='miguel_clinic_v02';
const v20Phases=['아침','낮','오후','저녁'];
function v20Ensure(){if(!s.v20||typeof s.v20!=='object'||Array.isArray(s.v20))s.v20={};const v=s.v20;for(const k of ['followups','community','daniel','dayLogs','notices','economy'])if(!v[k]||typeof v[k]!=='object'||Array.isArray(v[k]))v[k]={};if(!Array.isArray(v.errors))v.errors=[];if(!Array.isArray(v.history))v.history=[];return v}
function v20Log(message){const v=v20Ensure();v.history.unshift({day:s.day,phase:s.phase,message});v.history=v.history.slice(0,80);save(false)}
function v20Page(title,description){const el=$('main');el.replaceChildren(v14Text('h2',title,'sectionTitle'),v14Text('p',description,'notice'));return el}
function v20Card(title,desc){const c=document.createElement('section');c.className='v20-card';c.appendChild(v14Text('h3',title));if(desc)c.appendChild(v14Text('p',desc));return c}
function v20Actions(parent,actions){const r=document.createElement('div');r.className='v20-actions';for(const [label,fn,disabled] of actions)r.appendChild(button(label,fn,!!disabled));parent.appendChild(r)}
function v20SafeNum(x){return Number.isFinite(Number(x))?Number(x):0}
function v20Flow(){v20Ensure();v14ensure();v15ensure();v19arrivals();const el=v20Page('🩺 오늘의 통합 진료 흐름','[게임 확장] 기존 예약·접수·진료 데이터를 읽어 한 화면에서 확인합니다. 원본 기록을 덮어쓰지 않습니다.');const steps=v20Card('오늘의 단계',`${s.day}일 차 · ${v20Phases[s.phase]||'아침'} · 무료 진료`);const appts=v14Patients.map(p=>({p,key:p.id+'_'+s.day,ap:s.v14.appointments[p.id+'_'+s.day]}));const booked=appts.filter(x=>x.ap).length,checked=appts.filter(x=>x.ap?.status==='checked-in').length,completed=appts.filter(x=>!!s.v14.treatments[x.key]).length;for(const [name,val] of [['예약',booked],['접수',checked],['진료 완료',completed],['경과 상담',Object.keys(s.v15?.followups||{}).length]]){const r=document.createElement('div');r.className='v20-step';r.appendChild(v14Text('strong',name),v14Text('span',String(val)));steps.appendChild(r)}v20Actions(steps,[['예약 관리',()=>move('v14schedule')],['도착 알림·대기열',()=>move('v19queue')],['진료 선택',()=>move('v14care')],['후속 방문',()=>move('v15follow')]]);el.appendChild(steps);const grid=document.createElement('div');grid.className='v20-grid';for(const {p,key,ap} of appts){const treated=!!s.v14.treatments[key],loc=v16npc(p),status=treated?'진료 완료':!ap?'미예약':ap.status==='checked-in'?'접수 완료':s.phase<ap.phase?'예약 대기':'도착 확인 중';const c=v20Card(p.name,`${status} · ${loc} · ${ap?'예약 '+(v20Phases[ap.phase]||''): '예약 없음'}`);if(s.v19?.alerts?.[key])c.appendChild(v14Text('p','🔔 도착 알림 기록됨'));v20Actions(c,[['예약·접수 확인',()=>move('v19queue')],['환자 진료',()=>move('v14care')]]);grid.appendChild(c)}el.appendChild(grid)}
const v20Recovery=[{id:'cactus',name:'선인장 운반대',text:'가시가 덜 위험한 방향으로 화분을 놓았다. 시장에 작은 안내판이 붙었다.'},{id:'kettle',name:'주전자 찻자리',text:'주전자 장인은 이제 밤에는 뚜껑을 내려놓는다. 그늘에 찻잔 두 개가 놓였다.'},{id:'hat',name:'분실물 선반',text:'모자 장수는 선반에 번호표를 붙였다. 자기 모자 세 개부터 세어 본다.'},{id:'radio',name:'저녁 방송',text:'라디오 수리공은 방송 시간을 줄이고, 저녁에는 동네 소식만 전한다.'}];
function v20Village(){const v=v20Ensure(),el=v20Page('🏘️ 회복이 남긴 마을 풍경','[게임 확장] 기존 코미디 환자 재방문 2단계 및 연쇄 후일담 기록을 조건으로 합니다. 새로운 장소와 사건은 원작 확정이 아닙니다.');const grid=document.createElement('div');grid.className='v20-grid';for(const t of v20Recovery){const stage=v20SafeNum(s.v17?.visits?.[t.id]?.stage),prior=!!s.v19?.chain?.[t.id]||!!s.v18?.village?.[t.id],ready=stage>=2||prior,done=!!v.community[t.id];const c=v20Card(t.name,done?t.text:ready?'마을 변화 확인 가능':'환자 재방문 2단계 또는 기존 마을 후일담 필요');v20Actions(c,[['마을 변화 기록',()=>{if(!ready||v.community[t.id])return;v.community[t.id]={day:s.day,text:t.text};modify({peace:1});v20Log('마을 변화: '+t.name);v20Village()},!ready||done],['기존 연쇄 후일담',()=>move('v19chain')]]);grid.appendChild(c)}el.appendChild(grid)}
function v20Economy(){const v=v20Ensure(),el=v20Page('📊 운영 균형과 물자 안전망','[게임 확장] 무료 진료를 유지하며 지원금과 물자를 관리합니다. 하루 한 번만 실행하며 기존 장부와 중복 기록하지 않습니다.');const key=String(s.day),used=!!v.economy[key],c=v20Card('오늘의 운영 현황',`지원금 ${s.coins} · 공용 소모품 ${s.supplies} · 신뢰 ${s.trust} · 평온 ${s.peace}`);const actions=[['긴급 물자 보충',{coins:-3,supplies:4},()=>v20SafeNum(s.coins)>=3],['소모품 공동 나눔',{supplies:-2,trust:2},()=>v20SafeNum(s.supplies)>=2],['휴식과 재고 정리',{tired:-3,peace:1},()=>true]];for(const [name,delta,allowed] of actions)v20Actions(c,[[name,()=>{if(v.economy[key]||!allowed())return;const before={coins:s.coins,supplies:s.supplies};modify(delta);v.economy[key]={day:s.day,name,before,after:{coins:s.coins,supplies:s.supplies}};v20Log('운영: '+name);v20Economy()},used||!allowed()]]);el.appendChild(c);const entries=Object.values(v.economy).sort((a,b)=>b.day-a.day).slice(0,12);if(entries.length){const log=v20Card('최근 운영 선택');for(const e of entries)log.appendChild(v14Text('p',`${e.day}일 차 · ${e.name} · 지원금 ${e.before.coins}→${e.after.coins}, 물자 ${e.before.supplies}→${e.after.supplies}`));el.appendChild(log)}v20Actions(el,[['기존 운영 장부',()=>move('v19ledger')],['약품 재고',()=>move('v07stock')]])}
const v20Daniel=[{id:'quiet-call',day:3,title:'짧은 통화의 여백',text:'수화기 너머로 먼지 섞인 바람 소리가 들렸다.\n\n“코트리먼. 별일 없나?”\n“없어, D. 오늘은 주전자 때문에 소란스러웠지만.”\n\n둘은 잠시 아무 말도 하지 않았다. 그 침묵이 어색하지 않았다.',choices:['오늘의 진료소 이야기를 더 들려준다','다음 통화를 기약한다']},{id:'chess',day:6,title:'한 수의 무게',text:'휴가 중 들른 다니엘이 체스판을 꺼냈다. 미겔은 말 하나를 조용히 옮겼다.\n\n“봐주지 않는군.”\n“당연하지, D.”',choices:['끝까지 승부한다','차를 끓이고 다음 판을 둔다']},{id:'parcel',day:9,title:'봉투 속 작은 목록',text:'다니엘이 보낸 봉투에는 필요한 물품을 묻는 짧은 메모가 있었다. 미겔은 종이를 뒤집어 썼다.\n\n“붕대. 소독약. 그리고 네 안부.”',choices:['답장을 쓴다','목록을 진료소 서랍에 둔다']},{id:'visit',day:12,title:'문턱을 넘는 소리',text:'발소리가 멈추자 미겔은 고개를 들었다. 익숙한 걸음걸이였다.\n\n“D.”\n“코트리먼.”\n\n진료소의 오후가 조금 느려졌다.',choices:['따뜻한 차를 내온다','오늘의 마을을 함께 걷는다']}];
function v20DanielPage(){const v=v20Ensure(),el=v20Page('💜 다니엘과 평범한 날들','[원작 확정] 두 사람은 연인이며 다니엘은 현역 군인입니다. [게임 확장] 아래 대사·일정·선택지는 비공식 창작입니다.');const grid=document.createElement('div');grid.className='v20-grid';for(const t of v20Daniel){const seen=v.daniel[t.id],open=s.day>=t.day,c=v20Card(t.title,seen?'완료 · '+seen.choice:open?'열람 가능':`${t.day}일 차부터`);if(seen)c.appendChild(v14Text('p',t.text));else v20Actions(c,[['이야기 열기',()=>{if(!open||v.daniel[t.id])return;c.appendChild(v14Text('p',t.text));v20Actions(c,t.choices.map(choice=>[choice,()=>{if(v.daniel[t.id])return;v.daniel[t.id]={day:s.day,choice};modify({peace:1});v20Log('다니엘: '+t.title);v20DanielPage()},false]))},!open]]);grid.appendChild(c)}el.appendChild(grid)}
function v20Backup(){const el=v20Page('🛡️ 저장 데이터 복구와 오류 진단','저장 키 miguel_clinic_v02 · version: 2를 유지합니다. 백업 파일은 이 기기에 직접 저장됩니다. 복원 전 현재 저장을 먼저 백업해 주세요.');const v=v20Ensure(),status=v20Card('현재 상태',`게임 ${s.day}일 차 / ${v20Phases[s.phase]} · 저장 버전 ${s.version} · 진료 기록 ${Array.isArray(s.records)?s.records.length:0}개`);v20Actions(status,[['JSON 백업 내려받기',()=>{try{save(false);const raw=localStorage.getItem(v20KEY);if(!raw)throw Error('저장 데이터 없음');const blob=new Blob([raw],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`miguel-clinic-save-day-${s.day}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){v20Capture(e,'백업');alert('백업 실패: '+e.message)}}],['저장 검사',()=>{const report=v20CheckSave();alert(report.join('\n'))}]]);el.appendChild(status);const restore=v20Card('JSON 파일에서 복원','기존 데이터를 덮어쓰므로 백업 후 사용해 주세요. 파일의 필수 구조를 검사한 뒤 적용합니다.');const file=document.createElement('input');file.type='file';file.accept='.json,application/json';file.setAttribute('aria-label','저장 데이터 JSON 파일 선택');restore.appendChild(file);v20Actions(restore,[['선택한 파일 복원',async()=>{try{const f=file.files?.[0];if(!f)throw Error('JSON 파일을 선택해 주세요');if(f.size>2_000_000)throw Error('파일이 너무 큽니다');const candidate=JSON.parse(await f.text());const errors=v20Validate(candidate);if(errors.length)throw Error(errors.join(', '));if(!confirm('현재 저장 데이터를 새 파일로 교체할까요?'))return;localStorage.setItem(v20KEY,JSON.stringify(candidate));location.reload()}catch(e){v20Capture(e,'복원');alert('복원하지 못했습니다: '+e.message)}}]]);el.appendChild(restore);const errors=v20Card('오류 기록',v.errors.length?`최근 ${v.errors.length}건`:'현재 이 버전에서 수집된 오류가 없습니다.');for(const e of v.errors.slice(-8).reverse())errors.appendChild(v14Text('p',`${e.day}일 차 · ${e.source} · ${e.message}`,'v20-error'));v20Actions(errors,[['진단 결과 복사',()=>{const report=[...v20CheckSave(),...v.errors.map(e=>`${e.source}: ${e.message}`)].join('\n');if(navigator.clipboard?.writeText)navigator.clipboard.writeText(report).then(()=>alert('복사했습니다')).catch(()=>alert(report));else alert(report)}]]);el.appendChild(errors)}
function v20Validate(x){const e=[];if(!x||typeof x!=='object'||Array.isArray(x))return ['JSON 객체가 아닙니다'];if(x.version!==2)e.push('version: 2가 아닙니다');if(!Number.isInteger(x.day)||x.day<1)e.push('날짜가 올바르지 않습니다');if(!Number.isInteger(x.phase)||x.phase<0||x.phase>3)e.push('시간대가 올바르지 않습니다');if(!x.flags||typeof x.flags!=='object'||Array.isArray(x.flags))e.push('flags 누락');if(!Array.isArray(x.records))e.push('records 누락');return e}
function v20CheckSave(){const errors=v20Validate(s),raw=localStorage.getItem(v20KEY);let persisted='저장 파일 없음';try{if(raw){const d=JSON.parse(raw);persisted=v20Validate(d).length?'저장 구조 경고: '+v20Validate(d).join(', '):'저장 구조 정상'}}catch(e){persisted='저장 JSON 파싱 실패'}return [`저장 키: ${v20KEY}`,`현재 상태: ${errors.length?errors.join(', '):'정상'}`,persisted,`진료 기록: ${s.records?.length||0}개`,`v2.0 진단 오류: ${v20Ensure().errors.length}건`]}
function v20Capture(error,source){try{const v=v20Ensure();v.errors.push({day:s.day,source,message:String(error?.message||error).slice(0,240)});v.errors=v.errors.slice(-25);save(false)}catch(_){}}
window.addEventListener('error',e=>v20Capture(e.error||e.message,'스크립트'));
window.addEventListener('unhandledrejection',e=>v20Capture(e.reason,'비동기 작업'));
const v20PrevNext=next;next=function(){const oldDay=s.day,oldPhase=s.phase;v20PrevNext();v20Ensure();if(oldDay!==s.day||oldPhase!==s.phase){v19arrivals();v20Log('시간 이동: '+s.day+'일 차 '+v20Phases[s.phase])}render()};
const v20PrevRender=render;render=function(){v20Ensure();v20PrevRender();const pages={v20flow:v20Flow,v20village:v20Village,v20economy:v20Economy,v20daniel:v20DanielPage,v20backup:v20Backup};if(pages[s.tab])pages[s.tab]()};
for(const [id,label] of [['v20flow','🩺 진료 흐름'],['v20village','🏘️ 회복 마을'],['v20economy','📊 물자 균형'],['v20daniel','💜 일상 이야기'],['v20backup','🛡️ 저장·진단']]){if(!document.querySelector(`[data-tab="${id}"]`)){const b=button(label,()=>move(id));b.dataset.tab=id;document.querySelector('nav.tabs').insertBefore(b,document.querySelector('[data-tab="updates"]'))}}
v20Ensure();render();


/* v2.1 additive stabilization: never rewrite previous schema or delete previous features. */
const v21Phases=['아침','낮','오후','저녁'];
function v21Ensure(){if(!s.v21||typeof s.v21!=='object'||Array.isArray(s.v21))s.v21={};const v=s.v21;for(const k of ['notified','completed','economy','daniel','neighbors','followups'])if(!v[k]||typeof v[k]!=='object'||Array.isArray(v[k]))v[k]={};if(!Array.isArray(v.log))v.log=[];if(!Array.isArray(v.reports))v.reports=[];return v}
function v21Log(message){const v=v21Ensure();v.log.unshift({day:s.day,phase:s.phase,message});v.log=v.log.slice(0,90);save(false)}
function v21Page(title,description){const el=$('main');el.replaceChildren(v14Text('h2',title,'sectionTitle'),v14Text('p',description,'notice'));return el}
function v21Card(title,desc){const c=document.createElement('section');c.className='v21-card';c.appendChild(v14Text('h3',title));if(desc)c.appendChild(v14Text('p',desc));return c}
function v21Actions(parent,items){const r=document.createElement('div');r.className='v20-actions';for(const [label,fn,disabled] of items)r.appendChild(button(label,fn,!!disabled));parent.appendChild(r)}
function v21Appointments(){v21Ensure();v14ensure();v15ensure();v19ensure();v18checkArrivals();const v=v21Ensure(),out=[];for(const p of v14Patients){const key=p.id+'_'+s.day,ap=s.v14.appointments[key];if(!ap)continue;const treated=!!s.v14.treatments[key];const arrived=ap.status==='checked-in'||ap.status==='completed';const status=treated?'진료 완료':arrived?'접수 완료':s.phase<ap.phase?'예약 대기':'도착 대기';if(arrived&&!v.notified[key]){v.notified[key]={day:s.day,phase:s.phase};v21Log(p.name+' 예약 환자 도착 확인')}if(treated&&!v.completed[key]){v.completed[key]={day:s.day,phase:s.phase};v21Log(p.name+' 진료 완료 확인')}out.push({p,key,ap,status,treated,arrived})}return out}
function v21Flow(){const rows=v21Appointments(),el=v21Page('🩺 v2.1 진료 흐름 점검','[게임 확장] 기존 예약·접수·진료·재방문 기록을 읽어 단계별 상태를 보여 줍니다. 중복 도착·완료 알림은 저장된 식별자로 차단합니다.');const summary=v21Card('오늘의 현황',`${s.day}일 차 · ${v21Phases[s.phase]} · 예약 ${rows.length}건 · 접수 ${rows.filter(x=>x.arrived).length}건 · 완료 ${rows.filter(x=>x.treated).length}건`);v21Actions(summary,[['예약 등록',()=>move('v14schedule')],['도착·대기열',()=>move('v19queue')],['진료 진행',()=>move('v14care')],['후속 방문',()=>move('v15follow')]]);el.appendChild(summary);const grid=document.createElement('div');grid.className='v21-grid';for(const r of rows){const c=v21Card(r.p.name,`예약 ${v21Phases[r.ap.phase]||'시간 미상'} · ${r.status} · 현재 위치: ${v16npc(r.p)}`);c.appendChild(v14Text('p',r.treated?'완료된 진료는 다시 처리하지 않습니다.':r.arrived?'접수 완료. 기존 진료 선택 화면에서 이어서 진행하세요.':'환자가 아직 도착하지 않았습니다. 예약은 보존됩니다.'));v21Actions(c,[['진료 선택',()=>move('v14care'),!r.arrived||r.treated],['예약·접수 확인',()=>move('v19queue')]]);grid.appendChild(c)}el.appendChild(grid);if(!rows.length)el.appendChild(v14Text('p','오늘 예약이 없습니다. 기존 예약 메뉴에서 등록할 수 있습니다.'))}
function v21Economy(){const v=v21Ensure(),el=v21Page('⚖️ 무료 진료소 운영 균형','[게임 확장] v2.1의 추가 운영 지원은 하루 한 번만 가능하며 지원금·공용 물자의 과도한 누적을 제한합니다. 기존 장부와 운영 선택은 그대로 남습니다.');const used=!!v.economy[s.day],c=v21Card('현재 자원',`지원금 ${s.coins} · 공용 소모품 ${s.supplies} · 피로 ${s.tired} · 주민 신뢰 ${s.trust}`);const options=[['소모품 소량 보충',{coins:-2,supplies:3},()=>s.coins>=2&&s.supplies<=15],['지원 물자 정리',{supplies:2,tired:2},()=>s.supplies<=12],['휴식하며 장부 점검',{tired:-4,peace:1},()=>true]];for(const [name,delta,allowed] of options)v21Actions(c,[[name,()=>{if(v.economy[s.day]||!allowed())return;const before={coins:s.coins,supplies:s.supplies};modify(delta);v.economy[s.day]={name,before,after:{coins:s.coins,supplies:s.supplies}};v21Log('운영 점검: '+name);v21Economy()},used||!allowed()]]);el.appendChild(c);const logs=v21Card('최근 운영 점검');for(const [day,e] of Object.entries(v.economy).slice(-12).reverse())logs.appendChild(v14Text('p',`${day}일 차 · ${e.name} · 지원금 ${e.before.coins}→${e.after.coins}, 소모품 ${e.before.supplies}→${e.after.supplies}`));el.appendChild(logs);v21Actions(el,[['기존 운영 장부',()=>move('v19ledger')],['재고 관리',()=>move('v07stock')]])}
const v21Neighbors=[{id:'tea',name:'차 한 잔의 안부',day:3,text:'할머니는 차를 마시러 들렀다. “오늘은 아픈 데가 아니라, 차가 식을까 봐 왔지.” 미겔은 찻잔을 한 개 더 꺼냈다.'},{id:'chair',name:'의자의 새 자리',day:6,text:'시장의 의자가 햇볕을 피해 조금 옮겨졌다. “여기가 더 시원해요.” 이웃들은 고개를 끄덕였다.'},{id:'radio',name:'라디오의 조용한 시간',day:9,text:'라디오 수리공은 방송을 한 시간 줄였다. 대신 사람들은 저녁에 직접 만나 안부를 나눴다.'}];
function v21Village(){const v=v21Ensure(),el=v21Page('🏘️ 주민의 작은 일상','[해석] 진료소는 미겔이 스스로 선택한 삶의 공간입니다. [게임 확장] 아래 사건과 등장 일정은 비공식 창작입니다.');const grid=document.createElement('div');grid.className='v21-grid';for(const t of v21Neighbors){const seen=v.neighbors[t.id],ready=s.day>=t.day,c=v21Card(t.name,seen?t.text:ready?'새로운 일상 이야기':'개방: '+t.day+'일 차');v21Actions(c,[['이웃 이야기 보기',()=>{if(!ready||v.neighbors[t.id])return;v.neighbors[t.id]={day:s.day};modify({peace:1});v21Log('주민 일상: '+t.name);v21Village()},!ready||!!seen]]);grid.appendChild(c)}el.appendChild(grid);v21Actions(el,[['기존 마을 변화',()=>move('v20village')],['주민 관계',()=>move('v19relations')]])}
const v21Daniel=[{id:'cup',day:4,title:'남겨 둔 찻잔',text:'휴가를 맞아 들른 다니엘은 빈 찻잔을 씻어 놓았다.\n“D. 그건 내가 하려던 건데.”\n“이미 끝났습니다, 코트리먼.”\n미겔은 대답 대신 다음 잔을 꺼냈다.',choices:['차를 한 잔 더 따른다','창가에 함께 앉는다']},{id:'letter',day:8,title:'짧아도 충분한 편지',text:'미겔은 오늘 진료소에서 있었던 사소한 일을 적었다. 마지막 줄은 짧았다.\n“D. 나는 잘 지내. 너도 잘 지내.”',choices:['봉투를 접는다','내일의 이야기도 적어 둔다']},{id:'board',day:13,title:'다음 판도 진심으로',text:'다니엘이 체스 말을 놓았다.\n“이번에는 어떻습니까, 코트리먼?”\n“D. 시작도 안 했는데 벌써 결과를 묻나.”\n미겔은 단 한 수도 양보할 생각이 없었다.',choices:['곧바로 대국한다','차를 준비한 뒤 대국한다']},{id:'steps',day:18,title:'문밖의 발소리',text:'진료소 문 앞에서 발걸음이 멎었다. 미겔은 목소리가 들리기도 전에 익숙한 걸음의 박자를 알아챘다.\n“왔어, D?”\n“네, 코트리먼.”',choices:['오늘의 진료소를 소개한다','함께 마을을 걷는다']}];
function v21DanielPage(){const v=v21Ensure(),el=v21Page('💜 미겔과 다니엘의 일상','[원작 확정] 연인 관계와 호칭, 다니엘의 군 복무, 미겔의 자발적 전역 및 체스 태도를 유지합니다. [게임 확장] 아래 대사·일정·선택지는 신규 창작입니다.');const grid=document.createElement('div');grid.className='v21-grid';for(const t of v21Daniel){const seen=v.daniel[t.id],ready=s.day>=t.day,c=v21Card(t.title,seen?'완료 · '+seen.choice:ready?'이야기를 읽을 수 있습니다':`${t.day}일 차부터`);if(seen)c.appendChild(v14Text('p',t.text.replaceAll('\\n','\n')));else v21Actions(c,[['이야기 열기',()=>{if(!ready||v.daniel[t.id])return;c.appendChild(v14Text('p',t.text.replaceAll('\\n','\n')));v21Actions(c,t.choices.map(choice=>[choice,()=>{if(v.daniel[t.id])return;v.daniel[t.id]={day:s.day,choice};modify({peace:1});v21Log('다니엘 일상: '+t.title);v21DanielPage()},false]))},!ready]]);grid.appendChild(c)}el.appendChild(grid)}
function v21Validate(candidate){const e=v20Validate(candidate);if(e.length)return e;for(const key of ['records','eventsSeen','messages'])if(candidate[key]!==undefined&&!Array.isArray(candidate[key]))e.push(key+' 배열 형식 오류');for(const key of ['v14','v15','v19','v20','v21'])if(candidate[key]!==undefined&&(!candidate[key]||typeof candidate[key]!=='object'||Array.isArray(candidate[key])))e.push(key+' 객체 형식 오류');if(candidate.day>1000000)e.push('날짜 범위 오류');return e}
function v21Recovery(){const el=v21Page('🛡️ 안전 백업·복구 및 진단','저장 키 miguel_clinic_v02 · version: 2 유지. 복원 시 현재 저장 데이터를 별도 안전 슬롯에 먼저 보관하고, 쓰기 실패 시 롤백을 시도합니다.');const c=v21Card('저장 데이터 안전 검사');v21Actions(c,[['현재 저장 검증',()=>{let info;try{const raw=localStorage.getItem(KEY);info=raw?v21Validate(JSON.parse(raw)) : ['저장 데이터 없음']}catch(e){info=['JSON 파싱 실패: '+e.message]}alert(info.length?info.join('\n'):'저장 데이터 구조 검사 통과')}],['기존 JSON 백업 화면',()=>move('v20backup')]]);el.appendChild(c);const restore=v21Card('복원 전 안전 슬롯 생성','복원 파일은 2MB 이하 JSON이어야 합니다. 기존 데이터를 보존할 공간이 없으면 복원을 중단합니다.');const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.setAttribute('aria-label','복원할 JSON 저장 파일');restore.appendChild(input);v21Actions(restore,[['검증 후 안전 복원',async()=>{try{const f=input.files?.[0];if(!f)throw Error('파일을 선택해 주세요');if(f.size>2000000)throw Error('2MB 초과 파일은 지원하지 않습니다');const raw=await f.text(),candidate=JSON.parse(raw),issues=v21Validate(candidate);if(issues.length)throw Error(issues.join(', '));if(!confirm('현재 저장을 안전 슬롯에 보관한 후 복원할까요?'))return;const old=localStorage.getItem(KEY),backupKey=KEY+'_v21_pre_restore';if(old!==null)localStorage.setItem(backupKey,old);try{localStorage.setItem(KEY,JSON.stringify(candidate))}catch(e){if(old!==null)try{localStorage.setItem(KEY,old)}catch(_){}throw e}location.reload()}catch(e){v20Capture(e,'v2.1 안전 복원');alert('복원 중단: '+e.message)}}],['안전 슬롯에서 되돌리기',()=>{try{const raw=localStorage.getItem(KEY+'_v21_pre_restore');if(!raw)throw Error('안전 슬롯이 없습니다');const issues=v21Validate(JSON.parse(raw));if(issues.length)throw Error(issues.join(', '));if(!confirm('안전 슬롯의 이전 저장으로 되돌릴까요?'))return;localStorage.setItem(KEY,raw);location.reload()}catch(e){alert('되돌리기 실패: '+e.message)}}]]);el.appendChild(restore);const diagnostics=v21Card('진료 흐름 진단');v21Actions(diagnostics,[['예약 상태 진단',()=>{try{const rows=v21Appointments(),issues=[];for(const r of rows){if(r.treated&&!r.arrived)issues.push(r.p.name+': 진료 완료이나 접수 기록 확인 필요');if(!Number.isInteger(r.ap.phase)||r.ap.phase<0||r.ap.phase>3)issues.push(r.p.name+': 예약 시간 오류')}const result=issues.length?issues.join('\n'):`예약 ${rows.length}건 검사 완료 · 특이 사항 없음`;v21Ensure().reports.unshift({day:s.day,result});v21Ensure().reports=v21Ensure().reports.slice(0,20);save(false);alert(result)}catch(e){v20Capture(e,'v2.1 진료 진단');alert('진단 오류: '+e.message)}}],['오류 진단 화면',()=>move('v20backup')]]);el.appendChild(diagnostics);const log=v21Card('최근 v2.1 기록');log.classList.add('v21-log');for(const item of v21Ensure().log.slice(0,15))log.appendChild(v14Text('p',`${item.day}일 차 · ${v21Phases[item.phase]||''} · ${item.message}`));el.appendChild(log)}
const v21PreviousNext=next;next=function(){const beforeDay=s.day,beforePhase=s.phase;v21PreviousNext();if(beforeDay!==s.day||beforePhase!==s.phase){v21Appointments();} };
