/* v2.2 additive quality and play-test dashboard. [게임 확장] */
function v22Ensure(){if(!s.v22||typeof s.v22!=='object'||Array.isArray(s.v22))s.v22={};const v=s.v22;for(const k of ['seen','daniel','stories','ledger'])if(!v[k]||typeof v[k]!=='object'||Array.isArray(v[k]))v[k]={};if(!Array.isArray(v.tests))v.tests=[];if(!Array.isArray(v.errors))v.errors=[];return v}
