function v22Audit(){const findings=[],checks=[];const check=(label,ok,detail)=>{checks.push({label,ok,detail});if(!ok)findings.push(label+': '+detail)};check('저장 키 및 버전',s.version===2&&KEY==='miguel_clinic_v02','version:2 / miguel_clinic_v02 필요');check('기본 진료 기록',Array.isArray(s.records),'records 배열 필요');check('시간대',Number.isInteger(s.phase)&&s.phase>=0&&s.phase<=3,'시간대 0~3');check('날짜',Number.isInteger(s.day)&&s.day>=1,'날짜 1 이상');const ap=s.v14?.appointments||{},tx=s.v14?.treatments||{};let duplicates=0,completed=0,waiting=0;for(const [key,a] of Object.entries(ap)){if(!a||typeof a!=='object'){findings.push('예약 객체 오류 '+key);continue}if(a.status==='completed'||tx[key])completed++;else waiting++;if(tx[key]&&a.status==='checked-in')duplicates++}check('진료 완료 중복 상태',duplicates===0,duplicates+'건: 기록은 보존하며 자동 변경하지 않음');const v=v22Ensure();check('기존 알림 저장',!!s.v21?.notified&&typeof s.v21.notified==='object','v2.1 알림 기록 확인');const raw=localStorage.getItem(KEY);let parsed=null;try{parsed=raw?JSON.parse(raw):null}catch(e){findings.push('저장 JSON 파싱 실패')};check('저장 데이터 구조',!raw||!v21Validate(parsed).length,'복원 전 검증 권장');const summary={day:s.day,phase:s.phase,checks,findings,appointments:Object.keys(ap).length,waiting,completed,records:s.records?.length||0};v.tests.unshift(summary);v.tests=v.tests.slice(0,15);save(false);return summary}
function v22Dashboard(){const v=v22Ensure(),el=v21Page('🧪 v2.2 플레이 테스트','[게임 확장] 현재 저장 데이터를 읽는 비파괴 진단입니다. 테스트가 실제 진료를 대신 수행하거나 기존 기록을 수정하지 않습니다.');const c=v21Card('예약 → 접수 → 진료 → 재방문','현재 날짜와 기록을 점검합니다. 진료 완료·예약 상태가 서로 다르면 경고하고 자동으로 삭제하지 않습니다.');v21Actions(c,[['현재 상태 점검',()=>{try{v22Audit();v22Dashboard()}catch(e){v22Record(e.message);alert('점검 오류: '+e.message)}}],['기존 통합 진료',()=>move('v20flow')],['대기열',()=>move('v19queue')],['후속 방문',()=>move('v15follow')]]);el.appendChild(c);const latest=v.tests[0];if(latest){const r=v21Card('최근 점검 결과',`${latest.day}일 차 · 예약 ${latest.appointments}건 · 대기 ${latest.waiting}건 · 완료 ${latest.completed}건 · 기록 ${latest.records}건`);for(const t of latest.checks)r.appendChild(v14Text('p',(t.ok?'✓ ':'⚠ ')+t.label+(t.ok?'':' — '+t.detail)));for(const e of latest.findings)r.appendChild(v14Text('p','주의: '+e));el.appendChild(r)}const safety=v21Card('저장 복구 체크리스트','1. 기존 저장 JSON 내보내기  2. 백업 파일 구조 검사  3. 안전 슬롯 저장  4. 복원  5. 날짜·진료 기록 확인');v21Actions(safety,[['기존 백업·복원',()=>move('v21recovery')],['저장 진단',()=>move('v20backup')]]);el.appendChild(safety)}
const v22Patients=[{id:'shade',day:5,title:'양산의 명예',text:'우산 수집가가 접이식 양산을 들고 돌아왔다. “이제 한 개만 들고 다녀요. 하지만 색깔은 매일 바꿉니다!” 미겔은 어깨를 확인하고 고개를 끄덕였다.'},{id:'pot',day:8,title:'주전자의 사과',text:'주전자 장인이 작은 차통을 내밀었다. “소리를 줄였더니 제가 더 잘 들리더군요.” 미겔은 웃음을 참으며 차를 받았다.'},{id:'hat',day:11,title:'모자 세 개의 행방',text:'모자 장수가 잃어버린 모자를 찾았다며 들어왔다. 머리 위에는 여전히 세 개가 얹혀 있었다. “오늘은 모두 제 거예요!”'},{id:'radio',day:14,title:'라디오의 쉬는 시간',text:'라디오 수리공이 저녁 방송을 줄였다. “그 대신 사람들이 직접 와서 떠들어요.” 미겔은 목을 쉬게 하라고 권했다.'}];
function v22Village(){const v=v22Ensure(),el=v21Page('🏘️ 다시 만난 이웃들','[게임 확장] 환자의 후속 진료와 기존 마을 이벤트를 바탕으로 개방되는 일상 장면입니다.');for(const t of v22Patients){const done=!!v.stories[t.id],ready=s.day>=t.day;const c=v21Card(t.title,done?t.text:ready?'새로운 이웃의 이야기가 도착했습니다.':`${t.day}일 차부터 개방`);v21Actions(c,[['이야기 확인',()=>{if(!ready||v.stories[t.id])return;v.stories[t.id]={day:s.day};modify({peace:1});v22Village()},!ready||done]]);el.appendChild(c)}v21Actions(el,[['기존 코미디 환자 재방문',()=>move('v17follow')],['마을 연쇄 소문',()=>move('v19village')]])}
const v22Daniel=[{id:'calendar',day:5,title:'달력의 빈칸',text:'미겔은 진료소 달력의 빈칸을 세었다. D의 휴가가 언제든, 오늘 할 일은 그대로였다. 짧은 편지 끝에 적었다. “D. 오늘은 환자가 넷. 별일 없어.”',choices:['편지를 접는다','내일의 빈칸도 남긴다']},{id:'cup',day:10,title:'서로 다른 찻잔',text:'휴가 중 들른 다니엘이 찻잔을 꺼냈다. “코트리먼, 이 잔은 어디에 둘까요?” “D. 창가. 바람만 피해서.”',choices:['창가에서 차를 마신다','진료소 정리를 마친다']},{id:'chess',day:15,title:'끝까지 두는 수',text:'미겔은 체스 말을 옮겼다. “D. 봐주진 않아.” 대답을 기다리는 동안에도 다음 수를 생각했다.',choices:['다음 수를 둔다','잠시 물을 마신다']},{id:'post',day:20,title:'짧은 소식의 무게',text:'우편소에서 편지 한 장이 도착했다. 미겔은 익숙한 필체를 확인한 뒤 조용히 봉투를 열었다. 오늘 하루도 평범하게 이어졌다.',choices:['답장을 쓴다','편지를 서랍에 둔다']}];
function v22DanielPage(){const v=v22Ensure(),el=v21Page('💜 다니엘과 미겔 · 신규 일상','[원작 확정] 연인 관계·호칭과 군 복무 설정을 유지합니다. [게임 확장] 신규 대사·선택지는 공식 로그가 아닙니다.');for(const t of v22Daniel){const seen=v.daniel[t.id],ready=s.day>=t.day,c=v21Card(t.title,seen?t.text:ready?'읽을 수 있습니다.':`${t.day}일 차부터`);if(!seen)v21Actions(c,[['읽기',()=>{if(!ready||v.daniel[t.id])return;c.appendChild(v14Text('p',t.text));v21Actions(c,t.choices.map(choice=>[choice,()=>{if(v.daniel[t.id])return;v.daniel[t.id]={day:s.day,choice};modify({peace:1});v22DanielPage()},false]))},!ready]]);el.appendChild(c)}}
function v22Economy(){const v=v22Ensure(),el=v21Page('📊 운영 균형 · 일일 장부','[게임 확장] 기존 물자 경제를 변경하지 않고 자원 현황과 추가 운영 선택의 결과를 기록합니다.');const used=v.ledger[s.day],c=v21Card('오늘의 자원',`지원금 ${s.coins} · 소모품 ${s.supplies} · 피로 ${s.tired} · 신뢰 ${s.trust}`);const choices=[['소모품 구매',{coins:-2,supplies:3},()=>s.coins>=2&&s.supplies<=15],['기부 물품 분류',{supplies:2,tired:1},()=>s.supplies<=12],['장부 정리와 휴식',{tired:-3,peace:1},()=>true]];for(const [label,delta,allow] of choices)v21Actions(c,[[label,()=>{if(v.ledger[s.day]||!allow())return;const before={coins:s.coins,supplies:s.supplies};modify(delta);v.ledger[s.day]={label,before,after:{coins:s.coins,supplies:s.supplies}};v22Economy()},!!used||!allow()]]);el.appendChild(c);const history=v21Card('최근 기록');for(const [day,item] of Object.entries(v.ledger).slice(-10).reverse())history.appendChild(v14Text('p',`${day}일 차 · ${item.label} · 지원금 ${item.before.coins}→${item.after.coins} / 소모품 ${item.before.supplies}→${item.after.supplies}`));el.appendChild(history);v21Actions(el,[['기존 운영 장부',()=>move('v19ledger')],['기존 운영 균형',()=>move('v21economy')]])}
