/* v2.3 additive integration checks and safe recovery. [게임 확장] */
function v23Ensure(){if(!s.v23||typeof s.v23!=='object'||Array.isArray(s.v23))s.v23={};const v=s.v23;for(const k of ['stories','daniel','economy'])if(!v[k]||typeof v[k]!=='object'||Array.isArray(v[k]))v[k]={};if(!Array.isArray(v.runs))v.runs=[];return v}
function v23Simulate(){const cases=[],add=(name,pass,detail)=>cases.push({name,pass:!!pass,detail});const fresh={version:2,day:1,phase:0,flags:{},records:[]};add('이전 버전 저장 형식',v21Validate(fresh).length===0,'version:2 및 필수 필드');const booking={phase:1,status:'booked'},tx={};const status=()=>tx.patient?'completed':booking.status==='checked-in'?'checked-in':'booked';add('예약 생성',status()==='booked','예약 시간대 보존');booking.status='checked-in';add('도착·접수',status()==='checked-in','중복 접수 없이 상태 변경');tx.patient={day:1};add('진료 완료',status()==='completed','치료 기록이 최우선');const follow={due:3,stage:1};add('재방문 대기',follow.due>1&&follow.stage===1,'예정일과 단계 보존');const notify=new Set();const once=k=>{if(notify.has(k))return false;notify.add(k);return true};add('알림 중복 방지',once('patient_1')&&!once('patient_1'),'같은 환자·날짜는 한 번');const candidate=JSON.parse(JSON.stringify(fresh));candidate.version=3;add('잘못된 복원 거절',v21Validate(candidate).length>0,'버전 불일치 차단');add('기존 데이터 불변',fresh.version===2&&fresh.records.length===0,'격리된 가상 상태만 변경');return cases}
function v23Audit(){v14ensure();v15ensure();const issues=[],appointments=s.v14.appointments||{},treatments=s.v14.treatments||{};for(const [key,ap] of Object.entries(appointments)){if(!ap||typeof ap!=='object'){issues.push(key+': 예약 데이터 형식 오류');continue}if(!Number.isInteger(ap.phase)||ap.phase<0||ap.phase>3)issues.push(key+': 예약 시간대 오류');if(treatments[key]&&ap.status==='checked-in')issues.push(key+': 진료 완료 후 접수 상태 잔존 (기록 유지)')}for(const [key,f] of Object.entries(s.v15.followups||{})){if(f&&typeof f==='object'&&(!Number.isFinite(f.due)||f.due<1))issues.push(key+': 재방문 예정일 오류')}return issues}
function v23TestPage(){const v=v23Ensure(),el=v21Page('🧪 v2.3 통합 테스트','[게임 확장] 가상 상태로 예약→접수→진료→재방문·중복 알림·복원 거절을 검사합니다. 실제 환자 데이터는 수정하지 않습니다.');const c=v21Card('자동 시나리오 실행','테스트는 별도의 메모리 객체에서 실행되며 결과만 기록합니다.');v21Actions(c,[['7가지 가상 시나리오 실행',()=>{const tests=v23Simulate(),issues=v23Audit();v.runs.unshift({day:s.day,phase:s.phase,tests,issues});v.runs=v.runs.slice(0,12);save(false);v23TestPage()}],['기존 플레이 진단',()=>move('v22test')]]);el.appendChild(c);const last=v.runs[0];if(last){const report=v21Card('최근 실행',`${last.day}일 차 · ${last.tests.filter(x=>x.pass).length}/${last.tests.length} 통과 · 실제 기록 경고 ${last.issues.length}건`);for(const t of last.tests)report.appendChild(v14Text('p',(t.pass?'✓ ':'⚠ ')+t.name+' — '+t.detail));for(const issue of last.issues.slice(0,20))report.appendChild(v14Text('p','주의: '+issue));el.appendChild(report)} }
function v23Recovery(){const el=v21Page('🛡️ v2.3 복원 사전 검사','복원 파일을 적용하지 않고 구조·크기·기존 기록 개수를 먼저 비교합니다. 실제 복원은 기존 안전 슬롯 화면에서 진행합니다.');const c=v21Card('백업 JSON 사전 검사','파일을 선택한 뒤 검사하세요. 현재 저장은 변경되지 않습니다.');const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.setAttribute('aria-label','검사할 백업 JSON');c.appendChild(input);const result=v14Text('p','검사 대기');c.appendChild(result);v21Actions(c,[['파일 검사',async()=>{try{const f=input.files&&input.files[0];if(!f)throw Error('파일을 선택해 주세요');if(f.size>2000000)throw Error('2MB 제한 초과');const candidate=JSON.parse(await f.text());const errors=v21Validate(candidate);if(errors.length)throw Error(errors.join(' / '));result.textContent=`검사 통과 · 백업 ${candidate.day}일 차 · 진료 기록 ${candidate.records.length}건 / 현재 ${s.records.length}건. 실제 복원 전 기존 저장을 내보내세요.`}catch(e){result.textContent='복원 불가: '+e.message}}],['안전 슬롯 복원 화면',()=>move('v21recovery')]]);el.appendChild(c)}
const v23Stories=[{id:'chair',day:6,title:'진료소 의자의 비밀',text:'의자를 옮겨 달라는 부탁이 세 번이나 들어왔다. 미겔은 결국 바닥에 작은 표시를 남겼다. 다음 날, 의자는 제자리에 있었다.'},{id:'cactus',day:10,title:'선인장과 화해한 날',text:'선인장을 무서워하던 주민이 작은 화분을 내밀었다. “오늘은 가시가 먼저 인사하지 않더군요.” 미겔은 조용히 물 주는 법을 알려 주었다.'},{id:'tea',day:15,title:'찻잔이 하나 더',text:'할머니가 새 찻잔을 들고 왔다. “아픈 사람 말고도 쉬어 가는 사람이 있어야지.” 진료소 한쪽에 작은 찻자리가 생겼다.'}];
function v23Village(){const v=v23Ensure(),el=v21Page('🏘️ v2.3 주민 코미디','[게임 확장] 마을의 작은 소동과 따뜻한 후일담. 기존 기록은 그대로 유지합니다.');for(const t of v23Stories){const done=v.stories[t.id],ready=s.day>=t.day,c=v21Card(t.title,done?t.text:ready?'새 이야기가 열렸습니다':`${t.day}일 차부터`);v21Actions(c,[['이야기 보기',()=>{if(done||!ready)return;v.stories[t.id]={day:s.day};modify({peace:1});v23Village()},!ready||!!done]]);el.appendChild(c)}}
const v23Daniel=[{id:'post',day:5,title:'모래 묻은 편지',text:'미겔은 편지 봉투에 묻은 모래를 털었다. “D. 여기 바람은 여전해.” 답장에는 오늘 진료소의 사소한 일들을 적었다.'},{id:'chess',day:9,title:'양보 없는 한 판',text:'휴가 중 들른 다니엘이 체스판을 폈다. 미겔은 한 수를 오래 고민했다. “D. 이번에도 봐주진 않아.”'},{id:'lamp',day:13,title:'불이 켜진 창',text:'늦은 저녁, 미겔은 진료소 창가의 등을 켰다. 전화 너머에서 다니엘의 목소리가 들렸다. “코트리먼, 오늘도 수고했습니다.”'},{id:'walk',day:17,title:'같이 걷는 짧은 길',text:'휴가 중 두 사람은 마을을 천천히 걸었다. 미겔은 옆에서 들리는 익숙한 발소리에 맞춰 걸음을 늦췄다.'}];
function v23DanielPage(){const v=v23Ensure(),el=v21Page('💜 v2.3 다니엘과 미겔','[원작 확정] 연인 관계·호칭·군 복무·체스 태도 유지. [게임 확장] 새 대사와 일정은 비공식 창작입니다.');for(const t of v23Daniel){const done=v.daniel[t.id],ready=s.day>=t.day,c=v21Card(t.title,done?t.text:ready?'새 일상 이야기':'잠금 · '+t.day+'일 차');v21Actions(c,[['이야기 읽기',()=>{if(done||!ready)return;v.daniel[t.id]={day:s.day};modify({peace:1});v23DanielPage()},!ready||!!done]]);el.appendChild(c)}}
function v23Economy(){const v=v23Ensure(),el=v21Page('⚖️ v2.3 장기 운영','[게임 확장] 하루 한 번 소규모 지원만 선택할 수 있으며 자원 상한과 지출 기록을 적용합니다.');const old=v.economy[s.day],c=v21Card('오늘의 운영 선택',old?'완료: '+old.label:'한 번만 선택할 수 있습니다.');for(const [label,delta] of [['진료 물자 정리',{supplies:2,tired:1}],['휴식과 재고 확인',{tired:-2}],['이웃과 물자 나누기',{supplies:-1,trust:1}]])v21Actions(c,[[label,()=>{if(v.economy[s.day])return;if(delta.supplies<0&&(s.supplies||0)<1){alert('나눌 물자가 부족합니다');return}const safe={...delta};if(safe.supplies>0)safe.supplies=Math.min(safe.supplies,Math.max(0,30-(s.supplies||0)));modify(safe);v.economy[s.day]={label,delta:safe};save(false);v23Economy()},!!old]]);el.appendChild(c);const log=v21Card('최근 운영 기록');for(const [day,r] of Object.entries(v.economy).slice(-12).reverse())log.appendChild(v14Text('p',`${day}일 차 · ${r.label}`));el.appendChild(log)}
const v23OldRender=render;render=function(){v23Ensure();v23OldRender();const pages={v23test:v23TestPage,v23recovery:v23Recovery,v23village:v23Village,v23daniel:v23DanielPage,v23economy:v23Economy};if(pages[s.tab])pages[s.tab]()};
