/* v2.4: additive, read-only diagnostics and idempotent new events */
function v24Ensure(){if(!s.v24||typeof s.v24!=='object'||Array.isArray(s.v24))s.v24={};const v=s.v24;for(const k of ['stories','daniel','economy','notices'])if(!v[k]||typeof v[k]!=='object'||Array.isArray(v[k]))v[k]={};if(!Array.isArray(v.reports))v.reports=[];return v}
function v24AuditSnapshot(snapshot){const issues=[],st=snapshot||{},a=st.appointments||{},t=st.treatments||{},queue=st.queue||{},follow=st.followups||{},day=Number(st.day)||1,phase=Number(st.phase)||0;let booked=0,checked=0,treated=0,pending=0;const keys=new Set();for(const [key,ap] of Object.entries(a)){if(!ap||typeof ap!=='object'){issues.push(key+': 예약 구조 오류');continue}if(keys.has(key))issues.push(key+': 중복 예약');keys.add(key);if(!Number.isInteger(ap.phase)||ap.phase<0||ap.phase>3)issues.push(key+': 예약 시간 오류');if(!['booked','checked-in','completed'].includes(ap.status))issues.push(key+': 알 수 없는 예약 상태');if(t[key]){treated++;if(ap.status==='booked')issues.push(key+': 진료 완료 후 예약 상태 미반영')}else if(ap.status==='checked-in'||ap.status==='completed'){checked++;if(ap.status==='completed')issues.push(key+': 진료 기록 없는 완료 상태')}else{booked++;if(ap.phase<=phase&&key.endsWith('_'+day))pending++}if(queue[key]&&queue[key].checkedIn&&!t[key]&&ap.status==='booked')issues.push(key+': 대기열 접수와 예약 상태 불일치')}
for(const key of Object.keys(t))if(!a[key])issues.push(key+': 예약 없는 진료 기록');for(const [key,f] of Object.entries(follow))if(f&&typeof f==='object'&&f.due!==undefined&&(!Number.isFinite(Number(f.due))||Number(f.due)<1))issues.push(key+': 재방문 예정일 오류');return{booked,checked,treated,pending,issues}}
function v24Snapshot(){v14ensure();v15ensure();return{day:s.day,phase:s.phase,appointments:s.v14.appointments,treatments:s.v14.treatments,queue:s.v15.queue,followups:s.v15.followups}}
function v24Page(title,description){return v21Page(title,description)}
function v24Card(title,desc){const c=v21Card(title,desc);c.classList.add('v24-card');return c}
function v24Diagnostics(){const v=v24Ensure(),el=v24Page('🩺 v2.4 진료 실전 진단','실제 예약·접수·진료·재방문 저장 상태를 읽어 검증합니다. 검사는 진료 기록을 변경하지 않습니다.'),r=v24AuditSnapshot(v24Snapshot());const summary=document.createElement('div');summary.className='v24-summary';for(const [name,n] of [['예약 대기',r.booked],['접수 대기열',r.checked],['진료 완료',r.treated],['시간 경과 미접수',r.pending]]){const c=document.createElement('section');c.append(v14Text('strong',String(n)),v14Text('span',name));summary.appendChild(c)}el.appendChild(summary);const c=v24Card('저장 상태 검사',r.issues.length?`주의 ${r.issues.length}건 발견`:'검사한 상태에서 불일치가 발견되지 않았습니다.');for(const issue of r.issues.slice(0,30))c.appendChild(v14Text('p','⚠ '+issue,'v24-status'));v21Actions(c,[['검사 결과 기록',()=>{v.reports.unshift({day:s.day,phase:s.phase,summary:{booked:r.booked,checked:r.checked,treated:r.treated,pending:r.pending},issues:r.issues.slice(0,40)});v.reports=v.reports.slice(0,20);save(false);v24Diagnostics()}],['진료 대기열 열기',()=>move('v15queue')],['복원 검사',()=>move('v23recovery')]]);el.appendChild(c);const logs=v24Card('최근 검사 기록');for(const x of v.reports.slice(0,8))logs.appendChild(v14Text('p',`${x.day}일 차 · ${phases[x.phase]||x.phase} · 경고 ${x.issues.length}건`));el.appendChild(logs)}
function v24RunTests(){const cases=[];const add=(name,ok)=>cases.push({name,pass:!!ok});const ap={p_3:{phase:1,status:'booked'}},tx={},q={};let r=v24AuditSnapshot({day:3,phase:0,appointments:ap,treatments:tx,queue:q,followups:{}});add('예약 생성과 시간 대기',r.booked===1&&r.pending===0);ap.p_3.status='checked-in';q.p_3={checkedIn:true};r=v24AuditSnapshot({day:3,phase:1,appointments:ap,treatments:tx,queue:q});add('접수·대기열 동기화',r.checked===1&&r.issues.length===0);tx.p_3={result:'회복'};ap.p_3.status='completed';r=v24AuditSnapshot({day:3,phase:1,appointments:ap,treatments:tx,queue:q});add('진료 완료 우선 처리',r.treated===1&&r.issues.length===0);const f={p:{due:5,stage:1}};add('재방문 예약 검증',v24AuditSnapshot({followups:f}).issues.length===0);ap.p_3.status='booked';add('완료·예약 불일치 탐지',v24AuditSnapshot({appointments:ap,treatments:tx}).issues.length>0);const idempotent={};const once=k=>idempotent[k]?false:(idempotent[k]=true);add('이벤트 중복 지급 방지',once('x')&&!once('x'));const save={version:2,day:3,phase:1,records:[]};add('저장 형식 유지',save.version===2&&Array.isArray(save.records));add('재방문 이상 탐지',v24AuditSnapshot({followups:{p:{due:-1}}}).issues.length===1);return cases}
function v24TestPage(){const v=v24Ensure(),el=v24Page('🧪 v2.4 회귀 테스트','8개 상태 전이 테스트는 메모리에서만 실행합니다. 실제 플레이 기록은 별도의 진단 메뉴에서 검사합니다.'),c=v24Card('회귀 시나리오','예약→접수→진료→재방문, 중복 처리 및 데이터 오류 탐지를 확인합니다.');v21Actions(c,[['8개 시나리오 실행',()=>{const cases=v24RunTests();v.reports.unshift({day:s.day,phase:s.phase,tests:cases,issues:cases.filter(x=>!x.pass).map(x=>x.name)});v.reports=v.reports.slice(0,20);save(false);v24TestPage()}],['실제 기록 검사',()=>move('v24diagnostics')]]);el.appendChild(c);const x=v.reports.find(x=>x.tests);if(x){const c2=v24Card('최근 결과',`${x.tests.filter(z=>z.pass).length}/${x.tests.length} 통과`);for(const z of x.tests)c2.appendChild(v14Text('p',(z.pass?'✓ ':'⚠ ')+z.name));el.appendChild(c2)}}
const v24Stories=[{id:'umbrella',day:7,title:'양산 아래 줄 서기',text:'우산 수집가가 양산을 빌려주자 모자를 쓰고도 그늘을 찾는 손님들이 줄을 섰다. 미겔은 “진료 순서는 그대로다.” 하고 접수표를 정리했다.'},{id:'tea',day:11,title:'주전자 장인의 처방전',text:'주전자 장인은 진료소에 찻물을 가져왔다. 미겔은 온도부터 확인했다. “뜨거운 건 천천히 마셔.”'},{id:'radio',day:15,title:'라디오에 실린 분실물',text:'라디오 수리공이 모자 장수의 잃어버린 모자를 방송하자, 마을 사람들이 서로 다른 모자를 들고 찾아왔다.'},{id:'cactus',day:19,title:'선인장 보호 위원회',text:'선인장을 무서워하던 환자가 이제는 선인장에 이름표를 붙였다. 진료소 앞에는 작은 화분이 하나 늘었다.'}];
function v24StoriesPage(){const v=v24Ensure(),el=v24Page('🏘️ v2.4 주민 후일담','[게임 확장] 기존 주민과 코미디 환자의 새로운 소동. 각 이야기 보상은 한 번만 지급됩니다.');for(const x of v24Stories){const done=v.stories[x.id],ready=s.day>=x.day,c=v24Card(x.title,done?x.text:ready?'오늘 들을 수 있는 이야기입니다.':x.day+'일 차에 열립니다.');v21Actions(c,[['이야기 보기',()=>{if(v.stories[x.id]||s.day<x.day)return;v.stories[x.id]={day:s.day};modify({peace:1});save(false);v24StoriesPage()},!!done||!ready]]);el.appendChild(c)}}
const v24Daniel=[{id:'envelope',day:6,title:'봉투의 모서리',text:'미겔은 모서리가 구겨진 편지를 반듯하게 폈다. “D, 편지 잘 받았어.” 군에 있는 다니엘에게 짧은 답장을 남겼다.'},{id:'chess',day:10,title:'다음 수를 기다리는 시간',text:'휴가 중 다니엘이 체스판 앞에 앉았다. 미겔은 한 수를 깊게 생각한 뒤 말을 옮겼다. “D. 이번 판도 제대로 둘 거야.”'},{id:'call',day:14,title:'통화가 끊기기 전에',text:'진료소 문을 닫고 미겔은 전화를 받았다. “D, 오늘은 조용했어.” 그 말이 끝나기도 전에 바깥에서 주전자가 요란하게 울렸다.'},{id:'leave',day:18,title:'짧은 휴가의 산책',text:'휴가 중 찾아온 다니엘과 미겔은 정착촌의 모래길을 걸었다. 둘은 서로 다른 하루를 살다가 잠시 같은 길 위에 있었다.'}];
function v24DanielPage(){const v=v24Ensure(),el=v24Page('💜 v2.4 다니엘과 미겔','[원작 확정] 연인·호칭·군 복무·체스 태도 유지. [게임 확장] 아래 사건과 대사는 신규 창작입니다.');for(const x of v24Daniel){const done=v.daniel[x.id],ready=s.day>=x.day,c=v24Card(x.title,done?x.text:ready?'새 일상이 열렸습니다.':x.day+'일 차에 열립니다.');v21Actions(c,[['읽기',()=>{if(v.daniel[x.id]||s.day<x.day)return;v.daniel[x.id]={day:s.day};modify({peace:1});save(false);v24DanielPage()},!!done||!ready]]);el.appendChild(c)}}
function v24Economy(){const v=v24Ensure(),el=v24Page('⚖️ v2.4 장기 운영','[게임 확장] 무료 진료를 유지하면서 재고 부족과 과잉 보충을 방지합니다. 오늘의 선택은 한 번만 기록됩니다.');const prev=v.economy[s.day],c=v24Card('오늘의 운영',prev?'선택 완료: '+prev.label:`현재 물자 ${s.supplies||0} · 피로 ${s.tired||0}`);for(const [label,delta] of [['지원 물자 분류',{supplies:2,tired:1}],['물자 나눔',{supplies:-1,trust:1}],['장부 정리와 휴식',{tired:-2}]])v21Actions(c,[[label,()=>{if(v.economy[s.day])return;const d={...delta};if(d.supplies<0&&(s.supplies||0)<1){alert('나눌 물자가 부족합니다.');return}if(d.supplies>0)d.supplies=Math.min(d.supplies,Math.max(0,30-(s.supplies||0)));v.economy[s.day]={label,before:s.supplies||0,delta:d};modify(d);save(false);v24Economy()},!!prev]]);el.appendChild(c);const log=v24Card('운영 장부');for(const [day,x] of Object.entries(v.economy).slice(-15).reverse())log.appendChild(v14Text('p',`${day}일 차 · ${x.label} · 이전 물자 ${x.before}`));el.appendChild(log)}
const v24PreviousRender=render;render=function(){v24Ensure();v24PreviousRender();const pages={v24diagnostics:v24Diagnostics,v24tests:v24TestPage,v24stories:v24StoriesPage,v24daniel:v24DanielPage,v24economy:v24Economy};if(pages[s.tab])pages[s.tab]()};
