/* v2.5: compatible, opt-in repair, isolated regression and restore comparison */
function v25Ensure(){if(!s.v25||typeof s.v25!=='object'||Array.isArray(s.v25))s.v25={};const v=s.v25;for(const k of ['stories','daniel','economy'])if(!v[k]||typeof v[k]!=='object'||Array.isArray(v[k]))v[k]={};for(const k of ['audits','tests','repairs'])if(!Array.isArray(v[k]))v[k]=[];return v}
function v25Inspect(st){const issues=[],proposals=[],a=st?.v14?.appointments||{},t=st?.v14?.treatments||{},q=st?.v15?.queue||{},f=st?.v15?.followups||{};for(const [key,ap] of Object.entries(a)){if(!ap||typeof ap!=='object'||Array.isArray(ap)){issues.push(key+': 예약 데이터 손상 (자동 수정 불가)');continue}if(!Number.isInteger(ap.phase)||ap.phase<0||ap.phase>3)issues.push(key+': 예약 시간 오류 (수동 확인 필요)');if(t[key]&&ap.status!=='completed'){issues.push(key+': 진료 완료 후 예약 상태 불일치');proposals.push({key,field:'status',from:ap.status,to:'completed',reason:'기존 진료 기록 존재'})}else if(!t[key]&&ap.status==='completed')issues.push(key+': 완료 상태이나 진료 기록 없음 (수동 확인 필요)');else if(!t[key]&&q[key]?.checkedIn&&ap.status==='booked'){issues.push(key+': 접수 기록과 예약 상태 불일치');proposals.push({key,field:'status',from:'booked',to:'checked-in',reason:'기존 접수 기록 존재'})}}for(const key of Object.keys(t))if(!a[key])issues.push(key+': 예약 없이 진료 기록 존재 (자동 생성 안 함)');for(const [key,r] of Object.entries(f))if(r&&(!Number.isFinite(Number(r.due))||Number(r.due)<1))issues.push(key+': 재방문 예정일 오류');return{issues,proposals,counts:{reservations:Object.keys(a).length,treated:Object.keys(t).length,followups:Object.keys(f).length}}}
function v25ApplyProposal(st,p){const ap=st?.v14?.appointments?.[p.key];if(!ap||ap[p.field]!==p.from)return false;if(p.to==='completed'&&!st.v14.treatments?.[p.key])return false;if(p.to==='checked-in'&&(!st.v15?.queue?.[p.key]?.checkedIn||st.v14.treatments?.[p.key]))return false;ap[p.field]=p.to;return true}
function v25Compare(a,b){const va=v21Validate(a),vb=v21Validate(b);if(va.length||vb.length)return{valid:false,issues:[...va.map(x=>'현재: '+x),...vb.map(x=>'파일: '+x)]};const metrics=x=>({day:x.day,phase:x.phase,records:x.records.length,reservations:Object.keys(x.v14?.appointments||{}).length,treatments:Object.keys(x.v14?.treatments||{}).length,followups:Object.keys(x.v15?.followups||{}).length});return{valid:true,current:metrics(a),candidate:metrics(b),warnings:[...(b.day<a.day?['복원 파일의 날짜가 현재보다 이전입니다.']:[]),...(b.records.length<a.records.length?['복원 파일의 기본 진료 기록이 더 적습니다.']:[]),...(Object.keys(b.v14?.treatments||{}).length<Object.keys(a.v14?.treatments||{}).length?['복원 파일의 예약 진료 완료 기록이 더 적습니다.']:[])]}}
function v25Regression(){const tests=[],test=(name,fn)=>{try{tests.push({name,pass:!!fn()})}catch(e){tests.push({name,pass:false,detail:String(e.message||e)})}};const base=()=>({version:2,day:4,phase:1,flags:{},records:[],v14:{appointments:{'p_4':{phase:1,status:'booked'}},treatments:{}},v15:{queue:{},followups:{}}});test('기존 version:2 검증',()=>v21Validate(base()).length===0);test('예약 후 접수 불일치 탐지',()=>{const x=base();x.v15.queue.p_4={checkedIn:true};return v25Inspect(x).proposals.length===1});test('접수 승인 후 상태 변경',()=>{const x=base();x.v15.queue.p_4={checkedIn:true};return v25ApplyProposal(x,v25Inspect(x).proposals[0])&&x.v14.appointments.p_4.status==='checked-in'});test('동일 복구 중복 차단',()=>{const x=base();x.v15.queue.p_4={checkedIn:true};const p=v25Inspect(x).proposals[0];return v25ApplyProposal(x,p)&&!v25ApplyProposal(x,p)});test('진료 완료 상태 복구',()=>{const x=base();x.v14.treatments.p_4={result:'완료'};return v25ApplyProposal(x,v25Inspect(x).proposals[0])&&x.v14.appointments.p_4.status==='completed'});test('근거 없는 완료 상태 수정 차단',()=>{const x=base();return !v25ApplyProposal(x,{key:'p_4',field:'status',from:'booked',to:'completed'})});test('재방문 날짜 오류 탐지',()=>{const x=base();x.v15.followups.p={due:-2};return v25Inspect(x).issues.some(i=>i.includes('재방문'))});test('동일 백업 비교',()=>v25Compare(base(),base()).valid);test('과거 백업 경고',()=>{const a=base(),b=base();b.day=2;return v25Compare(a,b).warnings.length===1});test('잘못된 버전 복원 거부',()=>{const a=base(),b=base();b.version=3;return !v25Compare(a,b).valid});test('검사 중 원본 데이터 불변',()=>{const x=base(),before=JSON.stringify(x);v25Inspect(x);return JSON.stringify(x)===before});return tests}
function v25Page(title,desc){return v21Page(title,desc)}
function v25Card(title,desc){const c=v21Card(title,desc);c.classList.add('v25-panel');return c}
function v25Diagnostic(){v14ensure();v15ensure();const v=v25Ensure(),el=v25Page('🩺 v2.5 진료 상태와 복구 제안','실제 저장된 예약·접수·진료·재방문 기록을 확인합니다. 수정은 명시적 승인 후에만 적용합니다.'),r=v25Inspect(s),summary=v25Card('실제 저장 상태',`예약 ${r.counts.reservations} · 진료 ${r.counts.treated} · 재방문 ${r.counts.followups} · 경고 ${r.issues.length}`);for(const issue of r.issues.slice(0,25))summary.appendChild(v14Text('p','⚠ '+issue,'v25-note'));v21Actions(summary,[['진단 기록 저장',()=>{v.audits.unshift({day:s.day,phase:s.phase,issues:r.issues.slice(0,40)});v.audits=v.audits.slice(0,20);save(false);v25Diagnostic()}],['진료 화면',()=>move('v20flow')]]);el.appendChild(summary);const box=v25Card('안전한 복구 제안',r.proposals.length?`${r.proposals.length}개 제안 · 기존 진료 기록을 삭제하지 않습니다.`:'자동 수정 가능한 불일치가 없습니다.');for(const proposal of r.proposals.slice(0,15)){const c=v25Card(proposal.key,`${proposal.from} → ${proposal.to} · ${proposal.reason}`);v21Actions(c,[['이 항목만 승인하여 수정',()=>{if(!confirm('예약 '+proposal.key+'의 상태만 변경할까요?'))return;const before=JSON.stringify(s.v14.appointments[proposal.key]);if(!v25ApplyProposal(s,proposal)){alert('상태가 변경되어 수정하지 않았습니다.');return}v.repairs.unshift({day:s.day,key:proposal.key,before,after:proposal.to});v.repairs=v.repairs.slice(0,30);save(false);v25Diagnostic()}]]);box.appendChild(c)}el.appendChild(box)}
function v25Tests(){const v=v25Ensure(),el=v25Page('🧪 v2.5 회귀 검사','11개 메모리 상태 전이 테스트입니다. 실제 세이브는 수정하지 않습니다.'),c=v25Card('격리 회귀 검사','예약·접수·진료·재방문, 중복 방지, 백업 비교 및 원본 불변성을 검사합니다.');v21Actions(c,[['11개 시나리오 실행',()=>{const results=v25Regression();v.tests.unshift({day:s.day,results});v.tests=v.tests.slice(0,15);save(false);v25Tests()}]]);el.appendChild(c);if(v.tests[0]){const t=v.tests[0],r=v25Card('최근 결과',`${t.results.filter(x=>x.pass).length}/${t.results.length} 통과`);for(const x of t.results)r.appendChild(v14Text('p',(x.pass?'✓ ':'⚠ ')+x.name+(x.detail?' · '+x.detail:'')));el.appendChild(r)}}
function v25Recovery(){const el=v25Page('🛡️ v2.5 백업 전후 비교','파일을 적용하지 않고 현재 세이브와 복원 파일의 날짜·기록·진료 상태를 비교합니다. 실제 복원은 안전 슬롯 화면에서 진행합니다.'),c=v25Card('JSON 파일 사전 비교','2MB 이하의 JSON 파일만 검사합니다.');const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.className='v25-input';input.setAttribute('aria-label','비교할 백업 파일');c.appendChild(input);const result=v14Text('p','파일을 선택하고 비교를 실행하세요.','v25-note');c.appendChild(result);v21Actions(c,[['현재 저장과 비교',async()=>{try{const f=input.files?.[0];if(!f)throw Error('파일을 선택하세요');if(f.size>2000000)throw Error('2MB 초과');const raw=await f.text(),candidate=JSON.parse(raw),report=v25Compare(s,candidate);if(!report.valid)throw Error(report.issues.join(' / '));result.textContent=['비교 완료 (아직 복원하지 않음)',...Object.keys(report.current).map(k=>`${k}: 현재 ${report.current[k]} / 파일 ${report.candidate[k]}`),...(report.warnings.length?report.warnings:['주요 기록 수 감소 경고 없음'])].join('\n')}catch(e){result.textContent='비교 실패: '+e.message}}],['안전 슬롯 복원 화면',()=>move('v21recovery')],['기존 JSON 백업',()=>move('v20backup')]]);el.appendChild(c)}
const v25Stories=[{id:'chair',day:9,title:'의자 하나를 둘러싼 회의',text:'진료소 앞 의자가 한 칸 옮겨지자 주민들이 그늘의 길이를 재기 시작했다. 미겔은 조용히 접수표를 다시 놓았다.'},{id:'umbrella',day:13,title:'비가 오지 않는 날의 우산',text:'우산 수집가는 맑은 하늘 아래서 우산을 펼쳤다. “햇빛도 하늘에서 내려오잖아요.” 미겔은 물을 한 잔 건넸다.'},{id:'tea',day:17,title:'찻잔의 주인을 찾아서',text:'주전자 장인은 누가 두고 간 찻잔인지 찾아다녔다. 결국 진료소 손님들이 돌아가며 쓰던 공용 찻잔이었다.'},{id:'radio',day:21,title:'라디오의 조용한 시간',text:'라디오 수리공은 고장 난 잡음을 고치고 한동안 아무 말도 하지 않았다. 그날 방송에는 바람 소리만 잠깐 흘렀다.'}];
