function v27ClinicAudit(st){const base=v26Audit(st),a=st.v14?.appointments||{},t=st.v14?.treatments||{},f=st.v15?.followups||{},issues=[...base.issues];for(const [id,ap] of Object.entries(a)){if(!ap||typeof ap!=='object')continue;if(t[id]&&['reserved','arrived','waiting'].includes(ap.status))issues.push(id+': 진료 기록이 있으나 예약이 미완료 상태');if(ap.status==='done'&&!t[id])issues.push(id+': 완료된 예약에 진료 기록이 없습니다')}for(const [id,x] of Object.entries(f)){if(x&&typeof x==='object'&&Number.isFinite(x.due)&&x.due<0)issues.push(id+': 재방문 예정일이 잘못되었습니다')}return{snapshot:v27ClinicSnapshot(st),issues:[...new Set(issues)]}}
