function v27EconomyPlan(st,ledger,choice){if(ledger[String(st.day)])return{ok:false,reason:'오늘은 이미 운영을 마쳤습니다.'};const n=Number(st.supplies)||0, fatigue=Number(st.tired)||0;const plans={aid:{label:'구호 물품 정리',delta:{supplies:Math.max(0,Math.min(2,30-n)),tired:1}},share:{label:'주민 물자 지원',delta:{supplies:-2,trust:2,peace:1}},rest:{label:'장부 정리와 휴식',delta:{tired:-Math.min(3,Math.max(0,fatigue)),peace:1}}};const p=plans[choice];if(!p)return{ok:false,reason:'선택이 올바르지 않습니다.'};if(choice==='share'&&n<2)return{ok:false,reason:'물자가 2개 이상 필요합니다.'};return{ok:true,...p,before:{supplies:n,tired:fatigue,trust:st.trust,peace:st.peace}}}
function v27Regression(){const cases=[];const check=(name,fn)=>{try{if(!fn())throw Error('조건 불일치');cases.push({name,pass:true})}catch(e){cases.push({name,pass:false,reason:String(e.message||e)})}};const mk=()=>({day:2,phase:1,supplies:5,tired:4,trust:2,peace:2,v14:{appointments:{},treatments:{}},v15:{queue:{},followups:{}}});check('빈 예약 진단',()=>v27ClinicAudit(mk()).snapshot.appointments===0);check('예약 건수 반영',()=>{const x=mk();x.v14.appointments.a={phase:1,status:'reserved'};return v27ClinicSnapshot(x).appointments===1});check('진료 기록 건수 반영',()=>{const x=mk();x.v14.treatments.a={choice:'care'};return v27ClinicSnapshot(x).treatments===1});check('대기열 건수 반영',()=>{const x=mk();x.v15.queue.a={};return v27ClinicSnapshot(x).queued===1});check('재방문 건수 반영',()=>{const x=mk();x.v15.followups.a={due:3};return v27ClinicSnapshot(x).followups===1});check('진료 후 미완료 예약 경고',()=>{const x=mk();x.v14.appointments.a={phase:1,status:'reserved'};x.v14.treatments.a={};return v27ClinicAudit(x).issues.some(z=>z.includes('미완료'))});check('중복 경고 제거',()=>{const x=mk();return new Set(v27ClinicAudit(x).issues).size===v27ClinicAudit(x).issues.length});check('물자 부족 방지',()=>{const x=mk();x.supplies=1;return !v27EconomyPlan(x,{},'share').ok});check('물자 상한 30',()=>{const x=mk();x.supplies=29;return v27EconomyPlan(x,{},'aid').delta.supplies===1});check('일일 운영 중복 방지',()=>!v27EconomyPlan(mk(),{'2':{choice:'aid'}},'rest').ok);check('휴식 피로 하한',()=>{const x=mk();x.tired=1;return v27EconomyPlan(x,{},'rest').delta.tired===-1});check('기록 스냅샷 비파괴',()=>{const x=mk(),a=JSON.stringify(x);v27ClinicAudit(x);return JSON.stringify(x)===a});check('재방문 이상 예정일',()=>{const x=mk();x.v15.followups.a={due:-2};return v27ClinicAudit(x).issues.some(z=>z.includes('재방문 예정일'))});check('완료 예약의 진료 기록 누락',()=>{const x=mk();x.v14.appointments.a={phase:1,status:'done'};return v27ClinicAudit(x).issues.some(z=>z.includes('진료 기록이 없습니다'))});check('기존 상태 검사 함수 사용',()=>typeof v26Audit==='function');check('복원 비교 함수 사용',()=>typeof v26RestoreCheck==='function');check('기존 저장 키 유지',()=>KEY==='miguel_clinic_v02');check('신규 상태 격리',()=>!('v27' in mk()));return cases}
