function v27AuditUI(){const v=v27Ensure(),el=v27Page('🩺 v2.7 통합 진료 점검','실제 저장 데이터를 읽어 예약·접수·진료·재방문을 점검합니다. 진단은 데이터를 수정하지 않습니다.'),r=v27ClinicAudit(s),c=v27Card('현재 진료 기록',`예약 ${r.snapshot.appointments} · 진료 ${r.snapshot.treatments} · 대기 ${r.snapshot.queued} · 재방문 ${r.snapshot.followups} · 경고 ${r.issues.length}`);for(const msg of r.issues.slice(0,18))c.appendChild(v14Text('p','⚠ '+msg));v21Actions(c,[['18개 회귀 검사 실행',()=>{const tests=v27Regression();v.auditLog.unshift({day:s.day,phase:s.phase,tests,issues:r.issues.slice(0,20)});v.auditLog=v.auditLog.slice(0,10);save(false);v27AuditUI()}],['승인형 복구 화면',()=>move('v25diagnostics')]]);el.appendChild(c);if(v.auditLog[0]){const x=v.auditLog[0],c2=v27Card('최근 회귀 검사',`${x.tests.filter(t=>t.pass).length}/${x.tests.length} 통과`);for(const t of x.tests)c2.appendChild(v14Text('p',(t.pass?'✓ ':'✗ ')+t.name+(t.reason?' — '+t.reason:'')));el.appendChild(c2)}}
function v27RestoreUI(){const el=v27Page('🛡️ v2.7 백업 비교','복원하지 않고 파일을 먼저 검사합니다. 실제 복원은 기존 백업·복원 메뉴에서 진행하세요.'),c=v27Card('백업 JSON 비교','파일을 선택하고 현재 저장 데이터와 비교해 주세요.'),input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.setAttribute('aria-label','비교할 백업 JSON 파일');c.appendChild(input);const out=v14Text('p','파일 선택 대기');out.style.whiteSpace='pre-wrap';c.appendChild(out);v21Actions(c,[['백업 비교 실행',async()=>{try{const file=input.files?.[0];if(!file)throw Error('파일을 선택해 주세요.');if(file.size>2000000)throw Error('2MB를 초과하는 파일입니다.');const candidate=JSON.parse(await file.text()),r=v27SafeRestorePreview(candidate);if(!r.valid)throw Error((r.issues||['저장 형식 오류']).join(' / '));out.textContent=['검사 완료 (복원하지 않음)',...Object.keys(r.currentSnapshot||{}).map(k=>`${k}: 현재 ${r.currentSnapshot[k]} / 백업 ${r.incomingSnapshot[k]}`),...r.warnings,...(r.incomingIssues||[]).slice(0,10),r.safe?'주요 구조 경고 없음':'경고가 있습니다. 복원 전에 확인해 주세요.'].join('\n')}catch(e){out.textContent='비교 실패: '+e.message}}],['기존 안전 복원',()=>move('v21recovery')],['JSON 백업',()=>move('v20backup')]]);el.appendChild(c)}
const v27Residents=[{id:'chair-queue',day:11,title:'진료소 앞 의자 번호표',text:'의자에 번호표가 붙었다. 하지만 주민들은 그늘이 가장 진한 의자부터 골랐다. 미겔은 번호표 대신 진료 순서를 다시 적었다.'},{id:'cactus-consult',day:15,title:'선인장의 정기 검진',text:'선인장 주인은 화분을 들고 찾아왔다. 미겔은 잠시 침묵하다가 말했다. “오늘은 주인부터 진찰하죠.”'},{id:'teapot-radio',day:19,title:'찻주전자 라디오 방송',text:'라디오에서 찻물 끓는 소리가 흘렀다. 주민들은 방송 사고라고 생각했지만 주전자 장인은 만족스러운 표정이었다.'},{id:'umbrella-return',day:23,title:'양산의 귀가 시간',text:'빌려 간 양산들이 하나둘 돌아왔다. 마지막 양산에는 작은 메모가 매달렸다. “그늘 덕분에 잘 쉬었습니다.”'}];
