function v28Ensure(){if(!s.v28||typeof s.v28!=='object'||Array.isArray(s.v28))s.v28={};const v=s.v28;for(const k of ['stories','daniel','economy','notified'])if(!v[k]||typeof v[k]!=='object'||Array.isArray(v[k]))v[k]={};if(!Array.isArray(v.testHistory))v.testHistory=[];return v}
function v28ClinicState(st){const a=st.v14?.appointments||{},t=st.v14?.treatments||{},q=st.v15?.queue||{},f=st.v15?.followups||{};const issues=[];let pending=0,complete=0;for(const [key,ap] of Object.entries(a)){if(!ap||typeof ap!=='object'){issues.push(key+': 예약 형식 오류');continue}const treated=!!t[key];if(treated)complete++;else pending++;if(treated&&['reserved','arrived','waiting'].includes(ap.status))issues.push(key+': 진료 완료 후 예약 상태 미갱신');if(!treated&&['done','completed'].includes(ap.status))issues.push(key+': 진료 기록 없이 완료 처리됨');if(!Number.isInteger(ap.phase)||ap.phase<0||ap.phase>3)issues.push(key+': 시간대 오류')}for(const [key,x] of Object.entries(f)){if(x&&typeof x==='object'&&Number.isFinite(x.due)&&x.due<0)issues.push(key+': 재방문 날짜 오류')}return{appointments:Object.keys(a).length,treatments:Object.keys(t).length,queue:Object.keys(q).length,followups:Object.keys(f).length,pending,complete,issues:[...new Set(issues)]}}
function v28SafePlan(st,ledger,id){if(ledger[String(st.day)])return{ok:false,reason:'오늘의 운영은 이미 완료했습니다.'};const n=Math.max(0,Number(st.supplies)||0),fatigue=Math.max(0,Number(st.tired)||0);const plans={aid:{label:'구호 상자 정리',delta:{supplies:Math.min(2,Math.max(0,30-n)),tired:1}},share:{label:'이웃에게 물자 나눔',delta:{supplies:-2,trust:2,peace:1}},rest:{label:'장부 점검과 휴식',delta:{tired:-Math.min(3,fatigue),peace:1}}};const p=plans[id];if(!p)return{ok:false,reason:'선택 오류'};if(id==='share'&&n<2)return{ok:false,reason:'물자 2개가 필요합니다.'};if(id==='aid'&&n>=30)return{ok:false,reason:'물자 창고가 가득 찼습니다.'};return{ok:true,...p}}
