function v29Ensure(){if(!s.v29||typeof s.v29!=='object'||Array.isArray(s.v29))s.v29={};for(const k of ['stories','daniel','economy','notices'])if(!s.v29[k]||typeof s.v29[k]!=='object'||Array.isArray(s.v29[k]))s.v29[k]={};return s.v29}
function v29Key(p,day){return p.id+'_'+day}
function v29Eligible(st,key){const ap=st.v14?.appointments?.[key];return !!ap&&!st.v14?.treatments?.[key]&&Number.isInteger(ap.phase)&&ap.phase>=0&&ap.phase<=3&&st.phase>=ap.phase&&st.day===ap.day}
/* Reserved patients follow their booked clinic appointment even if their ordinary wandering route differs. */
const v29OldArrived=v16arrived;
v16arrived=function(p,ap){if(!ap)return false;const key=v29Key(p,s.day);if(s.v14?.appointments?.[key]===ap&&v29Eligible(s,key))return true;return v29OldArrived(p,ap)};
function v29Reconcile(){v29Ensure();v14ensure();v15ensure();v16ensure();let changed=false;for(const p of v14Patients){const key=v29Key(p,s.day),ap=s.v14.appointments[key],tr=s.v14.treatments[key];if(!ap)continue;if(tr){if(ap.status!=='completed'){ap.status='completed';changed=true}continue}if(v29Eligible(s,key)&&ap.status!=='checked-in'){
 ap.status='checked-in';changed=true;
}if(ap.status==='checked-in'&&!s.v15.queue[key]?.checkedIn){s.v15.queue[key]={day:s.day,patient:p.id,checkedIn:true,where:'진료소',automatic:true};changed=true}
 if(ap.status==='checked-in'&&!s.v29.notices[key]){s.v29.notices[key]={day:s.day,phase:s.phase};changed=true}
}if(changed)save(false);return changed}
/* Treating a booked patient is possible after auto check-in, and duplicate treatment remains blocked. */
const v29OldTreat=v14Treat;
v14Treat=function(p,key,choice){v29Reconcile();if(s.v14?.treatments?.[key])return;v29OldTreat(p,key,choice);if(s.v14?.treatments?.[key]){const ap=s.v14.appointments[key];if(ap)ap.status='completed';save(false)}};
const v29OldNext=next;next=function(){v29OldNext();v29Reconcile()};
