function v29Audit(){const el=v21Page('🧪 v2.9 검사','현재 상태 진단과 비파괴 가상 회귀 테스트입니다.'),r=v28ClinicState(s),c=v21Card('진료 기록',`예약 ${r.appointments} · 진료 ${r.treatments} · 재방문 ${r.followups} · 경고 ${r.issues.length}`);for(const issue of r.issues.slice(0,10))c.appendChild(v14Text('p',issue));const result=v29Tests();c.appendChild(v14Text('p',`격리 회귀 ${result.filter(x=>x.pass).length}/${result.length} 통과`));for(const x of result.filter(x=>!x.pass))c.appendChild(v14Text('p','실패: '+x.name));el.appendChild(c)}
