/* v3.0: additive integration and persistent save verification; game-expansion stories */
function v30Ensure(){if(!s.v30||typeof s.v30!=='object'||Array.isArray(s.v30))s.v30={};for(const k of ['town','daniel','ledger','seen'])if(!s.v30[k]||typeof s.v30[k]!=='object'||Array.isArray(s.v30[k]))s.v30[k]={};return s.v30}
function v30Snapshot(st){const a=st.v14?.appointments||{},t=st.v14?.treatments||{},f=st.v15?.followups||{};return{day:st.day,phase:st.phase,appointments:Object.keys(a).length,treatments:Object.keys(t).length,followups:Object.keys(f).length,supplies:st.supplies,records:Array.isArray(st.records)?st.records.length:0}}
function v30Audit(st){const a=st.v14?.appointments||{},t=st.v14?.treatments||{},f=st.v15?.followups||{},issues=[];for(const [key,ap] of Object.entries(a)){if(!ap||typeof ap!=='object'){issues.push(key+': 예약 데이터 형식 오류');continue}if(!Number.isInteger(ap.phase)||ap.phase<0||ap.phase>3)issues.push(key+': 시간대 오류');if(t[key]&&ap.status!=='completed')issues.push(key+': 진료 완료 상태 불일치');if(ap.status==='completed'&&!t[key])issues.push(key+': 진료 기록 누락')}for(const [id,item] of Object.entries(f)){if(!item||typeof item!=='object'||!Number.isFinite(item.due)||item.due<0)issues.push(id+': 재방문 예정일 오류')}return{snapshot:v30Snapshot(st),issues:[...new Set(issues)]}}
function v30RepairPreview(st){const a=st.v14?.appointments||{},t=st.v14?.treatments||{},out=[];for(const [key,ap] of Object.entries(a))if(ap&&typeof ap==='object'&&t[key]&&ap.status!=='completed')out.push({key,from:ap.status,to:'completed'});return out}
function v30ApplyRepair(key){const proposals=v30RepairPreview(s),item=proposals.find(x=>x.key===key);if(!item)return false;const raw=localStorage.getItem(KEY);try{localStorage.setItem('miguel_clinic_v02_v30_pre_repair',raw||JSON.stringify(s))}catch(e){alert('안전 사본을 만들 수 없어 수정을 중단합니다.');return false}const ap=s.v14.appointments[key];ap.status='completed';save(false);return true}
