function v30Flow(){v29Reconcile();const el=v30Page('🩺 v3.0 진료 통합','예약 → 자동 접수 → 진료 완료 → 재방문. 실제 저장된 진행 상태를 표시합니다.');const audit=v30Audit(s),box=v21Card('오늘의 진료 현황',`예약 ${audit.snapshot.appointments} · 진료 ${audit.snapshot.treatments} · 재방문 ${audit.snapshot.followups} · 경고 ${audit.issues.length}`);for(const x of audit.issues.slice(0,8))box.appendChild(v14Text('p','⚠ '+x));el.appendChild(box);const grid=document.createElement('div');grid.className='v30-grid';for(const p of v14Patients){const key=v29Key(p,s.day),ap=s.v14.appointments[key],tr=s.v14.treatments[key],f=s.v15?.followups?.[p.id],c=v21Card(p.name,tr?'진료 완료':ap?.status==='checked-in'?'접수 완료':ap?'예약 대기':'예약 없음');v21Actions(c,[['현재 시간 예약',()=>{if(s.v14.appointments[key]||!v11Day())return;const count=Object.values(s.v14.appointments).filter(x=>x?.day===s.day&&x.phase===s.phase).length;if(count>=3){alert('현재 시간대 예약이 가득 찼습니다.');return}s.v14.appointments[key]={day:s.day,phase:s.phase,status:'reserved'};v29Reconcile();save(false);v30Flow()},!!ap||!v11Day()],['진료 완료',()=>{v29Reconcile();if(s.v14.appointments[key]?.status!=='checked-in'||s.v14.treatments[key])return;v14Treat(p,key,'상태 확인');v30Flow()},!ap||ap.status!=='checked-in'||!!tr],['재방문 확인',()=>{const x=s.v15?.followups?.[p.id];if(!x||s.day<x.due||x.stage>=2)return;x.stage++;x.due=s.day+2;modify({trust:1,peace:1});save(false);v30Flow()},!f||s.day<f.due||f.stage>=2]]);if(f)c.appendChild(v14Text('p',`재방문 예정 ${f.due}일 차 · 진행 ${f.stage}/2`));grid.appendChild(c)}el.appendChild(grid);v21Actions(el,[['다음 시간대로',()=>next()],['저장 검사',()=>move('v30save')]])}
function v30SaveUI(){const el=v30Page('🛡️ v3.0 저장·복원 점검','현재 저장 데이터와 백업을 비교합니다. 복원은 기존 안전 복원 화면에서 승인 후 진행합니다.'),c=v21Card('브라우저 저장 상태'),probe=v30PersistProbe(),audit=v30Audit(s);c.appendChild(v14Text('p',`저장소 읽기/쓰기 ${probe.ok?'정상':'실패'} · 현재 저장 ${probe.stored?'존재':'없음'} · 경고 ${audit.issues.length}건`));v21Actions(c,[['현재 진행 저장',()=>{save(false);v30SaveUI()}],['안전 복원 화면',()=>move('v21recovery')],['JSON 백업',()=>move('v20backup')]]);el.appendChild(c);const comp=v21Card('구버전 JSON 백업 비교','읽기 전용 검사 · 2MB 이하'),input=document.createElement('input'),out=v14Text('p','백업 파일을 선택해 주세요.');input.type='file';input.accept='.json,application/json';input.setAttribute('aria-label','비교할 JSON 세이브 파일');out.className='v30-note';comp.append(input,out);v21Actions(comp,[['비교 실행',async()=>{try{const file=input.files?.[0];if(!file)throw Error('파일을 선택해 주세요.');if(file.size>2000000)throw Error('2MB 초과');const result=v30RestoreCompare(JSON.parse(await file.text()));if(!result.valid)throw Error(result.errors.join(', '));out.textContent=`현재 ${JSON.stringify(result.current)}\n백업 ${JSON.stringify(result.incoming)}\n백업이 더 오래됨: ${result.older?'예':'아니요'}\n진료 기록 경고: ${result.issues.length}건`;}catch(e){out.textContent='비교 실패: '+e.message}}]]);el.appendChild(comp);const repair=v21Card('승인형 진료 상태 수정','진료 기록이 있는데 예약이 완료로 표시되지 않은 경우에만 수정합니다. 적용 전 안전 사본을 생성합니다.');for(const x of v30RepairPreview(s))v21Actions(repair,[[x.key+' 완료 상태 수정',()=>{if(confirm('해당 예약 상태만 완료로 수정할까요?')){v30ApplyRepair(x.key);v30SaveUI()}}]]);if(!v30RepairPreview(s).length)repair.appendChild(v14Text('p','수정 제안 없음'));el.appendChild(repair)}
function v30EconomyPlan(st,ledger,id){if(ledger[String(st.day)])return{ok:false,reason:'오늘 이미 운영함'};const n=Math.max(0,Number(st.supplies)||0),t=Math.max(0,Number(st.tired)||0);const choices={sort:{name:'지원 물자 정리',delta:{supplies:Math.min(2,Math.max(0,30-n)),tired:1}},share:{name:'주민에게 물자 나눔',delta:{supplies:-2,trust:2,peace:1}},rest:{name:'휴식과 장부 정리',delta:{tired:-Math.min(3,t),peace:1}}};const x=choices[id];if(!x)return{ok:false,reason:'잘못된 선택'};if(id==='share'&&n<2)return{ok:false,reason:'물자 부족'};if(id==='sort'&&n>=30)return{ok:false,reason:'재고 상한'};return{ok:true,...x}}
function v30Economy(){const v=v30Ensure(),el=v30Page('⚖️ v3.0 장기 운영','[게임 확장] 하루 한 번만 운영 선택이 가능합니다.'),c=v21Card('현재 운영',`물자 ${s.supplies}/30 · 피로 ${s.tired}`);for(const id of ['sort','share','rest']){const x=v30EconomyPlan(s,v.ledger,id);v21Actions(c,[[x.name||id,()=>{const p=v30EconomyPlan(s,v.ledger,id);if(!p.ok)return;const before={supplies:s.supplies,tired:s.tired};modify(p.delta);v.ledger[String(s.day)]={choice:id,before,after:{supplies:s.supplies,tired:s.tired}};save(false);v30Economy()},!x.ok]])}for(const [day,x] of Object.entries(v.ledger).slice(-8).reverse())c.appendChild(v14Text('p',`${day}일 차: ${x.choice} · 물자 ${x.before.supplies} → ${x.after.supplies}`));el.appendChild(c)}
function v30Stories(dan){const v=v30Ensure(),list=dan?v30Daniel:v30Town,seen=dan?v.daniel:v.town,el=v30Page(dan?'💜 다니엘의 일상':'🏘️ 주민 코미디 후일담','[게임 확장] 공식 원작에 없는 게임 전용 창작입니다.');for(const item of list){const read=!!seen[item.id],c=v21Card(item.title,read?item.text:s.day>=item.day?'읽을 수 있습니다.':`${item.day}일 차 개방`);v21Actions(c,[['이야기 읽기',()=>{if(read||s.day<item.day)return;seen[item.id]={day:s.day};modify({peace:1});save(false);v30Stories(dan)},read||s.day<item.day]]);el.appendChild(c)}}
function v30Regression(){const out=[],check=(name,fn)=>{try{if(!fn())throw Error('조건 불일치');out.push({name,pass:true})}catch(e){out.push({name,pass:false,error:String(e.message||e)})}};const mk=()=>({version:2,day:4,phase:1,flags:{},records:[],eventsSeen:[],messages:[],supplies:5,tired:2,v14:{appointments:{cactus_4:{day:4,phase:1,status:'reserved'}},treatments:{}},v15:{queue:{},followups:{}}});check('기존 키',()=>KEY==='miguel_clinic_v02');check('버전 2 검증',()=>!v21Validate(mk()).length);check('시간 도달',()=>v29Eligible(mk(),'cactus_4'));check('시간 이전 차단',()=>{const x=mk();x.phase=0;return !v29Eligible(x,'cactus_4')});check('다른 날 차단',()=>{const x=mk();x.day=5;return !v29Eligible(x,'cactus_4')});check('중복 진료 차단',()=>{const x=mk();x.v14.treatments.cactus_4={};return !v29Eligible(x,'cactus_4')});check('상태 수정 제안',()=>{const x=mk();x.v14.treatments.cactus_4={};return v30RepairPreview(x).length===1});check('수정 제안 비파괴',()=>{const x=mk(),before=JSON.stringify(x);v30RepairPreview(x);return before===JSON.stringify(x)});check('완료 상태 경고',()=>{const x=mk();x.v14.appointments.cactus_4.status='completed';return v30Audit(x).issues.length>0});check('재방문 경고',()=>{const x=mk();x.v15.followups.cactus={due:-2};return v30Audit(x).issues.length>0});check('재방문 수량',()=>{const x=mk();x.v15.followups.cactus={due:6};return v30Snapshot(x).followups===1});check('물자 부족',()=>{const x=mk();x.supplies=1;return !v30EconomyPlan(x,{},'share').ok});check('재고 상한',()=>{const x=mk();x.supplies=30;return !v30EconomyPlan(x,{},'sort').ok});check('상한 직전',()=>{const x=mk();x.supplies=29;return v30EconomyPlan(x,{},'sort').delta.supplies===1});check('일일 중복',()=>!v30EconomyPlan(mk(),{'4':{}},'rest').ok);check('휴식 하한',()=>{const x=mk();x.tired=1;return v30EconomyPlan(x,{},'rest').delta.tired===-1});check('진료 상태 검사',()=>v30Audit(mk()).snapshot.appointments===1);check('기존 진료 함수',()=>typeof v14Treat==='function');check('복원 검증 함수',()=>typeof v21Validate==='function');check('v30 신규 상태 격리',()=>!('v30' in mk()));return out}
function v30TestsUI(){const el=v30Page('🧪 v3.0 회귀 진단','20개 메모리 격리 검사. 실제 브라우저 E2E 결과는 tests/ 보고서를 확인해 주세요.'),cases=v30Regression(),c=v21Card('검사 결과',`${cases.filter(x=>x.pass).length}/${cases.length} 통과`);for(const x of cases.filter(x=>!x.pass))c.appendChild(v14Text('p',`실패: ${x.name} ${x.error||''}`));el.appendChild(c)}
