/* v3.1: additive compatibility and diagnostic layer. [게임 확장] */
function v31Ensure(){if(!s.v31||typeof s.v31!=='object'||Array.isArray(s.v31))s.v31={};for(const k of ['town','daniel','economy','notice'])if(!s.v31[k]||typeof s.v31[k]!=='object'||Array.isArray(s.v31[k]))s.v31[k]={};return s.v31}
function v31Summary(st){return{version:st.version,day:st.day,phase:st.phase,appointments:Object.keys(st.v14?.appointments||{}).length,treatments:Object.keys(st.v14?.treatments||{}).length,followups:Object.keys(st.v15?.followups||{}).length,coins:st.coins,supplies:st.supplies}}
function v31Validate(st){const errors=[];if(!st||typeof st!=='object'||Array.isArray(st))return ['저장 데이터는 객체여야 합니다.'];if(st.version!==2)errors.push('version: 2가 아닙니다.');if(!Number.isInteger(st.day)||st.day<1)errors.push('날짜가 올바르지 않습니다.');if(!Number.isInteger(st.phase)||st.phase<0||st.phase>3)errors.push('시간대가 올바르지 않습니다.');if(!st.flags||typeof st.flags!=='object'||Array.isArray(st.flags))errors.push('flags 형식 오류');if(!Array.isArray(st.records))errors.push('records 형식 오류');for(const [key,ap] of Object.entries(st.v14?.appointments||{})){if(!ap||typeof ap!=='object')errors.push(key+' 예약 형식 오류');else if(!Number.isInteger(ap.phase)||ap.phase<0||ap.phase>3)errors.push(key+' 예약 시간 오류')}return errors}
function v31Compare(old,now){return{old:v31Summary(old),current:v31Summary(now),older:old.day<now.day,issues:v31Validate(old),legacy:!old.v31}}
function v31ClinicAudit(st){const a=st.v14?.appointments||{},t=st.v14?.treatments||{},f=st.v15?.followups||{},issues=[];for(const [key,ap] of Object.entries(a)){if(!ap||typeof ap!=='object')continue;if(t[key]&&ap.status!=='completed')issues.push(key+' 완료 상태 불일치');if(!t[key]&&ap.status==='completed')issues.push(key+' 진료 기록 없이 완료');if(ap.day>st.day&&ap.status==='completed')issues.push(key+' 미래 예약 완료');}for(const [key,x] of Object.entries(f))if(x&&(!Number.isFinite(x.due)||x.due<0))issues.push(key+' 재방문 날짜 오류');return issues}
function v31Panel(title,description){const el=document.createElement('section');el.className='v31-panel';const h=document.createElement('h3');h.textContent=title;el.appendChild(h);if(description){const p=document.createElement('p');p.textContent=description;el.appendChild(p)}return el}
