function v31Clinic(){const el=v31Page('🩺 v3.1 장기 진료 진단'),issues=v31ClinicAudit(s),c=v31Panel('실제 저장 상태',`예약 ${Object.keys(s.v14?.appointments||{}).length}건 · 진료 ${Object.keys(s.v14?.treatments||{}).length}건 · 재방문 ${Object.keys(s.v15?.followups||{}).length}건`);v31Line(c,issues.length?issues.join('\n'):'현재 확인된 상태 불일치 없음');v31Actions(c,[['기존 진료 화면',()=>move('v30flow')],['승인형 복구',()=>move('v30save')],['다음 시간대로',()=>next()]]);el.appendChild(c)}
function v31Storage(){const el=v31Page('🛡️ v3.1 저장 영속성·구버전 비교'),c=v31Panel('현재 저장소 점검','브라우저에 저장된 값과 현재 메모리의 날짜를 비교합니다.');let raw=null;try{raw=localStorage.getItem(KEY);const stored=raw?JSON.parse(raw):null;v31Line(c,stored?`저장 키: ${KEY}\n현재 ${s.day}일 차 / 저장 ${stored.day}일 차\n버전 ${stored.version}\n오류 ${v31Validate(stored).length}건`:'아직 저장된 기록이 없습니다.')}catch(e){v31Line(c,'저장소 읽기 실패: '+e.message)}v31Actions(c,[['현재 상태 저장',()=>{save(false);v31Storage()}],['기존 백업·복원',()=>move('v20backup')]]);el.appendChild(c);const b=v31Panel('구버전 JSON 읽기 전용 비교','파일을 불러와도 게임 상태는 변경되지 않습니다.');const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.setAttribute('aria-label','비교할 구버전 JSON 파일');b.appendChild(input);const out=v31Line(b,'JSON 백업을 선택해 주세요.');v31Actions(b,[['차이 확인',async()=>{try{const file=input.files?.[0];if(!file)throw Error('파일을 선택해 주세요.');if(file.size>2000000)throw Error('파일이 2MB를 초과합니다.');const old=JSON.parse(await file.text()),cmp=v31Compare(old,s);out.textContent=`이전 형식: ${cmp.legacy?'예':'아니요'}\n검증: ${cmp.issues.length?cmp.issues.join(', '):'정상'}\n백업: ${JSON.stringify(cmp.old)}\n현재: ${JSON.stringify(cmp.current)}\n백업이 더 오래됨: ${cmp.older?'예':'아니요'}`;}catch(e){out.textContent='비교 실패: '+e.message}}]]);el.appendChild(b)}
function v31EconomyPlan(st,history,id){if(history[String(st.day)])return{ok:false,reason:'오늘 이미 선택했습니다.'};const supply=Math.max(0,Number(st.supplies)||0),coins=Math.max(0,Number(st.coins)||0);const plans={buy:{title:'물자 구매',ds:Math.min(3,Math.max(0,30-supply)),dc:-4},share:{title:'이웃에게 물자 나누기',ds:-2,dc:0},repair:{title:'장비 정비',ds:-1,dc:0}};const p=plans[id];if(!p)return{ok:false,reason:'잘못된 선택'};if(id==='buy'&&(coins<4||supply>=30))return{ok:false,reason:'자금 부족 또는 재고 상한'};if(id==='share'&&supply<2||id==='repair'&&supply<1)return{ok:false,reason:'물자 부족'};return{ok:true,...p}}
function v31Economy(){const v=v31Ensure(),el=v31Page('⚖️ v3.1 운영 균형'),c=v31Panel('하루 한 번의 선택',`물자 ${s.supplies}/30 · 보유금 ${s.coins} · 날짜 ${s.day}`);for(const id of ['buy','share','repair']){const p=v31EconomyPlan(s,v.economy,id);v31Actions(c,[[p.title||id,()=>{const x=v31EconomyPlan(s,v.economy,id);if(!x.ok)return;const before={coins:s.coins,supplies:s.supplies};modify({coins:x.dc,supplies:x.ds,...(id==='share'?{trust:1}:id==='repair'?{tired:-1}:{})});v.economy[String(s.day)]={id,before,after:{coins:s.coins,supplies:s.supplies}};save(false);v31Economy()},!p.ok]])}for(const [day,item] of Object.entries(v.economy).slice(-10).reverse())v31Line(c,`${day}일: ${item.id} · 물자 ${item.before.supplies} → ${item.after.supplies} · 보유금 ${item.before.coins} → ${item.after.coins}`);el.appendChild(c)}
const v31Town=[['umbrella','우산이 너무 많은 날','우산 수집가가 진료소 문 앞에 우산을 여섯 개 펼쳤다. 비는 오지 않았다. 미겔은 잠시 보다가 말했다. “진료소 입구만 비워 주세요.”',3],['cactus','선인장과 눈싸움','선인장을 의심하던 주민은 오늘도 선인장을 바라봤다. “오늘은 먼저 눈을 피했어요.” 미겔은 차트를 덮었다. “그건 다행이군요.”',5],['radio','라디오의 건강 상담','라디오 수리공은 건강 상담 방송을 열겠다고 했다. 미겔은 잘못된 정보를 퍼뜨리지 않는다는 조건으로 짧은 안내문을 건넸다.',7],['teapot','주전자 장인의 작은 소동','주전자 장인이 진료소에 주전자를 세 개 가져왔다. 차를 마시러 온 노인이 가장 작은 주전자를 골랐다. 그날은 진료소가 조금 시끌벅적했다.',9]];
const v31Daniel=[['postcard','도착하지 않은 엽서','다니엘이 보낸 엽서는 늦게 도착했다. 미겔은 글씨보다 먼저 종이의 접힌 모서리를 만졌다. “D, 이번엔 좀 늦었네.”',3],['chess','양보 없는 수','휴가 중 체스판 앞에 앉은 다니엘을 향해 미겔은 망설임 없이 말을 움직였다. 승부는 승부였다. 그녀는 일부러 져 주지 않았다.',5],['call','근무가 끝난 뒤','통화 너머에서 익숙한 목소리가 들렸다. “코트리먼.” 미겔은 의자를 끌어 앉았다. “응, D.” 두 사람은 각자의 하루를 짧게 나누었다.',7],['visit','잠깐의 휴가','다니엘의 짧은 휴가가 끝나갈 무렵, 미겔은 진료소 문을 닫고 함께 골목을 걸었다. 다음 만남을 약속하는 대신 오늘의 시간을 조금 더 오래 썼다.',9]];
function v31Stories(dan){const v=v31Ensure(),el=v31Page(dan?'💜 다니엘과 미겔':'🏘️ 정착촌 코미디'),store=dan?v.daniel:v.town;v31Line(el,'[게임 확장] 신규 사건과 대사는 원작 확정 설정이 아닙니다.');for(const [id,title,story,day] of dan?v31Daniel:v31Town){const c=v31Panel(title,store[id]?story:s.day>=day?'읽을 수 있습니다.':`${day}일 차에 개방됩니다.`);v31Actions(c,[['읽기',()=>{if(store[id]||s.day<day)return;store[id]={day:s.day};modify({peace:1});save(false);v31Stories(dan)},!!store[id]||s.day<day]]);el.appendChild(c)}}
