function v32Ensure(){if(!s.v32||typeof s.v32!=='object'||Array.isArray(s.v32))s.v32={};for(const k of ['town','daniel','economy','diagnostics'])if(!s.v32[k]||typeof s.v32[k]!=='object'||Array.isArray(s.v32[k]))s.v32[k]={};return s.v32}
function v32Audit(st){const issues=[];const aps=st.v14?.appointments||{},trs=st.v14?.treatments||{},queue=st.v15?.queue||{};for(const [key,ap] of Object.entries(aps)){if(!ap||!Number.isInteger(ap.phase)||ap.phase<0||ap.phase>3){issues.push(key+': 예약 시간 오류');continue}if(trs[key]&&ap.status!=='completed')issues.push(key+': 진료 완료와 예약 상태 불일치');if(!trs[key]&&ap.status==='completed')issues.push(key+': 진료 기록 없는 완료 상태');if(ap.status==='checked-in'&&!queue[key]?.checkedIn)issues.push(key+': 접수 대기열 누락')}for(const [key,tr] of Object.entries(trs)){if(!tr||typeof tr!=='object')issues.push(key+': 진료 데이터 오류')}return issues}
