function v33Ensure(){if(!s.v33||typeof s.v33!=='object'||Array.isArray(s.v33))s.v33={};for(const k of ['town','daniel','ledger'])if(!s.v33[k]||typeof s.v33[k]!=='object'||Array.isArray(s.v33[k]))s.v33[k]={};return s.v33}
function v33Snapshot(st){return{version:st.version,day:st.day,phase:st.phase,appointments:Object.keys(st.v14?.appointments||{}).length,treatments:Object.keys(st.v14?.treatments||{}).length,followups:Object.keys(st.v15?.followups||{}).length,coins:st.coins,supplies:st.supplies}}
function v33Audit(st){const errors=[],a=st.v14?.appointments||{},t=st.v14?.treatments||{},q=st.v15?.queue||{},f=st.v15?.followups||{};for(const [key,ap] of Object.entries(a)){if(!ap||!Number.isInteger(ap.phase)||ap.phase<0||ap.phase>3){errors.push(key+': 예약 시간 오류');continue}if(ap.status==='completed'&&!t[key])errors.push(key+': 완료 상태에 진료 기록 없음');if(t[key]&&ap.status!=='completed')errors.push(key+': 진료 기록과 예약 상태 불일치');if(ap.status==='checked-in'&&!q[key]?.checkedIn)errors.push(key+': 접수 대기열 불일치')}for(const [id,item] of Object.entries(f))if(!item||!Number.isFinite(item.due)||item.due<0)errors.push(id+': 재방문 날짜 오류');return [...new Set(errors)]}
function v33Compare(candidate){const issues=v21Validate(candidate);return{valid:!issues.length,issues,current:v33Snapshot(s),backup:v33Snapshot(candidate),changes:Object.keys(candidate).filter(k=>JSON.stringify(candidate[k])!==JSON.stringify(s[k])).slice(0,40)}}
function v33EconomyPlan(st,ledger,id){if(ledger[String(st.day)])return{ok:false,reason:'오늘 운영 완료'};const supply=Number(st.supplies)||0,coins=Number(st.coins)||0;const plans={purchase:{title:'의료 물자 공동구매',dc:-3,ds:Math.min(3,30-supply)},share:{title:'이웃과 물자 나눔',dc:0,ds:-2},repair:{title:'진료 도구 정비',dc:-1,ds:-1}};const p=plans[id];if(!p)return{ok:false,reason:'잘못된 선택'};if(coins+p.dc<0||supply+p.ds<0||supply+p.ds>30||(id==='purchase'&&supply>=30))return{ok:false,reason:'자금·재고 부족 또는 상한'};return{ok:true,...p}}
