function v33Save(){const el=v33Page('🛡️ v3.3 브라우저 저장·복원 검사'),c=v33Card(el,'실제 저장 상태','저장 후 새로고침해 날짜와 진료 건수가 동일한지 확인하세요.'),out=document.createElement('pre');out.className='v33-report';c.appendChild(out);function refresh(){try{const raw=localStorage.getItem(KEY),saved=raw?JSON.parse(raw):null;out.textContent=JSON.stringify({key:KEY,current:v33Snapshot(s),stored:saved?v33Snapshot(saved):null,valid:saved?v21Validate(saved):['저장 데이터 없음']},null,2)}catch(e){out.textContent='저장소 접근 실패: '+e.message}}refresh();v33Btn(c,'지금 저장',()=>{save(false);refresh()});v33Btn(c,'새로고침',()=>location.reload());const d=v33Card(el,'과거 세이브 비교','파일을 읽어 비교만 수행합니다. 현재 진행 데이터는 변경되지 않습니다.'),file=document.createElement('input'),res=document.createElement('pre');file.type='file';file.accept='.json,application/json';file.setAttribute('aria-label','과거 저장 파일 선택');res.className='v33-report';d.append(file,res);v33Btn(d,'선택한 JSON 검사',async()=>{try{const f=file.files?.[0];if(!f)throw Error('JSON 파일을 선택하세요');if(f.size>2000000)throw Error('2MB 제한');const old=JSON.parse(await f.text());res.textContent=JSON.stringify(v33Compare(old),null,2)}catch(e){res.textContent=e.message}});v33Btn(d,'기존 안전 복원 메뉴',()=>move('v21recovery'))}
