function v33Regression(){const r=[],test=(n,f)=>{try{if(!f())throw Error('조건 불일치');r.push({name:n,pass:true})}catch(e){r.push({name:n,pass:false,error:String(e)})}};const mk=()=>({version:2,day:4,phase:1,flags:{},records:[],messages:[],eventsSeen:[],coins:12,supplies:8,v14:{appointments:{cactus_4:{day:4,phase:1,status:'reserved'}},treatments:{}},v15:{queue:{},followups:{}}});test('저장 키',()=>KEY==='miguel_clinic_v02');test('버전2 검증',()=>v21Validate(mk()).length===0);test('과거 필드 보존',()=>!('v33' in mk()));test('정상 예약',()=>v33Audit(mk()).length===0);test('예약 시간 오류',()=>{const x=mk();x.v14.appointments.cactus_4.phase=9;return v33Audit(x).length===1});test('진료 완료 불일치',()=>{const x=mk();x.v14.appointments.cactus_4.status='completed';return v33Audit(x).length===1});test('접수 대기열 누락',()=>{const x=mk();x.v14.appointments.cactus_4.status='checked-in';return v33Audit(x).length===1});test('접수 대기열 일치',()=>{const x=mk();x.v14.appointments.cactus_4.status='checked-in';x.v15.queue.cactus_4={checkedIn:true};return !v33Audit(x).length});test('재방문 오류',()=>{const x=mk();x.v15.followups.cactus={due:-1};return v33Audit(x).length===1});test('중복 진료 차단',()=>{const x=mk();x.v14.treatments.cactus_4={};return !v29Eligible(x,'cactus_4')});test('진료 함수',()=>typeof v14Treat==='function');test('접수 함수',()=>typeof v29Reconcile==='function');test('비파괴 스냅샷',()=>{const x=mk(),before=JSON.stringify(x);v33Snapshot(x);return JSON.stringify(x)===before});test('물자 구매',()=>v33EconomyPlan(mk(),{},'purchase').ok);test('물자 부족',()=>!v33EconomyPlan({...mk(),supplies:0},{},'share').ok);test('자금 부족',()=>!v33EconomyPlan({...mk(),coins:0},{},'purchase').ok);test('재고 상한',()=>!v33EconomyPlan({...mk(),supplies:30},{},'purchase').ok);test('하루 중복 운영',()=>!v33EconomyPlan(mk(),{'4':{}},'purchase').ok);test('구매 재고 제한',()=>v33EconomyPlan({...mk(),supplies:29},{},'purchase').ds===1);test('백업 검증 함수',()=>typeof v21Validate==='function');return r}
