function v34SaveUI(){const el=v34Page('🛡️ v3.4 저장 영속성 확인','실제 localStorage를 사용합니다. 새로고침 확인은 사용자의 브라우저에서만 최종 확인할 수 있습니다.');const c=v34Panel(el,'저장 상태와 일치 여부');const pre=document.createElement('pre');c.appendChild(pre);function report(){const stored=v34ReadSaved();pre.textContent=JSON.stringify({key:KEY,current:v34Digest(s),stored:stored.ok?v34Digest(stored.data):null,valid:stored.ok,issues:stored.errors||stored.error||[],equal:stored.ok&&JSON.stringify(v34Digest(s))===JSON.stringify(v34Digest(stored.data))},null,2)}report();v34Actions(c,[['지금 저장하고 비교',()=>{save(false);report()}],['새로고침하여 확인',()=>{save(false);location.reload()}],['기존 안전 복원',()=>move('v21recovery')]]);const old=v34Panel(el,'과거 저장 호환성','과거 JSON을 검사한 뒤 기존 안전 복원 화면에서 복원하세요. 검사만으로 현재 저장은 변경되지 않습니다.');const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.setAttribute('aria-label','과거 저장 JSON 선택');const result=document.createElement('pre');old.append(input,result);v34Actions(old,[['JSON 검증',async()=>{try{const file=input.files?.[0];if(!file)throw Error('JSON 파일을 선택해 주세요');if(file.size>2000000)throw Error('파일은 2MB 이하여야 합니다');const candidate=JSON.parse(await file.text()),errors=v21Validate(candidate);result.textContent=JSON.stringify({valid:!errors.length,errors,backup:v34Digest(candidate),current:v34Digest(s),warning:'이 화면에서는 복원하지 않습니다.'},null,2)}catch(e){result.textContent='검증 실패: '+e.message}}]]);const diag=v34Panel(el,'진료 기록 일관성');const errors=v34Consistency(s);diag.appendChild(v14Text('p',errors.length?errors.join(' / '):'현재 진료 기록의 구조적 불일치가 없습니다.'))}
function v34EconomyPlan(st,ledger,id){if(ledger[String(st.day)])return{ok:false,reason:'오늘 이미 운영했습니다'};const supplies=Number(st.supplies),coins=Number(st.coins);if(!Number.isFinite(supplies)||!Number.isFinite(coins)||supplies<0||coins<0)return{ok:false,reason:'자원 데이터 오류'};const opts={purchase:{title:'공동 물품 구매',coins:-4,supplies:Math.min(4,Math.max(0,30-supplies))},share:{title:'이웃에 물품 전달',coins:1,supplies:-2},maintain:{title:'장비 점검',coins:-1,supplies:-1}};const a=opts[id];if(!a)return{ok:false,reason:'알 수 없는 운영'};if(id==='purchase'&&a.supplies===0)return{ok:false,reason:'물자 상한 도달'};if(coins+a.coins<0||supplies+a.supplies<0||supplies+a.supplies>30)return{ok:false,reason:'자금·물자 부족'};return{ok:true,...a}}
