const v34Residents=[['teacup','찻잔 분실 사건','할머니가 찻잔을 잃어버렸다고 소리쳤다. 모자 장수가 자신의 모자에서 찻잔을 발견했다. 미겔은 진료소 대기실에 분실물 상자를 마련했다.',6],['cactus','선인장에게 보낸 편지','선인장 환자가 화분에 사과 편지를 붙였다. 다음 날 화분에는 답장이 없었다. 미겔은 조용히 편지에 물이 닿지 않게 옮겼다.',11],['umbrella','양산의 출근부','양산 수집가는 모든 양산에 이름표를 붙였다. 그런데 이름표를 잘못 붙여 대여소에 혼란이 생겼다. 미겔은 숫자부터 다시 매기자고 했다.',16],['radio','라디오 속 건강 퀴즈','라디오 수리공이 건강 퀴즈를 냈다. “잠은 왜 잘까요?” 수면 부족 청년이 외쳤다. “게임을 더 오래 하려고요!” 미겔은 라디오를 껐다.',21]];
const v34Daniel=[['postcard','접힌 엽서','미겔은 D에게 보내는 엽서에 정착촌의 날씨를 적었다. 거창한 문장은 없었다. “오늘도 무사해.” 그것이면 충분했다.',6],['chess','승부를 미루지 않는 사람','다니엘이 휴가를 오면 체스판을 꺼낼 생각이었다. 미겔은 수순을 정리했다. 누구를 상대하든 일부러 져 줄 생각은 없었다.',11],['voice','짧은 통화','“코트리먼.” 익숙한 목소리가 들리자 미겔은 손에 쥔 연필을 내려놓았다. “응, D.” 그날의 평범한 일들을 나눴다.',16],['leave','휴가의 저녁','짧은 휴가에 정착촌을 찾은 다니엘과 미겔은 조용히 저녁을 먹었다. 다음 날에는 다시 각자의 일상이 기다리고 있었다.',21]];
function v34Stories(dan){const v=v34Ensure(),el=v34Page(dan?'💜 v3.4 다니엘 일상':'🏘️ v3.4 주민 후일담','[게임 확장] 원작 확정 사건이 아닌 신규 창작입니다. 다니엘은 현역 군인이고, 미겔과 따로 생활합니다.');const list=dan?v34Daniel:v34Residents,store=dan?v.daniel:v.residents;for(const [id,title,story,day] of list){const seen=!!store[id],c=v34Panel(el,title,seen?story:s.day>=day?'새로운 이야기를 읽을 수 있습니다.':`${day}일 차부터 열립니다.`);v34Actions(c,[['이야기 읽기',()=>{if(store[id]||s.day<day||s.story!=='free')return;store[id]={day:s.day};modify({peace:1});save(false);v34Stories(dan)},seen||s.day<day||s.story!=='free']])}}
function v34Regression(){const r=[],test=(name,fn)=>{try{if(!fn())throw Error('조건 불일치');r.push({name,pass:true})}catch(e){r.push({name,pass:false,error:String(e)})}};const sample=()=>({version:2,day:6,phase:1,story:'free',flags:{},records:[],eventsSeen:[],messages:[],coins:20,supplies:9,v14:{appointments:{cactus_6:{day:6,phase:1,status:'reserved'}},treatments:{}},v15:{queue:{},followups:{}}});test('저장 키 호환',()=>KEY==='miguel_clinic_v02');test('version 2 유지',()=>init().version===2);test('구버전 기본 형식',()=>v21Validate(sample()).length===0);test('구버전 신규 필드 미필수',()=>!('v34' in sample()));test('기본 예약',()=>v34Consistency(sample()).length===0);test('완료 기록 누락',()=>{const x=sample();x.v14.appointments.cactus_6.status='completed';return v34Consistency(x).length>0});test('진료 중복 차단',()=>{const x=sample();x.v14.treatments.cactus_6={day:6};return !v29Eligible(x,'cactus_6')});test('진료 날짜 불일치',()=>{const x=sample();x.v14.treatments.cactus_6={day:5};x.v14.appointments.cactus_6.status='completed';return v34Consistency(x).length>0});test('접수 기록 불일치',()=>{const x=sample();x.v14.appointments.cactus_6.status='checked-in';return v34Consistency(x).length>0});test('비파괴 검사',()=>{const x=sample(),before=JSON.stringify(x);v34Consistency(x);return before===JSON.stringify(x)});test('경제 구매',()=>v34EconomyPlan(sample(),{},'purchase').ok);test('물자 상한',()=>!v34EconomyPlan({...sample(),supplies:30},{},'purchase').ok);test('잔액 부족',()=>!v34EconomyPlan({...sample(),coins:0},{},'purchase').ok);test('나눔 물자 부족',()=>!v34EconomyPlan({...sample(),supplies:0},{},'share').ok);test('하루 중복 운영',()=>!v34EconomyPlan(sample(),{'6':{}},'purchase').ok);test('상한 직전 구매',()=>v34EconomyPlan({...sample(),supplies:29},{},'purchase').supplies===1);test('일상 콘텐츠 주민 4',()=>v34Residents.length===4);test('일상 콘텐츠 다니엘 4',()=>v34Daniel.length===4);test('저장 구조 검증 함수',()=>typeof v21Validate==='function');test('예약 자동 접수 함수',()=>typeof v29Reconcile==='function');return r}
function v34Tests(){const el=v34Page('🧪 v3.4 회귀 검사','격리 데이터 검사이며 실제 브라우저 저장 복원 검사와는 별도입니다.'),results=v34Regression(),c=v34Panel(el,'검사 결과',`${results.filter(x=>x.pass).length}/${results.length} 통과`),p=document.createElement('pre');p.textContent=results.map(x=>(x.pass?'✓ ':'✗ ')+x.name+(x.error?' '+x.error:'')).join('\n');c.appendChild(p)}
const v34PrevRender=render;render=function(){v34Ensure();v34PrevRender();const pages={v34save:v34SaveUI,v34economy:v34Economy,v34town:()=>v34Stories(false),v34daniel:()=>v34Stories(true),v34tests:v34Tests};if(pages[s.tab])pages[s.tab]()};
for(const [id,label] of [['v34save','🛡️ v3.4 저장'],['v34tests','🧪 v3.4 검사'],['v34economy','⚖️ v3.4 운영'],['v34town','🏘️ v3.4 주민'],['v34daniel','💜 v3.4 다니엘']])if(!document.querySelector(`[data-tab="${id}"]`)){const b=button(label,()=>move(id));b.dataset.tab=id;document.querySelector('nav.tabs').insertBefore(b,document.querySelector('[data-tab="updates"]'))}
v34Ensure();render();

